    private void LoadPendingPatchPreviewIfNeeded()
    {
        if (_pendingPatchPreviewLoaded)
        {
            return;
        }

        _pendingPatchPreviewLoaded = true;
        if (!File.Exists(_pendingPatchPreviewPath))
        {
            return;
        }

        try
        {
            using var stream = File.OpenRead(_pendingPatchPreviewPath);
            var request = JsonSerializer.Deserialize<CodingToolRequest>(stream, RoadmapJsonOptions);
            _lastPatchPreviewRequest = request?.Action is CodingToolAction.PreviewReplaceText or CodingToolAction.PreviewPatchBundle
                ? request
                : null;
        }
        catch (IOException)
        {
            _lastPatchPreviewRequest = null;
        }
        catch (UnauthorizedAccessException)
        {
            _lastPatchPreviewRequest = null;
        }
        catch (JsonException)
        {
            _lastPatchPreviewRequest = null;
        }
    }

    private void SavePendingPatchPreview()
    {
        _pendingPatchPreviewLoaded = true;
        if (_lastPatchPreviewRequest is null)
        {
            if (File.Exists(_pendingPatchPreviewPath))
            {
                File.Delete(_pendingPatchPreviewPath);
            }

            return;
        }

        Directory.CreateDirectory(Path.GetDirectoryName(_pendingPatchPreviewPath)!);
        using var stream = File.Create(_pendingPatchPreviewPath);
        JsonSerializer.Serialize(stream, _lastPatchPreviewRequest, RoadmapJsonOptions);
    }
    public async Task<CodingToolResult> TryHandleAsync(
        string userText,
        CancellationToken cancellationToken)
    {
        if (!CodingToolRequestParser.TryParse(userText, out var request))
        {
            return CodingToolResult.NotHandled;
        }

        cancellationToken.ThrowIfCancellationRequested();
        var permission = Policy.Evaluate(request);
        if (permission.Kind == CodingToolPermissionKind.Deny)
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding tool blocked: {permission.Reason}");
        }

        if (permission.Kind == CodingToolPermissionKind.RequireConfirmation)
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding tool needs confirmation: {permission.Reason}");
        }

        var result = request.Action switch
        {
            CodingToolAction.OpenWorkspace => await OpenWorkspaceAsync(cancellationToken).ConfigureAwait(false),
            CodingToolAction.ListWorkspace => ListWorkspace(),
            CodingToolAction.InspectWorkspace => InspectWorkspace(),
            CodingToolAction.AnalyzeArchitecture => AnalyzeArchitecture(),
            CodingToolAction.ShowProjectIntelligence => ShowProjectIntelligence(),
            CodingToolAction.ShowProjectIndex => await ShowProjectIndexAsync(cancellationToken).ConfigureAwait(false),
            CodingToolAction.ShowProjectDependencyMap => ShowProjectDependencyMap(request),
            CodingToolAction.ShowRepoUnderstanding => await ShowRepoUnderstandingAsync(cancellationToken).ConfigureAwait(false),
            CodingToolAction.ShowCodingContextPacket => await ShowCodingContextPacketAsync(request, cancellationToken).ConfigureAwait(false),
