        }

        lines.Add(string.Empty);
        lines.Add("Next Safe Commands");
        lines.Add("- inspect coding workspace");
        lines.Add("- analyze solution architecture");
        lines.Add("- plan coding task <goal>");
        lines.Add("- draft implementation roadmap <goal>");
