        lines.Add("- run packet item 1");
        lines.Add("- confirm run packet item N");
        lines.Add("- show packet ledger");
        lines.Add("- resume build plan");
        lines.Add("- plan package lookup <goal>");
        lines.Add("- preview project scaffold <goal>");
