    private CodingToolResult ListWorkspace()
    {
        if (!Directory.Exists(Policy.WorkspaceRoot))
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding workspace does not exist yet: {Policy.WorkspaceRoot}",
                "Workspace list",
                Policy.WorkspaceRoot);
        }

        var entries = Directory.EnumerateFileSystemEntries(Policy.WorkspaceRoot)
            .Where(path => !ShouldSkipPath(path))
            .OrderBy(path => Directory.Exists(path) ? 0 : 1)
            .ThenBy(path => Path.GetFileName(path), StringComparer.OrdinalIgnoreCase)
            .Take(MaxListedEntries + 1)
            .ToList();
        var listed = entries.Take(MaxListedEntries)
            .Select(path => Directory.Exists(path)
                ? $"[dir] {Path.GetFileName(path)}"
                : $"[file] {Path.GetFileName(path)}")
            .ToList();
        var truncated = entries.Count > MaxListedEntries
            ? $"{Environment.NewLine}...more entries omitted."
            : string.Empty;

        var body = listed.Count == 0
            ? "Workspace is empty."
            : string.Join(Environment.NewLine, listed);
        return new CodingToolResult(
            true,
            true,
            $"Coding workspace: {Policy.WorkspaceRoot}{Environment.NewLine}{body}{truncated}",
            "Workspace list",
            Policy.WorkspaceRoot);
    }

    private CodingToolResult InspectWorkspace()
    {
        if (!Directory.Exists(Policy.WorkspaceRoot))
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding workspace does not exist yet: {Policy.WorkspaceRoot}",
                "Workspace inspection",
                Policy.WorkspaceRoot);
        }

        var files = EnumerateWorkspaceFiles().Take(10_000).ToList();
        var solutions = files
            .Where(file => file.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
                           || file.EndsWith(".slnx", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var projects = files
            .Where(file => file.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var entryPoints = files
            .Where(IsLikelyEntryPoint)
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .Take(MaxWorkspaceSummaryEntries)
            .Select(RelativeToWorkspace)
            .ToList();
        var extensionCounts = files
            .Select(Path.GetExtension)
            .Where(extension => !string.IsNullOrWhiteSpace(extension))
            .GroupBy(extension => extension!, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .Select(group => $"{group.Key}: {group.Count()}")
            .ToList();

        var lines = new List<string>
        {
            $"Coding workspace inspection: {Policy.WorkspaceRoot}",
            $"Files scanned: {files.Count}",
            $"Solutions: {solutions.Count}",
            $"Projects: {projects.Count}"
        };

        AddPathSection(lines, "Solution files", solutions);
        AddProjectSection(lines, projects);
        if (entryPoints.Count > 0)
        {
            lines.Add("Likely entry/UI files:");
            lines.AddRange(entryPoints.Select(path => $"- {path}"));
        }

        if (extensionCounts.Count > 0)
        {
            lines.Add("Top file types:");
            lines.AddRange(extensionCounts.Select(item => $"- {item}"));
        }

        return new CodingToolResult(
            true,
            true,
            string.Join(Environment.NewLine, lines),
            "Workspace inspection",
            Policy.WorkspaceRoot);
    }

    private CodingToolResult AnalyzeArchitecture()
    {
        if (!Directory.Exists(Policy.WorkspaceRoot))
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding workspace does not exist yet: {Policy.WorkspaceRoot}",
                "Architecture analysis",
                Policy.WorkspaceRoot);
        }

        var files = EnumerateWorkspaceFiles().Take(10_000).ToList();
        var solutions = files
            .Where(file => file.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
                           || file.EndsWith(".slnx", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var projects = files
            .Where(file => file.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var summaries = projects
            .Take(MaxWorkspaceSummaryEntries)
            .Select(ReadProjectSummary)
            .ToList();

        var lines = new List<string>
        {
            $"Solution architecture analysis: {Policy.WorkspaceRoot}",
            "No files were changed.",
            $"Solutions found: {solutions.Count}",
            $"Projects found: {projects.Count}",
            $"Files scanned: {files.Count}"
        };

        AddPathSection(lines, "Solution files", solutions);
        if (summaries.Count > 0)
        {
            lines.Add("Project map:");
            foreach (var summary in summaries)
            {
                lines.Add($"- {summary.RelativePath}");
                lines.Add($"  Role: {summary.ProjectRole}");
                lines.Add(summary.TargetFrameworks.Count == 0
                    ? "  Targets: not declared"
                    : $"  Targets: {string.Join(", ", summary.TargetFrameworks)}");
                lines.Add($"  Source files: {summary.CSharpSourceCount} C#, {summary.XamlFileCount} XAML, {summary.JsonFileCount} JSON/config");

                if (summary.ProjectReferences.Count > 0)
                {
                    lines.Add($"  Project references: {string.Join(", ", summary.ProjectReferences.Take(8))}");
                    if (summary.ProjectReferences.Count > 8)
                    {
                        lines.Add($"  ...{summary.ProjectReferences.Count - 8} more project reference(s) omitted.");
                    }
                }
                else
                {
                    lines.Add("  Project references: none declared");
                }

                if (summary.PackageReferences.Count > 0)
                {
                    lines.Add($"  Package references: {string.Join(", ", summary.PackageReferences.Take(8))}");
                    if (summary.PackageReferences.Count > 8)
                    {
                        lines.Add($"  ...{summary.PackageReferences.Count - 8} more package reference(s) omitted.");
                    }
                }
                else
                {
                    lines.Add("  Package references: none declared");
                }

                if (!string.IsNullOrWhiteSpace(summary.Warning))
                {
                    lines.Add($"  Warning: {summary.Warning}");
                }
            }
        }

        AddArchitectureDependencySections(lines, summaries);

        if (projects.Count > MaxWorkspaceSummaryEntries)
        {
            lines.Add($"...{projects.Count - MaxWorkspaceSummaryEntries} more project file(s) omitted.");
        }

        lines.Add("Suggested guarded next steps:");
        lines.Add("- open solution");
        lines.Add("- list packages");
        lines.Add("- confirm dotnet build \"path\"");
        lines.Add("- diagnose last build failure");
        lines.Add("- generate coding report");

        return new CodingToolResult(
            true,
            true,
            string.Join(Environment.NewLine, lines),
            "Architecture analysis",
            Policy.WorkspaceRoot);
    }

    private CodingToolResult ShowProjectIntelligence()
    {
        if (!Directory.Exists(Policy.WorkspaceRoot))
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding workspace does not exist yet: {Policy.WorkspaceRoot}",
                "Project intelligence",
                Policy.WorkspaceRoot);
        }

        var files = EnumerateWorkspaceFiles().Take(10_000).ToList();
        var solutions = files
            .Where(file => file.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
                           || file.EndsWith(".slnx", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var projects = files
            .Where(file => file.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var summaries = projects
            .Take(MaxWorkspaceSummaryEntries)
            .Select(ReadProjectSummary)
            .ToList();
        var primaryTarget = TryFindPrimaryProjectOrSolution(Policy.WorkspaceRoot, out var primary)
            ? primary
            : null;
        var appProjects = summaries
            .Where(summary => summary.ProjectRole.Contains("app", StringComparison.OrdinalIgnoreCase))
            .Select(summary => summary.RelativePath)
            .ToList();
        var testProjects = summaries
            .Where(summary => summary.ProjectRole.Contains("test", StringComparison.OrdinalIgnoreCase))
            .Select(summary => summary.RelativePath)
            .ToList();
        var roleSummary = summaries.Count == 0
            ? "none"
            : string.Join(", ", summaries
                .GroupBy(summary => summary.ProjectRole, StringComparer.OrdinalIgnoreCase)
                .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                .Select(group => $"{group.Key}: {group.Count()}"));
        var markers = FindProjectMarkers(files);
        var entryFiles = files
            .Where(IsLikelyEntryPoint)
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .Select(RelativeToWorkspace)
            .ToList();
        var stackSignals = DetectStackSignals(files, summaries);
        var styleSignals = DetectStyleSignals(files, summaries);
        var buildCommands = DiscoverBuildCommands(files, summaries, primaryTarget).ToList();
        var testCommands = DiscoverTestCommands(files, summaries, primaryTarget).ToList();

        var lines = new List<string>
        {
            $"Project intelligence scan: {Policy.WorkspaceRoot}",
            "No files were changed.",
            $"Shape: {solutions.Count} solution(s), {projects.Count} .NET project(s), {files.Count} file(s) scanned.",
            $"Detected stacks: {FormatInlineList(stackSignals)}",
            $"Style signals: {FormatInlineList(styleSignals)}",
            $"Project roles: {roleSummary}",
            primaryTarget is null
                ? "Primary target: not found"
                : $"Primary target: {RelativeToWorkspace(primaryTarget)}"
        };

        AddCompactList(lines, "Likely app/host projects", appProjects);
        AddCompactList(lines, "Likely test projects", testProjects);
        AddCompactList(lines, "Important entry/config files", entryFiles);
        AddCompactList(lines, "Other project markers", markers);

        lines.Add("Recommended commands:");
        if (buildCommands.Count > 0)
        {
            foreach (var command in buildCommands.Take(4))
            {
                lines.Add($"- Build: {command}");
            }
        }
        else
        {
            lines.Add("- Build: choose a solution, project, package, or script target first.");
        }

        if (testCommands.Count > 0)
        {
            foreach (var command in testCommands.Take(4))
            {
                lines.Add($"- Tests: {command}");
            }
        }
        else
        {
            lines.Add("- Tests: no test command detected; add or identify tests before risky changes.");
        }

        lines.Add("- Review: review current changes");
        lines.Add("- Plan: plan coding task <goal>");
        lines.Add("Risk notes:");
        if (solutions.Count > 1)
        {
            lines.Add("- Multiple solutions found; choose the intended solution before build/test work.");
        }

        if (testProjects.Count == 0)
        {
            lines.Add("- No obvious test project found; prefer small edits plus manual validation notes.");
        }

        if (appProjects.Count == 0 && projects.Count > 0)
        {
            lines.Add("- No obvious app/host project found; this may be a library or support package.");
        }

        if (projects.Count == 0 && markers.Count == 0)
        {
            lines.Add("- No common project files found; inspect the workspace before planning edits.");
        }

        lines.Add("Next - Use Plan, Build, Tests, or Review from the Programming dashboard.");

        return new CodingToolResult(
            true,
            true,
            string.Join(Environment.NewLine, lines),
            "Project intelligence",
            Policy.WorkspaceRoot);
    }

    private ProjectIndexAwareness LoadProjectIndexAwareness()
    {
        var status = GetProjectIndexStatus();
        if (!File.Exists(_projectIndexPath))
        {
            return new ProjectIndexAwareness(false, status.Summary, null, [], [], [], [], [], [], [], [], [], [], [], [], [], [], []);
        }

        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(_projectIndexPath));
            var root = document.RootElement;
            var primaryTarget = root.TryGetProperty("primaryTarget", out var primaryElement)
                ? primaryElement.GetString()
                : null;
            return new ProjectIndexAwareness(
                status.Available,
                status.Summary,
                primaryTarget,
                ReadProjectIndexSymbolArray(root, "symbols"),
                ReadProjectIndexSummaryArray(root, "fileRoles", "role", "examples"),
                ReadProjectIndexSummaryArray(root, "featureAreas", "area", "representativeFiles"),
                ReadProjectDependencyArray(root, "projectDependencies"),
                ReadProjectStringArray(root, "projectBuildOrder"),
                ReadProjectStringArray(root, "generatedCode"),
                ReadProjectStringArray(root, "msBuildProjects"),
                ReadProjectStringArray(root, "publicApiSurface"),
                ReadProjectStringArray(root, "architectureSummary"),
                ReadProjectStringArray(root, "runtimeRoutes"),
                ReadProjectStringArray(root, "ownershipMap"),
                ReadProjectStringArray(root, "crossLanguageRoutes"),
                ReadProjectStringArray(root, "riskModel"),
                ReadProjectStringArray(root, "projectIntent"),
                ReadProjectStringArray(root, "compressedRepoMap"));
        }
        catch (JsonException ex)
        {
            return new ProjectIndexAwareness(false, $"Bad - unreadable project index: {TrimForChat(ex.Message, 240)}", null, [], [], [], [], [], [], [], [], [], [], [], [], [], [], []);
        }
        catch (IOException ex)
        {
            return new ProjectIndexAwareness(false, $"Bad - cannot read project index: {TrimForChat(ex.Message, 240)}", null, [], [], [], [], [], [], [], [], [], [], [], [], [], [], []);
        }
        catch (UnauthorizedAccessException ex)
        {
            return new ProjectIndexAwareness(false, $"Bad - cannot read project index: {TrimForChat(ex.Message, 240)}", null, [], [], [], [], [], [], [], [], [], [], [], [], [], [], []);
        }
    }

    private static IReadOnlyList<string> ReadProjectDependencyArray(JsonElement root, string propertyName)
    {
        if (!root.TryGetProperty(propertyName, out var element) || element.ValueKind != JsonValueKind.Array)
        {
            return [];
        }

        var dependencies = new List<string>();
        foreach (var item in element.EnumerateArray().Take(12))
        {
            var from = item.TryGetProperty("from", out var fromElement) ? fromElement.GetString() : null;
            var to = item.TryGetProperty("to", out var toElement) ? toElement.GetString() : null;
            if (!string.IsNullOrWhiteSpace(from) && !string.IsNullOrWhiteSpace(to))
            {
                dependencies.Add($"{from} -> {to}");
            }
        }

        return dependencies;
    }

    private static IReadOnlyList<string> ReadProjectStringArray(JsonElement root, string propertyName)
    {
        if (!root.TryGetProperty(propertyName, out var element) || element.ValueKind != JsonValueKind.Array)
        {
            return [];
        }

        return element
            .EnumerateArray()
            .Select(value => value.GetString())
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value!)
            .Take(12)
            .ToList();
    }

    private static IReadOnlyList<string> ReadProjectIndexSummaryArray(
        JsonElement root,
        string propertyName,
        string nameProperty,
        string examplesProperty)
    {
        if (!root.TryGetProperty(propertyName, out var element) || element.ValueKind != JsonValueKind.Array)
        {
            return [];
        }

        var summaries = new List<string>();
        foreach (var item in element.EnumerateArray().Take(8))
        {
            var name = item.TryGetProperty(nameProperty, out var nameElement)
                ? nameElement.GetString()
                : null;
            var count = item.TryGetProperty("count", out var countElement) && countElement.TryGetInt32(out var parsedCount)
                ? parsedCount
                : 0;
            var examples = item.TryGetProperty(examplesProperty, out var examplesElement) && examplesElement.ValueKind == JsonValueKind.Array
                ? examplesElement.EnumerateArray().Select(value => value.GetString()).Where(value => !string.IsNullOrWhiteSpace(value)).Take(3).ToList()
                : [];
            if (!string.IsNullOrWhiteSpace(name))
            {
                var exampleText = examples.Count == 0 ? string.Empty : $": {string.Join(", ", examples)}";
                summaries.Add($"{name} ({count}){exampleText}");
            }
        }

        return summaries;
    }

    private static IReadOnlyList<string> ReadProjectIndexSymbolArray(JsonElement root, string propertyName)
    {
        if (!root.TryGetProperty(propertyName, out var element) || element.ValueKind != JsonValueKind.Array)
        {
            return [];
        }

        var symbols = new List<string>();
        foreach (var item in element.EnumerateArray().Take(16))
        {
            var kind = item.TryGetProperty("kind", out var kindElement) ? kindElement.GetString() : null;
            var name = item.TryGetProperty("name", out var nameElement) ? nameElement.GetString() : null;
            var display = item.TryGetProperty("displayName", out var displayElement) ? displayElement.GetString() : null;
            var path = item.TryGetProperty("relativePath", out var pathElement) ? pathElement.GetString() : null;
            var line = item.TryGetProperty("lineNumber", out var lineElement) && lineElement.TryGetInt32(out var parsedLine)
                ? parsedLine
                : 0;
            if (!string.IsNullOrWhiteSpace(kind) && !string.IsNullOrWhiteSpace(name))
            {
                var symbolDisplay = string.IsNullOrWhiteSpace(display) ? name : display;
                var location = string.IsNullOrWhiteSpace(path) ? string.Empty : $" at {path}:{line}";
                symbols.Add($"{kind} {symbolDisplay}{location}");
            }
        }

        return symbols;
    }

    private static void AddProjectIndexAwarenessLines(List<string> lines, ProjectIndexAwareness awareness, int limit)
    {
        lines.Add("Codebase awareness map:");
        lines.Add($"- Project index: {awareness.Status}");
        if (!awareness.Available)
        {
            lines.Add("- Refresh action: project index");
        }
        lines.Add($"- Refresh automation: {FormatInlineList(BuildProjectIndexRefreshRows(new ProjectIndexStatus(awareness.Available, awareness.Status)).Take(3))}");
        if (!string.IsNullOrWhiteSpace(awareness.PrimaryTarget))
        {
            lines.Add($"- Primary target: {awareness.PrimaryTarget}");
        }

        lines.Add($"- Semantic symbols: {FormatInlineList(awareness.SemanticSymbols.Take(limit))}");
        lines.Add($"- File roles: {FormatInlineList(awareness.FileRoles.Take(limit))}");
        lines.Add($"- Feature areas: {FormatInlineList(awareness.FeatureAreas.Take(limit))}");
        lines.Add($"- Project dependencies: {FormatInlineList(awareness.ProjectDependencies.Take(limit))}");
        lines.Add($"- Project build order: {FormatInlineList(awareness.ProjectBuildOrder.Take(limit))}");
        lines.Add($"- Architecture summary: {FormatInlineList(awareness.ArchitectureSummary.Take(limit))}");
        lines.Add($"- MSBuild awareness: {FormatInlineList(awareness.MsBuildProjects.Take(limit))}");
        lines.Add($"- Generated/designer guardrails: {FormatInlineList(awareness.GeneratedCode.Take(limit))}");
        lines.Add($"- Public API surface: {FormatInlineList(awareness.PublicApiSurface.Take(limit))}");
        lines.Add($"- Runtime routes: {FormatInlineList(awareness.RuntimeRoutes.Take(limit))}");
        lines.Add($"- Ownership map: {FormatInlineList(awareness.OwnershipMap.Take(limit))}");
        lines.Add($"- Cross-language routes: {FormatInlineList(awareness.CrossLanguageRoutes.Take(limit))}");
        lines.Add($"- Risk model v2: {FormatInlineList(awareness.RiskModel.Take(limit))}");
        lines.Add($"- Project intent: {FormatInlineList(awareness.ProjectIntent.Take(limit))}");
        lines.Add($"- Compressed repo map: {FormatInlineList(awareness.CompressedRepoMap.Take(limit))}");
    }

    private IReadOnlyList<ProjectIndexFileRole> BuildProjectIndexFileRoles(IReadOnlyList<string> files) =>
        files
            .Select(RelativeToWorkspace)
            .GroupBy(ClassifyProjectIndexFileRole, StringComparer.OrdinalIgnoreCase)
            .Select(group => new ProjectIndexFileRole(
                group.Key,
                group.Count(),
                group.OrderBy(path => path, StringComparer.OrdinalIgnoreCase).Take(5).ToList()))
            .OrderByDescending(role => role.Count)
            .ThenBy(role => role.Role, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();

    private IReadOnlyList<ProjectIndexFeatureArea> BuildProjectIndexFeatureAreas(IReadOnlyList<string> files) =>
        files
            .Select(RelativeToWorkspace)
            .GroupBy(ClassifyProjectIndexFeatureArea, StringComparer.OrdinalIgnoreCase)
            .Select(group => new ProjectIndexFeatureArea(
                group.Key,
                group.Count(),
                group.OrderBy(path => path, StringComparer.OrdinalIgnoreCase).Take(5).ToList()))
            .OrderByDescending(area => area.Count)
            .ThenBy(area => area.Area, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();

    private static string FormatProjectIndexRoleSummary(IReadOnlyList<ProjectIndexFileRole> roles) =>
        roles.Count == 0
            ? "none detected"
            : string.Join(", ", roles.Take(6).Select(role => $"{role.Role} ({role.Count})"));

    private static string FormatProjectIndexFeatureSummary(IReadOnlyList<ProjectIndexFeatureArea> areas) =>
        areas.Count == 0
            ? "none detected"
            : string.Join(", ", areas.Take(6).Select(area => $"{area.Area} ({area.Count})"));

    private IReadOnlyList<string> BuildGeneratedCodeAwareness(IReadOnlyList<string> files)
    {
        var relativeFiles = files.Select(RelativeToWorkspace).ToList();
        var generated = relativeFiles
            .Where(IsGeneratedOrDesignerFile)
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        var projectSystem = relativeFiles
            .Where(path => NormalizePathForClassification(path).Contains("/obj/", StringComparison.OrdinalIgnoreCase)
                || NormalizePathForClassification(path).Contains("/bin/", StringComparison.OrdinalIgnoreCase)
                || NormalizePathForClassification(path).Contains("/.vs/", StringComparison.OrdinalIgnoreCase))
            .Take(5)
            .ToList();
        var migrations = relativeFiles
            .Where(path => NormalizePathForClassification(path).Contains("/migrations/", StringComparison.OrdinalIgnoreCase)
                || NormalizePathForClassification(path).Contains("/snapshots/", StringComparison.OrdinalIgnoreCase))
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .Take(5)
            .ToList();

        return
        [
            $"Generated/designer files: {generated.Count}",
            $"Generated examples: {FormatInlineList(generated)}",
            $"Migration/snapshot files: {migrations.Count}",
            $"Migration examples: {FormatInlineList(migrations)}",
            $"Ignored build output examples: {FormatInlineList(projectSystem)}",
            "Rule: generated, designer, migration, snapshot, bin, obj, and .vs files require explicit review before edits."
        ];
    }

    private IReadOnlyList<string> BuildMsBuildProjectAwareness(IReadOnlyList<string> projectFiles) =>
        projectFiles
            .Take(MaxWorkspaceSummaryEntries)
            .Select(ReadMsBuildProjectAwareness)
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value!)
            .ToList();

    private string? ReadMsBuildProjectAwareness(string projectFile)
    {
        try
        {
            var document = XDocument.Load(projectFile);
            var properties = new[]
                {
                    ("targets", ReadMsBuildPropertyList(document, "TargetFramework", "TargetFrameworks")),
                    ("rid", ReadMsBuildPropertyList(document, "RuntimeIdentifier", "RuntimeIdentifiers")),
                    ("output", ReadMsBuildPropertyList(document, "OutputType")),
                    ("wpf", ReadMsBuildPropertyList(document, "UseWPF")),
                    ("forms", ReadMsBuildPropertyList(document, "UseWindowsForms")),
                    ("nullable", ReadMsBuildPropertyList(document, "Nullable")),
                    ("implicit", ReadMsBuildPropertyList(document, "ImplicitUsings"))
                }
                .Where(pair => pair.Item2.Count > 0)
                .Select(pair => $"{pair.Item1}={string.Join("/", pair.Item2)}")
                .ToList();
            var packages = document.Descendants().Count(element => element.Name.LocalName == "PackageReference");
            var references = document.Descendants().Count(element => element.Name.LocalName == "ProjectReference");
            properties.Add($"packages={packages}");
            properties.Add($"projectRefs={references}");
            return $"{RelativeToWorkspace(projectFile)}: {string.Join(", ", properties)}";
        }
        catch (IOException ex)
        {
            return $"{RelativeToWorkspace(projectFile)}: unreadable - {TrimForChat(ex.Message, 120)}";
        }
        catch (UnauthorizedAccessException ex)
        {
            return $"{RelativeToWorkspace(projectFile)}: unreadable - {TrimForChat(ex.Message, 120)}";
        }
        catch (System.Xml.XmlException ex)
        {
            return $"{RelativeToWorkspace(projectFile)}: invalid XML - {TrimForChat(ex.Message, 120)}";
        }
    }

    private static IReadOnlyList<string> ReadMsBuildPropertyList(XDocument document, params string[] names) =>
        document
            .Descendants()
            .Where(element => names.Any(name => element.Name.LocalName.Equals(name, StringComparison.OrdinalIgnoreCase)))
            .SelectMany(element => SplitSemicolonList(element.Value))
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
            .ToList();

    private IReadOnlyList<string> BuildPublicApiSurface(IReadOnlyList<string> csharpFiles)
    {
        var surface = new List<string>();
        foreach (var file in csharpFiles.Where(File.Exists).Take(500))
        {
            if (surface.Count >= 80)
            {
                break;
            }

            var relativePath = RelativeToWorkspace(file);
            if (IsGeneratedOrDesignerFile(relativePath))
            {
                continue;
            }

            try
            {
                var tree = CSharpSyntaxTree.ParseText(File.ReadAllText(file), path: file);
                var root = tree.GetRoot();
                foreach (var member in root.DescendantNodes().OfType<MemberDeclarationSyntax>())
                {
                    if (surface.Count >= 80)
                    {
                        break;
                    }

                    var name = GetPublicApiMemberName(member);
                    if (string.IsNullOrWhiteSpace(name) || !LooksLikePublicApiMember(member))
                    {
                        continue;
                    }

                    var line = tree.GetLineSpan(member.Span).StartLinePosition.Line + 1;
                    surface.Add($"{GetPublicApiMemberKind(member)} {name} at {relativePath}:{line}");
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }

        return surface.Count == 0 ? ["none detected"] : surface;
    }

    private static bool LooksLikePublicApiMember(MemberDeclarationSyntax member)
    {
        var modifiers = member.Modifiers;
        return modifiers.Any(token => token.IsKind(SyntaxKind.PublicKeyword))
            || modifiers.Any(token => token.IsKind(SyntaxKind.ProtectedKeyword))
            || modifiers.Any(token => token.IsKind(SyntaxKind.InternalKeyword));
    }

    private static string? GetPublicApiMemberName(MemberDeclarationSyntax member) =>
        member switch
        {
            BaseTypeDeclarationSyntax type => type.Identifier.ValueText,
            MethodDeclarationSyntax method => method.Identifier.ValueText,
            PropertyDeclarationSyntax property => property.Identifier.ValueText,
            EventDeclarationSyntax eventDeclaration => eventDeclaration.Identifier.ValueText,
            FieldDeclarationSyntax field => field.Declaration.Variables.FirstOrDefault()?.Identifier.ValueText,
            ConstructorDeclarationSyntax constructor => constructor.Identifier.ValueText,
            _ => null
        };

    private static string GetPublicApiMemberKind(MemberDeclarationSyntax member) =>
        member switch
        {
            ClassDeclarationSyntax => "class",
            RecordDeclarationSyntax => "record",
            InterfaceDeclarationSyntax => "interface",
            EnumDeclarationSyntax => "enum",
            StructDeclarationSyntax => "struct",
            MethodDeclarationSyntax => "method",
            PropertyDeclarationSyntax => "property",
            EventDeclarationSyntax => "event",
            FieldDeclarationSyntax => "field",
            ConstructorDeclarationSyntax => "constructor",
            _ => "member"
        };

    private IReadOnlyList<string> BuildRepositoryArchitectureSummary(
        IReadOnlyList<string> files,
        IReadOnlyList<ProjectSummary> summaries,
        IReadOnlyList<string> msBuildProjects)
    {
        var roles = summaries
            .GroupBy(summary => summary.ProjectRole, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Select(group => $"{group.Key}={group.Count()}")
            .ToList();
        var relativeFiles = files.Select(RelativeToWorkspace).ToList();
        var featureAreas = BuildProjectIndexFeatureAreas(files);
        var entryFiles = relativeFiles.Where(path => IsLikelyEntryPoint(Path.Combine(Policy.WorkspaceRoot, path))).Take(6).ToList();
        return
        [
            $"Projects: {summaries.Count} ({FormatInlineList(roles)})",
            $"Feature areas: {FormatProjectIndexFeatureSummary(featureAreas)}",
            $"Entry points: {FormatInlineList(entryFiles)}",
            $"Desktop UI present: {FormatYesNo(relativeFiles.Any(path => path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase) || path.Contains("Ali.App.Wpf", StringComparison.OrdinalIgnoreCase)))}",
            $"Coding assistant layer present: {FormatYesNo(relativeFiles.Any(path => path.Contains("/Coding/", StringComparison.OrdinalIgnoreCase) || path.Contains("CodingTool", StringComparison.OrdinalIgnoreCase)))}",
            $"MSBuild projects mapped: {msBuildProjects.Count}"
        ];
    }

    private IReadOnlyList<string> BuildProjectIntentSignals(
        IReadOnlyList<string> files,
        IReadOnlyList<ProjectSummary> summaries,
        IReadOnlyList<string> stackSignals)
    {
        var relativeFiles = files.Select(RelativeToWorkspace).ToList();
        var appKinds = new List<string>();
        if (relativeFiles.Any(path => path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase))
            || summaries.Any(summary => summary.XamlFileCount > 0)
            || stackSignals.Any(signal => signal.Contains("WPF", StringComparison.OrdinalIgnoreCase)))
        {
            appKinds.Add("desktop app");
        }

        if (relativeFiles.Any(path => path.Contains("Controller", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Endpoint", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith("appsettings.json", StringComparison.OrdinalIgnoreCase)))
        {
            appKinds.Add("web/service surface");
        }

        if (summaries.Any(summary => summary.ProjectRole.Contains("test", StringComparison.OrdinalIgnoreCase))
            || relativeFiles.Any(path => path.StartsWith("tests/", StringComparison.OrdinalIgnoreCase)))
        {
            appKinds.Add("test suite");
        }

        if (relativeFiles.Any(path => path.Contains("Installer", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Installation", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Distributable", StringComparison.OrdinalIgnoreCase)))
        {
            appKinds.Add("installer/delivery package");
        }

        if (relativeFiles.Any(path => path.Contains("VisualStudio", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".vsixmanifest", StringComparison.OrdinalIgnoreCase)))
        {
            appKinds.Add("IDE extension/bridge");
        }

        if (appKinds.Count == 0 && summaries.Count > 0)
        {
            appKinds.Add("library/support codebase");
        }

        var primaryWorkflow = appKinds.Contains("desktop app")
            ? "build WPF app, validate coding/maintenance dashboards, then package installer"
            : appKinds.Contains("web/service surface")
                ? "build service, run tests, validate endpoint behavior"
                : "inspect project target, run focused tests, then build";

        return
        [
            $"Detected repo shape: {FormatInlineList(appKinds.Distinct(StringComparer.OrdinalIgnoreCase))}",
            $"Primary workflow: {primaryWorkflow}",
            $"Delivery surface: {FormatDeliverySurface(relativeFiles)}",
            $"Validation personality: {FormatValidationPersonality(summaries, relativeFiles)}",
            "Intent rule: decide app shape before choosing edit, build, test, and release commands."
        ];
    }

    private static string FormatDeliverySurface(IReadOnlyList<string> relativeFiles)
    {
        var surfaces = new List<string>();
        if (relativeFiles.Any(path => path.Contains("Ali.App.Wpf", StringComparison.OrdinalIgnoreCase)))
        {
            surfaces.Add("WPF client");
        }
        if (relativeFiles.Any(path => path.Contains("Installer", StringComparison.OrdinalIgnoreCase)))
        {
            surfaces.Add("installer");
        }
        if (relativeFiles.Any(path => path.Contains("VisualStudio", StringComparison.OrdinalIgnoreCase)))
        {
            surfaces.Add("Visual Studio bridge");
        }
        if (relativeFiles.Any(path => path.Contains("WebHelper", StringComparison.OrdinalIgnoreCase)))
        {
            surfaces.Add("local web helper");
        }

        return FormatInlineList(surfaces.Distinct(StringComparer.OrdinalIgnoreCase));
    }

    private static string FormatValidationPersonality(IReadOnlyList<ProjectSummary> summaries, IReadOnlyList<string> relativeFiles)
    {
        var hasTests = summaries.Any(summary => summary.ProjectRole.Contains("test", StringComparison.OrdinalIgnoreCase))
            || relativeFiles.Any(path => path.StartsWith("tests/", StringComparison.OrdinalIgnoreCase));
        var hasInstaller = relativeFiles.Any(path => path.Contains("Installer", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Installation", StringComparison.OrdinalIgnoreCase));
        var hasUi = relativeFiles.Any(path => path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase)
            || path.Contains("App.Wpf", StringComparison.OrdinalIgnoreCase));
        var cards = new List<string> { hasTests ? "targeted tests available" : "manual/build validation needed" };
        if (hasUi)
        {
            cards.Add("UI binding checks matter");
        }
        if (hasInstaller)
        {
            cards.Add("installer smoke checks matter");
        }

        return string.Join("; ", cards);
    }

    private IReadOnlyList<string> BuildCompressedRepoMap(
        IReadOnlyList<string> files,
        IReadOnlyList<ProjectSummary> summaries,
        IReadOnlyList<ProjectIndexFileRole> fileRoles,
        IReadOnlyList<ProjectIndexFeatureArea> featureAreas,
        IReadOnlyList<string> projectIntent,
        IReadOnlyList<string> buildCommands,
        IReadOnlyList<string> testCommands)
    {
        var entryFiles = files.Where(IsLikelyEntryPoint).Select(RelativeToWorkspace).Take(5).ToList();
        var dashboardFiles = files
            .Select(RelativeToWorkspace)
            .Where(path => path.Contains("Dashboard", StringComparison.OrdinalIgnoreCase)
                || path.Contains("MainWindow", StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(5)
            .ToList();
        return
        [
            $"Intent: {FormatInlineList(projectIntent.Take(3))}",
            $"Main projects: {FormatInlineList(summaries.Select(summary => summary.RelativePath).Take(6))}",
            $"Entry points: {FormatInlineList(entryFiles)}",
            $"Dashboards/UI: {FormatInlineList(dashboardFiles)}",
            $"Top file roles: {FormatProjectIndexRoleSummary(fileRoles)}",
            $"Top feature areas: {FormatProjectIndexFeatureSummary(featureAreas)}",
            $"Build first: {FormatInlineList(buildCommands.Take(3))}",
            $"Test first: {FormatInlineList(testCommands.Take(3))}"
        ];
    }
    private IReadOnlyList<SymbolOwnershipLedgerEntry> BuildDurableSymbolOwnershipLedger(IReadOnlyList<ProjectIndexSymbol> symbols) =>
        symbols
            .Where(symbol => !string.IsNullOrWhiteSpace(symbol.Name) && !string.IsNullOrWhiteSpace(symbol.RelativePath))
            .GroupBy(symbol => $"{symbol.Kind}|{symbol.DisplayName}|{symbol.RelativePath}|{symbol.LineNumber}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .OrderBy(symbol => symbol.ProjectPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(symbol => symbol.RelativePath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(symbol => symbol.LineNumber)
            .Take(500)
            .Select(symbol => new SymbolOwnershipLedgerEntry(
                symbol.DisplayName,
                symbol.Kind,
                string.IsNullOrWhiteSpace(symbol.Container) ? symbol.DisplayName : symbol.Container,
                symbol.RelativePath,
                symbol.ProjectPath,
                symbol.LineNumber,
                symbol.EndLineNumber,
                ClassifyFileRisk(symbol.RelativePath)))
            .ToList();

    private static IReadOnlyList<string> BuildDurableSymbolOwnershipLines(IReadOnlyList<SymbolOwnershipLedgerEntry> ledger) =>
        ledger.Count == 0
            ? ["none detected"]
            : ledger
                .Take(8)
                .Select(entry => $"{entry.Symbol} -> {entry.Owner} in {entry.RelativePath}:{entry.LineNumber} ({entry.Risk})")
                .ToList();

    private IReadOnlyList<string> BuildSymbolStalenessRows(IReadOnlyList<SymbolOwnershipLedgerEntry> ledger)
    {
        if (ledger.Count == 0)
        {
            return ["Good - no symbols were indexed yet"];
        }

        var staleRows = new List<string>();
        foreach (var entry in ledger.Take(120))
        {
            var absolutePath = ToAbsoluteWorkspacePath(entry.RelativePath);
            if (absolutePath is null || !File.Exists(absolutePath))
            {
                staleRows.Add($"Stale - {entry.Symbol}: missing file {entry.RelativePath}");
                continue;
            }

            var lines = SafeReadText(absolutePath).Split([Environment.NewLine, "\n"], StringSplitOptions.None);
            var index = Math.Clamp(entry.LineNumber - 1, 0, Math.Max(0, lines.Length - 1));
            var localWindow = lines
                .Skip(Math.Max(0, index - 2))
                .Take(5)
                .Any(line => line.Contains(entry.Symbol, StringComparison.Ordinal) || line.Contains(entry.Owner, StringComparison.Ordinal));
            if (!localWindow)
            {
                staleRows.Add($"Review - {entry.Symbol}: symbol moved or changed near {entry.RelativePath}:{entry.LineNumber}");
            }
        }

        return staleRows.Count == 0
            ? [$"Good - {ledger.Count} symbol ownership row(s) still match indexed files"]
            : staleRows.Take(12).ToList();
    }

