    private IReadOnlyList<string> BuildPersistentOwnershipMap(
        IReadOnlyList<ProjectIndexSymbol> symbols,
        IReadOnlyList<ProjectSummary> summaries,
        IReadOnlyList<string> files)
    {
        var lines = new List<string>();
        var projectSymbolCounts = symbols
            .Where(symbol => !string.IsNullOrWhiteSpace(symbol.ProjectPath))
            .GroupBy(symbol => symbol.ProjectPath, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .Select(group => $"{group.Key}: {group.Count()} symbol(s), {FormatInlineList(group.Select(symbol => symbol.DisplayName).Distinct(StringComparer.OrdinalIgnoreCase).Take(3))}")
            .ToList();
        lines.AddRange(projectSymbolCounts);

        var publicOwners = symbols
            .Where(symbol => symbol.Kind is "class" or "record" or "interface" or "method")
            .Where(symbol => !string.IsNullOrWhiteSpace(symbol.Container) || symbol.Kind is "class" or "record" or "interface")
            .Select(symbol =>
            {
                var owner = string.IsNullOrWhiteSpace(symbol.Container) ? symbol.DisplayName : symbol.Container;
                return $"{owner} owns {symbol.Name} ({symbol.ProjectPath})";
            })
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        lines.AddRange(publicOwners);

        var roleOwners = BuildProjectIndexFileRoles(files)
            .Take(6)
            .Select(role => $"{role.Role}: {role.Count} file(s), examples {FormatInlineList(role.Examples.Take(3))}")
            .ToList();
        lines.AddRange(roleOwners);

        if (summaries.Count > 0)
        {
            lines.AddRange(summaries
                .Take(6)
                .Select(summary => $"{summary.RelativePath}: {summary.ProjectRole}, refs {summary.ProjectReferences.Count}, packages {summary.PackageReferences.Count}"));
        }

        return lines.Count == 0 ? ["none detected"] : lines.Distinct(StringComparer.OrdinalIgnoreCase).Take(24).ToList();
    }

    private IReadOnlyList<string> BuildCrossLanguageRouteMap(IReadOnlyList<string> files)
    {
        var lines = new List<string>();
        var readableFiles = files
            .Where(LooksTextReadable)
            .Take(4_000)
            .ToList();
        var xamlCommands = readableFiles
            .Where(file => file.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase))
            .SelectMany(file => ExtractQuotedAttributeValues(file, "Command"))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(10)
            .ToList();
        var jsonKeys = readableFiles
            .Where(file => file.EndsWith(".json", StringComparison.OrdinalIgnoreCase))
            .SelectMany(ExtractTopLevelJsonKeys)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(10)
            .ToList();
        var projectLinks = readableFiles
            .Where(file => file.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))
            .SelectMany(file => ExtractProjectRouteHints(file))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(10)
            .ToList();
        var csharpRoutes = readableFiles
            .Where(file => file.EndsWith(".cs", StringComparison.OrdinalIgnoreCase))
            .Select(RelativeToWorkspace)
            .Where(path => path.Contains("Parser", StringComparison.OrdinalIgnoreCase)
                || path.Contains("Controller", StringComparison.OrdinalIgnoreCase)
                || path.Contains("Endpoint", StringComparison.OrdinalIgnoreCase)
                || path.Contains("Window", StringComparison.OrdinalIgnoreCase)
                || path.Contains("ViewModel", StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();

        lines.Add($"XAML command routes: {FormatInlineList(xamlCommands)}");
        lines.Add($"JSON config keys: {FormatInlineList(jsonKeys)}");
        lines.Add($"Project/package routes: {FormatInlineList(projectLinks)}");
        lines.Add($"C# route surfaces: {FormatInlineList(csharpRoutes)}");
        lines.Add("Cross-language rule: UI binding, parser/action route, project reference, and JSON setting changes should be validated together.");
        return lines;
    }

    private IEnumerable<string> ExtractQuotedAttributeValues(string file, string attributeName)
    {
        var text = SafeReadText(file);
        var marker = attributeName + "=\"";
        var index = 0;
        while ((index = text.IndexOf(marker, index, StringComparison.OrdinalIgnoreCase)) >= 0)
        {
            var start = index + marker.Length;
            var end = text.IndexOf('"', start);
            if (end <= start)
            {
                break;
            }

            var value = text[start..end].Trim();
            if (!string.IsNullOrWhiteSpace(value))
            {
                yield return $"{RelativeToWorkspace(file)} -> {value}";
            }

            index = end + 1;
        }
    }

    private IReadOnlyList<string> ExtractTopLevelJsonKeys(string file)
    {
        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(file));
            if (document.RootElement.ValueKind != JsonValueKind.Object)
            {
                return [];
            }

            return document.RootElement
                .EnumerateObject()
                .Take(8)
                .Select(property => $"{RelativeToWorkspace(file)}:{property.Name}")
                .ToList();
        }
        catch (JsonException)
        {
            return [];
        }
        catch (IOException)
        {
            return [];
        }
        catch (UnauthorizedAccessException)
        {
            return [];
        }
    }

    private IEnumerable<string> ExtractProjectRouteHints(string file)
    {
        XDocument document;
        try
        {
            document = XDocument.Load(file);
        }
        catch (IOException)
        {
            yield break;
        }
        catch (UnauthorizedAccessException)
        {
            yield break;
        }
        catch (System.Xml.XmlException)
        {
            yield break;
        }

        foreach (var reference in document.Descendants().Where(element => element.Name.LocalName is "ProjectReference" or "PackageReference").Take(8))
        {
            var include = reference.Attribute("Include")?.Value;
            if (!string.IsNullOrWhiteSpace(include))
            {
                yield return $"{RelativeToWorkspace(file)} -> {include}";
            }
        }
    }

    private static string FormatYesNo(bool value) => value ? "yes" : "no";

    private IReadOnlyList<string> BuildRiskModelV2(IReadOnlyList<string> files)
    {
        var groups = files
            .Select(RelativeToWorkspace)
            .GroupBy(ClassifyFileRiskV2, StringComparer.OrdinalIgnoreCase)
            .OrderBy(group => RiskSortKey(group.Key))
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .Select(group => $"{group.Key} ({group.Count()}): {FormatInlineList(group.Take(3))}")
            .ToList();
        return groups.Count == 0
            ? ["No files available for risk scoring."]
            : groups;
    }

    private static int RiskSortKey(string risk)
    {
        if (risk.StartsWith("Protected", StringComparison.OrdinalIgnoreCase))
        {
            return 0;
        }

        if (risk.StartsWith("High", StringComparison.OrdinalIgnoreCase))
        {
            return 1;
        }

        if (risk.StartsWith("Medium", StringComparison.OrdinalIgnoreCase))
        {
            return 2;
        }

        return 3;
    }

    private static DateTimeOffset GetLatestWorkspaceWriteUtc(IReadOnlyList<string> files)
    {
        var latest = DateTimeOffset.MinValue;
        foreach (var file in files)
        {
            try
            {
                if (!File.Exists(file))
                {
                    continue;
                }

                var write = new DateTimeOffset(File.GetLastWriteTimeUtc(file), TimeSpan.Zero);
                if (write > latest)
                {
                    latest = write;
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }

        return latest == DateTimeOffset.MinValue ? DateTimeOffset.UtcNow : latest;
    }

    private static string ClassifyProjectIndexFileRole(string relativePath)
    {
        var path = NormalizePathForClassification(relativePath);
        var fileName = Path.GetFileName(path);
        if (path.Contains("/tests/", StringComparison.OrdinalIgnoreCase) || fileName.Contains("test", StringComparison.OrdinalIgnoreCase))
        {
            return "tests";
        }

        if (path.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".slnx", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".props", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".targets", StringComparison.OrdinalIgnoreCase)
            || fileName.Equals("package.json", StringComparison.OrdinalIgnoreCase))
        {
            return "project/dependency setup";
        }

        if (path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/viewmodels/", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/views/", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/ali.app.wpf/", StringComparison.OrdinalIgnoreCase))
        {
            return "desktop UI";
        }

        if (path.Contains("/coding/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Coding", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("WorkspacePolicy", StringComparison.OrdinalIgnoreCase))
        {
            return "programming assistant";
        }

        if (path.Contains("/sources/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Source", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Retriever", StringComparison.OrdinalIgnoreCase))
        {
            return "source retrieval";
        }

        if (path.Contains("/voice/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Voice", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Speech", StringComparison.OrdinalIgnoreCase))
        {
            return "voice/audio";
        }

        if (path.Contains("/installation/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Installer", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Setup", StringComparison.OrdinalIgnoreCase))
        {
            return "installer/deployment";
        }

        if (path.Contains("/runtime/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Runtime", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("OpenAI", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Ollama", StringComparison.OrdinalIgnoreCase))
        {
            return "model runtime";
        }

        if (path.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".md", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".yml", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".yaml", StringComparison.OrdinalIgnoreCase))
        {
            return "docs/config";
        }

        return path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase) ? "application code" : "other";
    }

    private static string ClassifyProjectIndexFeatureArea(string relativePath)
    {
        var path = NormalizePathForClassification(relativePath);
        var fileName = Path.GetFileName(path);
        if (path.Contains("/tests/", StringComparison.OrdinalIgnoreCase) || fileName.Contains("test", StringComparison.OrdinalIgnoreCase))
        {
            return "test coverage";
        }

        if (path.Contains("/coding/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Coding", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Roadmap", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Patch", StringComparison.OrdinalIgnoreCase))
        {
            return "programming workflow";
        }

        if (fileName.Contains("Computer", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Troubleshooting", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Process", StringComparison.OrdinalIgnoreCase))
        {
            return "computer maintenance";
        }

        if (path.Contains("/sources/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Source", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Weather", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Forecast", StringComparison.OrdinalIgnoreCase))
        {
            return "web sources and weather";
        }

        if (path.Contains("/voice/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Voice", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Speech", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Audio", StringComparison.OrdinalIgnoreCase))
        {
            return "voice and audio";
        }

        if (path.Contains("/installation/", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Installer", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Setup", StringComparison.OrdinalIgnoreCase))
        {
            return "installer and delivery";
        }

        if (path.Contains("/ali.app.wpf/", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/viewmodels/", StringComparison.OrdinalIgnoreCase))
        {
            return "desktop shell";
        }

        if (fileName.Contains("Runtime", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("OpenAI", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Ollama", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Model", StringComparison.OrdinalIgnoreCase))
        {
            return "local model runtime";
        }

        if (fileName.Contains("Conversation", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Memory", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Reminder", StringComparison.OrdinalIgnoreCase))
        {
            return "conversation memory";
        }

        if (fileName.Contains("Pdf", StringComparison.OrdinalIgnoreCase)
            || fileName.Contains("Document", StringComparison.OrdinalIgnoreCase))
        {
            return "documents and PDFs";
        }

        if (path.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".props", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".targets", StringComparison.OrdinalIgnoreCase))
        {
            return "project structure";
        }

        return "general application";
    }

    private static string NormalizePathForClassification(string path) =>
        path.Replace('\\', '/');

    private ProjectIndexStatus GetProjectIndexStatus()
    {
        if (!File.Exists(_projectIndexPath))
        {
            return new ProjectIndexStatus(false, "Bad - missing; run project index.");
        }

        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(_projectIndexPath));
            var root = document.RootElement;
            var workspaceRoot = root.TryGetProperty("workspaceRoot", out var workspaceElement)
                ? workspaceElement.GetString()
                : null;
            var projects = root.TryGetProperty("projects", out var projectsElement) && projectsElement.ValueKind == JsonValueKind.Array
                ? projectsElement.GetArrayLength()
                : 0;
            var symbols = root.TryGetProperty("symbols", out var symbolsElement) && symbolsElement.ValueKind == JsonValueKind.Array
                ? symbolsElement.GetArrayLength()
                : 0;
            var fileRoles = root.TryGetProperty("fileRoles", out var rolesElement) && rolesElement.ValueKind == JsonValueKind.Array
                ? rolesElement.GetArrayLength()
                : 0;
            var featureAreas = root.TryGetProperty("featureAreas", out var areasElement) && areasElement.ValueKind == JsonValueKind.Array
                ? areasElement.GetArrayLength()
                : 0;
            var dependencies = root.TryGetProperty("projectDependencies", out var dependenciesElement) && dependenciesElement.ValueKind == JsonValueKind.Array
                ? dependenciesElement.GetArrayLength()
                : 0;
            var created = root.TryGetProperty("createdAtUtc", out var createdElement) && createdElement.TryGetDateTimeOffset(out var parsedCreated)
                ? parsedCreated.LocalDateTime.ToString("g", CultureInfo.CurrentCulture)
                : "unknown time";
            var indexedFileCount = root.TryGetProperty("fileCount", out var fileCountElement) && fileCountElement.TryGetInt32(out var parsedFileCount)
                ? parsedFileCount
                : -1;
            var indexedLatestWrite = root.TryGetProperty("latestWorkspaceWriteUtc", out var latestWriteElement) && latestWriteElement.TryGetDateTimeOffset(out var parsedLatestWrite)
                ? parsedLatestWrite
                : (DateTimeOffset?)null;
            if (string.IsNullOrWhiteSpace(workspaceRoot)
                || !Path.GetFullPath(workspaceRoot).Equals(Path.GetFullPath(Policy.WorkspaceRoot), StringComparison.OrdinalIgnoreCase))
            {
                return new ProjectIndexStatus(false, "Needs refresh - index is for another workspace.");
            }

            var currentFiles = Directory.Exists(Policy.WorkspaceRoot) ? EnumerateWorkspaceFiles().Take(10_001).ToList() : [];
            var currentLatestWrite = GetLatestWorkspaceWriteUtc(currentFiles);
            if (indexedFileCount >= 0 && currentFiles.Count != indexedFileCount)
            {
                return new ProjectIndexStatus(false, $"Needs refresh - file count changed from {indexedFileCount} to {currentFiles.Count}.");
            }

            if (indexedLatestWrite is not null && currentLatestWrite > indexedLatestWrite.Value.AddSeconds(2))
            {
                return new ProjectIndexStatus(false, "Needs refresh - workspace files changed after the index was built.");
            }

            return new ProjectIndexStatus(true, $"Good - {projects} project(s), {symbols} symbol(s), {fileRoles} file role(s), {featureAreas} feature area(s), {dependencies} dependency edge(s), refreshed {created}.");
        }
        catch (JsonException ex)
        {
            return new ProjectIndexStatus(false, $"Bad - unreadable project index: {TrimForChat(ex.Message, 240)}");
        }
        catch (IOException ex)
        {
            return new ProjectIndexStatus(false, $"Bad - cannot read project index: {TrimForChat(ex.Message, 240)}");
        }
        catch (UnauthorizedAccessException ex)
        {
            return new ProjectIndexStatus(false, $"Bad - cannot read project index: {TrimForChat(ex.Message, 240)}");
        }
    }

    private async Task<CodingToolResult> ShowProjectIndexAsync(CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (!Directory.Exists(Policy.WorkspaceRoot))
        {
            return new CodingToolResult(
                true,
                false,
                $"Coding workspace does not exist yet: {Policy.WorkspaceRoot}",
                "Project index",
                Policy.WorkspaceRoot);
        }

        var files = EnumerateWorkspaceFiles().Take(10_000).ToList();
        var solutions = files
            .Where(file => file.EndsWith(".sln", StringComparison.OrdinalIgnoreCase)
                           || file.EndsWith(".slnx", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .Select(RelativeToWorkspace)
            .ToList();
        var projectFiles = files
            .Where(file => file.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var summaries = projectFiles
            .Take(MaxWorkspaceSummaryEntries)
            .Select(ReadProjectSummary)
            .ToList();
        var primaryTarget = TryFindPrimaryProjectOrSolution(Policy.WorkspaceRoot, out var primary)
            ? RelativeToWorkspace(primary)
            : null;
        var stackSignals = DetectStackSignals(files, summaries);
        var styleSignals = DetectStyleSignals(files, summaries);
        var markers = FindProjectMarkers(files);
        var entryFiles = files
            .Where(IsLikelyEntryPoint)
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .Select(RelativeToWorkspace)
            .ToList();
        var buildCommands = DiscoverBuildCommands(files, summaries, primary is null ? null : primary).ToList();
        var testCommands = DiscoverTestCommands(files, summaries, primary is null ? null : primary).ToList();
        var symbols = BuildRoslynSymbolIndex(GetCSharpFiles(), 500)
            .Select(symbol => new ProjectIndexSymbol(
                symbol.Kind,
                symbol.Name,
                symbol.DisplayName,
                symbol.Container,
                RelativeToWorkspace(symbol.Path),
                string.IsNullOrWhiteSpace(symbol.ProjectPath) ? string.Empty : RelativeToWorkspace(symbol.ProjectPath),
                symbol.LineNumber,
                symbol.EndLineNumber))
            .ToList();
        var fileRoles = BuildProjectIndexFileRoles(files);
        var featureAreas = BuildProjectIndexFeatureAreas(files);
        var projectDependencies = BuildProjectDependencyEdges(summaries);
        var projectBuildOrder = EstimateBuildOrder(summaries, projectDependencies);
        var generatedCode = BuildGeneratedCodeAwareness(files);
        var msBuildProjects = BuildMsBuildProjectAwareness(projectFiles);
        var publicApiSurface = BuildPublicApiSurface(GetCSharpFiles().Take(1_000).ToList());
        var architectureSummary = BuildRepositoryArchitectureSummary(files, summaries, msBuildProjects);
        var runtimeRoutes = BuildRuntimeRouteMap(files);
        var ownershipMap = BuildPersistentOwnershipMap(symbols, summaries, files);
        var crossLanguageRoutes = BuildCrossLanguageRouteMap(files);
        var riskModel = BuildRiskModelV2(files);
        var projectIntent = BuildProjectIntentSignals(files, summaries, stackSignals);
        var compressedRepoMap = BuildCompressedRepoMap(files, summaries, fileRoles, featureAreas, projectIntent, buildCommands, testCommands);
        var symbolOwnershipLedger = BuildDurableSymbolOwnershipLedger(symbols);
        var symbolStalenessRows = BuildSymbolStalenessRows(symbolOwnershipLedger);
        var focusedTestPlan = BuildFocusedTestRunnerRecommendations(testCommands, summaries);
        var refreshAutomationRows = BuildProjectIndexRefreshRows(new ProjectIndexStatus(true, "Good - index freshly rebuilt."));
        var latestWorkspaceWrite = GetLatestWorkspaceWriteUtc(files);
        var snapshot = new ProjectIndexSnapshot(
            DateTimeOffset.UtcNow,
            Policy.WorkspaceRoot,
            files.Count,
            latestWorkspaceWrite,
            primaryTarget,
            solutions,
            summaries,
            stackSignals,
            styleSignals,
            markers,
            entryFiles,
            buildCommands,
            testCommands,
            symbols,
            fileRoles,
            featureAreas,
            projectDependencies,
            projectBuildOrder,
            generatedCode,
            msBuildProjects,
            publicApiSurface,
            architectureSummary,
            runtimeRoutes,
            ownershipMap,
            crossLanguageRoutes,
            riskModel,
            projectIntent,
            compressedRepoMap,
            symbolStalenessRows,
            refreshAutomationRows);

        await WriteCodingJsonAsync(_symbolOwnershipLedgerPath, symbolOwnershipLedger, cancellationToken).ConfigureAwait(false);
        Directory.CreateDirectory(Path.GetDirectoryName(_projectIndexPath)!);
        var json = JsonSerializer.Serialize(snapshot, RoadmapJsonOptions);
        await File.WriteAllTextAsync(_projectIndexPath, json, cancellationToken).ConfigureAwait(false);

        var lines = new List<string>
        {
            "Project index:",
            "No files were changed in the workspace.",
            $"Index file: {_projectIndexPath}",
            $"Workspace: {Policy.WorkspaceRoot}",
            $"Files indexed: {files.Count}",
            $"Solutions: {solutions.Count}",
            $"Projects: {summaries.Count}",
            $"Symbols: {symbols.Count}",
            $"File roles: {FormatProjectIndexRoleSummary(fileRoles)}",
            $"Feature areas: {FormatProjectIndexFeatureSummary(featureAreas)}",
            $"Project dependencies: {FormatProjectDependencySummary(projectDependencies)}",
            $"Project build order: {FormatInlineList(projectBuildOrder.Take(6))}",
            $"Architecture summary: {FormatInlineList(architectureSummary.Take(6))}",
            $"MSBuild awareness: {FormatInlineList(msBuildProjects.Take(6))}",
            $"Generated/designer guardrails: {FormatInlineList(generatedCode.Take(6))}",
            $"Project intent: {FormatInlineList(projectIntent.Take(5))}",
            $"Compressed repo map: {FormatInlineList(compressedRepoMap.Take(5))}",
            $"Public API surface: {FormatInlineList(publicApiSurface.Take(6))}",
            $"Runtime route map: {FormatInlineList(runtimeRoutes.Take(6))}",
            $"Ownership map: {FormatInlineList(ownershipMap.Take(6))}",
            $"Durable symbol ledger: {_symbolOwnershipLedgerPath}",
            $"Symbol ownership examples: {FormatInlineList(BuildDurableSymbolOwnershipLines(symbolOwnershipLedger).Take(6))}",
            $"Focused test runner: {FormatInlineList(focusedTestPlan.Take(4))}",
            $"Per-symbol stale detection: {FormatInlineList(symbolStalenessRows.Take(4))}",
            $"Project index refresh automation: {FormatInlineList(refreshAutomationRows.Take(3))}",
            $"Cross-language routes: {FormatInlineList(crossLanguageRoutes.Take(6))}",
            $"Risk model v2: {FormatInlineList(riskModel.Take(6))}",
            primaryTarget is null ? "Primary target: not found" : $"Primary target: {primaryTarget}",
            $"Stacks: {FormatInlineList(stackSignals)}",
            $"Style signals: {FormatInlineList(styleSignals)}",
            $"Build commands: {FormatInlineList(buildCommands)}",
            $"Test commands: {FormatInlineList(testCommands)}",
            $"Latest workspace write: {latestWorkspaceWrite.LocalDateTime:g}",
            $"Semantic symbol examples: {FormatInlineList(symbols.Take(8).Select(symbol => $"{symbol.Kind} {symbol.DisplayName}"))}",
            "Next - use coding context packet, safe edit workflow, or resolve test target against this refreshed index."
        };

        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Project index", _projectIndexPath);
    }

    private CodingToolResult ShowProjectDependencyMap(CodingToolRequest request)
    {
        var query = CleanGoal(request.Query, string.Empty);
        var summaries = GetWorkspaceProjectSummaries();
        var edges = BuildProjectDependencyEdges(summaries);
        var selected = SelectProjectsForDependencyMap(query, summaries);
        var impacted = BuildProjectDependentClosure(selected, edges);
        var buildOrder = EstimateBuildOrder(summaries, edges)
            .Where(project => impacted.Contains(project))
            .ToList();
        var directDependencies = edges
            .Where(edge => selected.Contains(edge.From))
            .Select(edge => $"{edge.From} -> {edge.To}")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var directDependents = edges
            .Where(edge => selected.Contains(edge.To))
            .Select(edge => $"{edge.From} -> {edge.To}")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        var lines = new List<string>
        {
            "Project dependency map:",
            "No files were changed.",
            string.IsNullOrWhiteSpace(query) ? "Query: all projects" : $"Query: {query}",
            $"Projects found: {summaries.Count}",
            $"Dependency edges: {edges.Count}",
            "Selected projects:"
        };
        lines.AddRange(selected.Count == 0 ? ["- none matched"] : selected.Select(project => $"- {project}"));
        lines.Add("Direct dependencies:");
        lines.AddRange(directDependencies.Count == 0 ? ["- none"] : directDependencies.Select(edge => $"- {edge}"));
        lines.Add("Direct dependents:");
        lines.AddRange(directDependents.Count == 0 ? ["- none"] : directDependents.Select(edge => $"- {edge}"));
        lines.Add("Transitive impact:");
        lines.AddRange(impacted.Count == 0 ? ["- none"] : impacted.OrderBy(project => project, StringComparer.OrdinalIgnoreCase).Select(project => $"- {project}"));
        lines.Add("Build order slice:");
        lines.AddRange(buildOrder.Count == 0 ? ["- none"] : buildOrder.Select((project, index) => $"- {index + 1}. {project}"));
        lines.Add("Validation guidance:");
        lines.Add(selected.Count == 0
            ? "- Run project index, then ask for a project path or project name shown there."
            : "- Validate selected projects first, then direct/transitive dependents in build order.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Project dependency map", Policy.WorkspaceRoot);
    }

    private static IReadOnlyList<string> SelectProjectsForDependencyMap(string query, IReadOnlyList<ProjectSummary> summaries)
    {
        if (summaries.Count == 0)
        {
            return [];
        }

        if (string.IsNullOrWhiteSpace(query))
        {
            return summaries
                .Select(summary => summary.RelativePath)
                .Take(12)
                .ToList();
        }

        return summaries
            .Where(summary => summary.RelativePath.Contains(query, StringComparison.OrdinalIgnoreCase)
                || Path.GetFileNameWithoutExtension(summary.RelativePath).Contains(query, StringComparison.OrdinalIgnoreCase))
            .Select(summary => summary.RelativePath)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();
    }

    private static IReadOnlyList<string> BuildProjectDependentClosure(
        IReadOnlyList<string> selected,
        IReadOnlyList<ProjectDependency> edges)
    {
        var impacted = new HashSet<string>(selected, StringComparer.OrdinalIgnoreCase);
        var pending = new Queue<string>(selected);
        while (pending.Count > 0)
        {
            var current = pending.Dequeue();
            foreach (var dependent in edges.Where(edge => edge.To.Equals(current, StringComparison.OrdinalIgnoreCase)).Select(edge => edge.From))
            {
                if (impacted.Add(dependent))
                {
                    pending.Enqueue(dependent);
                }
            }
        }

        return impacted.ToList();
    }

