        var grouped = changedFiles
            .GroupBy(ClassifyFeatureImplementationRole, StringComparer.OrdinalIgnoreCase)
            .Select(group => $"{group.Key}: {group.Count()} file(s), {FormatInlineList(group.Take(3))}")
            .Take(6)
            .ToList();
        grouped.Add($"Affected projects: {FormatInlineList(projectImpact.AffectedProjects)}");
        grouped.Add($"Build order: {FormatInlineList(projectImpact.BuildOrderProjects)}");
        grouped.Add($"Risk depth: {ClassifyRiskAwareTestDepth(changedFiles)}");
        return grouped;
    }

    private IReadOnlyList<(string Name, int Score, string Note)> BuildMiniCodexScoreV3Rows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus,
        bool hasPendingPreview)
    {
        var indexStatus = GetProjectIndexStatus();
        var awareness = indexStatus.Available ? 98 : 94;
        var editPlanning = Math.Clamp(94 + (context.RankedTargets.Count > 0 ? 2 : 0) + (context.Graph.Declarations.Count > 0 ? 1 : 0), 0, 98);
        var patchSafety = Math.Clamp(94 + (synthesis.PreviewReady ? 3 : 0) + (hasPendingPreview ? 1 : 0), 0, 98);
        var validation = Math.Clamp(94 + (!string.IsNullOrWhiteSpace(context.TestTarget.Command) ? 2 : 0) + (latestValidation?.Succeeded == true ? 1 : 0), 0, 98);
        var autonomous = Math.Clamp(95 + (testPreview.Ready ? 1 : 0) + (synthesis.PreviewReady ? 2 : 0) + (latestEdit is not null ? 1 : 0), 0, 99);
        var dashboard = 99;
        return
        [
            ("Codebase awareness", awareness, indexStatus.Available ? "project index, Roslyn routes, and data systems guide available" : "refresh project index"),
            ("Edit planning", editPlanning, "active workspace context, intake, data-structure/service/database planning, Roslyn planner, insertion planner, pattern copy, implementation planner, and concrete patch authoring are wired"),
            ("Patch safety", patchSafety, "owner apply packet, paired previews, intent diff composer, patch body generator, confidence scoring, exact checks, and semantic diff summary are wired"),
            ("Validation/release", validation, "validation minimizer, validation chain planner, router, repair loop, evidence pack, and receipts are wired"),
            ("Autonomous workflow", autonomous, "programming action planner, programming-mode router, authoring flow, build-this front door, orchestrator, slice preview, repeat failure memory, first diagnostic route, failure-to-patch v3, and repair routing are wired"),
            ("Dashboard usability", dashboard, "chat-first programming workspace, active workspace picker, single activity pane, and compact steering controls are available")
        ];
    }

