    private void AppendCurrentCodingSessionHistory(string eventName, CurrentCodingSessionState state, string note)
    {
        var history = ReadCurrentCodingSessionHistory();
        history.Entries.Add(new CurrentCodingSessionHistoryEntry(
            DateTimeOffset.Now,
            eventName,
            state.Goal,
            state.ProjectPath,
            state.Status,
            note));
        WriteCurrentCodingSessionHistory(new CurrentCodingSessionHistory(history.Entries.TakeLast(100).ToList()));
    }

    private string DescribePendingPatchPreview()
    {
        LoadPendingPatchPreviewIfNeeded();
        if (_lastPatchPreviewRequest is null)
        {
            return "none";
        }

        var request = _lastPatchPreviewRequest;
        if (request.Action == CodingToolAction.PreviewPatchBundle)
        {
            return $"Waiting - patch bundle with {request.PatchEdits?.Count ?? 0} edit(s).";
        }

        return string.IsNullOrWhiteSpace(request.Path)
            ? "Waiting - single-file patch preview."
            : $"Waiting - {FormatWorkspacePath(request.Path)}.";
    }

    private string BuildCurrentTaskNextAction(
        CurrentCodingSessionState state,
        FeatureWorkContext context,
        GitWorkingTreeStatus gitStatus)
    {
        LoadPendingPatchPreviewIfNeeded();
        var receipts = ReadRecentReceipts(MaxReceiptEntries);
        var latestValidation = receipts.LastOrDefault(IsDotNetReceipt);
        if (_lastPatchPreviewRequest is not null)
        {
            return "show pending patch preview";
        }

        if (latestValidation is { Succeeded: false })
        {
            return "diagnose last failure";
        }

        if (gitStatus.HasUncommittedChanges && latestValidation?.Succeeded != true)
        {
            return "validation chain planner " + state.Goal;
        }

        if (context.RankedTargets.Count == 0)
        {
            return "feature work context " + state.Goal;
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "resolve test target " + state.Goal;
        }

        return "concrete patch authoring " + state.Goal;
    }

    private IReadOnlyList<string> BuildContinueCurrentTaskCommandRows(
        CurrentCodingSessionState state,
        FeatureWorkContext context,
        GitWorkingTreeStatus gitStatus)
    {
        var rows = new List<string>
        {
            BuildCurrentTaskNextAction(state, context, gitStatus),
            "current coding task",
            "coding session history"
        };

        if (_lastPatchPreviewRequest is not null)
        {
            rows.Add("confirm apply last patch preview");
            rows.Add("discard pending patch preview");
        }
        else
        {
            rows.Add("feature work context " + state.Goal);
            rows.Add("exact patch synthesis " + state.Goal);
        }

        if (!string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            rows.Add(context.TestTarget.Command);
        }

        rows.Add(state.BuildCommand);
        rows.Add("semantic change receipt " + state.Goal);
        return rows
            .Where(row => !string.IsNullOrWhiteSpace(row))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
    }

    private ProjectCommandDefaultsStore ReadProjectCommandDefaultsStore()
    {
        if (!File.Exists(_projectCommandDefaultsPath))
        {
            return new ProjectCommandDefaultsStore([]);
        }

        try
        {
            using var stream = File.OpenRead(_projectCommandDefaultsPath);
            return JsonSerializer.Deserialize<ProjectCommandDefaultsStore>(stream, RoadmapJsonOptions)
                   ?? new ProjectCommandDefaultsStore([]);
        }
        catch (IOException)
        {
            return new ProjectCommandDefaultsStore([]);
        }
        catch (UnauthorizedAccessException)
        {
            return new ProjectCommandDefaultsStore([]);
        }
        catch (JsonException)
        {
            return new ProjectCommandDefaultsStore([]);
        }
    }

    private void WriteProjectCommandDefaultsStore(ProjectCommandDefaultsStore store)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(_projectCommandDefaultsPath)!);
        using var stream = File.Create(_projectCommandDefaultsPath);
        JsonSerializer.Serialize(stream, store, RoadmapJsonOptions);
    }

    private ProjectCommandDefaultsEntry BuildProjectCommandDefaults(string? currentTarget, string? testCommand)
    {
        if (!string.IsNullOrWhiteSpace(currentTarget))
        {
            var key = NormalizeProjectMemoryKey(currentTarget);
            var saved = ReadProjectCommandDefaultsStore().Entries
                .LastOrDefault(entry => string.Equals(NormalizeProjectMemoryKey(entry.ProjectPath), key, StringComparison.OrdinalIgnoreCase));
            if (saved is not null)
            {
                return saved;
            }
        }

        var target = currentTarget ?? Policy.WorkspaceRoot;
        var quoted = QuoteForOwnerCommand(target);
        var build = $"confirm dotnet build {quoted}";
        var test = string.IsNullOrWhiteSpace(testCommand)
            ? $"confirm dotnet test {quoted}"
            : testCommand;
        var run = target.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
            ? $"confirm dotnet run {quoted}"
            : "Review - pick an app .csproj before running.";
        return new ProjectCommandDefaultsEntry(target, build, test, run, DateTimeOffset.Now);
    }

    private static ProjectCommandDefaultsEntry ParseProjectCommandDefaults(
        string? query,
        ProjectCommandDefaultsEntry fallback)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            return fallback;
        }

        var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var segment in query.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var index = segment.IndexOf('=', StringComparison.Ordinal);
            if (index <= 0)
            {
                continue;
            }

            var key = segment[..index].Trim();
            var value = segment[(index + 1)..].Trim().Trim('"');
            if (key.Length > 0 && value.Length > 0)
            {
                values[key] = value;
            }
        }

        return fallback with
        {
            BuildCommand = values.GetValueOrDefault("build", fallback.BuildCommand),
            TestCommand = values.GetValueOrDefault("test", fallback.TestCommand),
            RunCommand = values.GetValueOrDefault("run", fallback.RunCommand),
            UpdatedAt = DateTimeOffset.Now
        };
    }

