    private async Task<FeaturePatchSynthesis> BuildFeaturePatchSynthesisAsync(
        FeatureWorkContext context,
        CancellationToken cancellationToken)
    {
        var candidates = new List<FeaturePatchSynthesisCandidate>();
        var guardRows = new List<string>();
        var hasTransform = TryParseMechanicalPatchTransform(context.Goal, out var oldValue, out var newValue);
        guardRows.Add(hasTransform
            ? $"Mechanical transform: replace {oldValue} with {newValue}."
            : "Mechanical transform: none detected - exact anchors only until implementation text is supplied.");
        var targetPaths = FindDeterministicFeaturePatchTargets(context)
            .Concat(context.RankedTargets
            .Select(target => ToAbsoluteWorkspacePath(target.RelativePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!))
            .Concat(context.CandidateFiles)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(MaxPatchBundleEdits)
            .ToList();
        if (targetPaths.Count == 0)
        {
            guardRows.Add("Target guard: no file target was resolved.");
        }

        foreach (var fullPath in targetPaths)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (!File.Exists(fullPath))
            {
                if (!hasTransform
                    && TryBuildSimpleConsoleProgramCreateBlock(context.Goal, fullPath, out var createText, out var createNote))
                {
                    candidates.Add(new FeaturePatchSynthesisCandidate(
                        RelativeToWorkspace(fullPath),
                        fullPath,
                        "deterministic console recipe",
                        string.Empty,
                        createText,
                        true,
                        createNote));
                    continue;
                }

                if (!hasTransform
                    && TryBuildNewWpfViewModelPatchBlock(context.Goal, fullPath, out var newWpfViewModelText, out var newWpfViewModelNote))
                {
                    candidates.Add(new FeaturePatchSynthesisCandidate(
                        RelativeToWorkspace(fullPath),
                        fullPath,
                        "deterministic WPF MVVM view-model recipe",
                        string.Empty,
                        newWpfViewModelText,
                        true,
                        newWpfViewModelNote));
                    continue;
                }

                if (!hasTransform
                    && TryBuildNewWpfAppPatchBlock(context.Goal, fullPath, out var newWpfAppText, out var newWpfAppNote))
                {
                    candidates.Add(new FeaturePatchSynthesisCandidate(
                        RelativeToWorkspace(fullPath),
                        fullPath,
                        "deterministic WPF application entry recipe",
                        string.Empty,
                        newWpfAppText,
                        true,
                        newWpfAppNote));
                    continue;
                }

                if (!hasTransform
                    && TryBuildNewWpfStylesPatchBlock(context.Goal, fullPath, out var newWpfStylesText, out var newWpfStylesNote))
                {
                    candidates.Add(new FeaturePatchSynthesisCandidate(
                        RelativeToWorkspace(fullPath),
                        fullPath,
                        "deterministic WPF ResourceDictionary recipe",
                        string.Empty,
                        newWpfStylesText,
                        true,
                        newWpfStylesNote));
                    continue;
                }

                if (!hasTransform
                    && TryBuildNewWpfUserControlPatchBlock(context.Goal, fullPath, out var newWpfUserControlText, out var newWpfUserControlNote))
                {
                    candidates.Add(new FeaturePatchSynthesisCandidate(
                        RelativeToWorkspace(fullPath),
                        fullPath,
                        "deterministic WPF UserControl recipe",
                        string.Empty,
                        newWpfUserControlText,
                        true,
                        newWpfUserControlNote));
                    continue;
                }

                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "missing file",
                    string.Empty,
                    string.Empty,
                    false,
                    "Target file does not exist."));
                continue;
            }

            var info = new FileInfo(fullPath);
            if (info.Length > MaxReplaceFileCharacters)
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "file too large",
                    string.Empty,
                    string.Empty,
                    false,
                    $"File is too large for safe exact synthesis ({info.Length} bytes)."));
                continue;
            }

            var content = await File.ReadAllTextAsync(fullPath, cancellationToken).ConfigureAwait(false);
            if (string.IsNullOrWhiteSpace(content))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "empty file",
                    string.Empty,
                    string.Empty,
                    false,
                    "File is empty or whitespace only."));
                continue;
            }

            if (hasTransform && TryBuildMechanicalPatchBlock(content, oldValue, newValue, out var oldText, out var newText, out var transformNote))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "mechanical transform",
                    oldText,
                    newText,
                    true,
                    transformNote));
                continue;
            }

            if (!hasTransform
                && TryBuildConsoleProjectOutputTypePatchBlock(content, context.Goal, fullPath, out var projectOldText, out var projectNewText, out var projectNote))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "deterministic console project recipe",
                    projectOldText,
                    projectNewText,
                    true,
                    projectNote));
                continue;
            }

            if (!hasTransform
                && TryBuildSimpleConsoleProgramPatchBlock(content, context.Goal, fullPath, out var consoleOldText, out var consoleNewText, out var consoleNote))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "deterministic console recipe",
                    consoleOldText,
                    consoleNewText,
                    true,
                    consoleNote));
                continue;
            }

            if (!hasTransform
                && TryBuildSimpleWpfPatchBlock(content, context.Goal, fullPath, out var wpfOldText, out var wpfNewText, out var wpfNote))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "deterministic WPF starter recipe",
                    wpfOldText,
                    wpfNewText,
                    true,
                    wpfNote));
                continue;
            }

            if (TryBuildAnchorPatchBlock(content, context.GoalTerms, hasTransform ? oldValue : null, out var anchorText, out var anchorNote))
            {
                candidates.Add(new FeaturePatchSynthesisCandidate(
                    RelativeToWorkspace(fullPath),
                    fullPath,
                    "exact anchor",
                    anchorText,
                    anchorText,
                    false,
                    hasTransform
                        ? $"Transform text was not uniquely replaceable; {anchorNote}"
                        : anchorNote));
            }
        }

        var previewEdits = candidates
            .Where(candidate => candidate.PreviewReady)
            .Take(MaxPatchBundleEdits)
            .Select(candidate => new CodingPatchEdit(candidate.FullPath, candidate.OldText, candidate.NewText))
            .ToList();
        guardRows.Add(previewEdits.Count > 0
            ? $"Preview guard: {previewEdits.Count} exact edit(s) can be previewed through the normal patch bundle engine."
            : "Preview guard: hold - no exact old/new edit is ready.");
        guardRows.Add(context.RankedTargets.Count == 0
            ? "Target guard: no ranked target; inspect files before applying."
            : $"Target guard: {context.RankedTargets.First().RelativePath} is the top ranked target.");
        guardRows.Add(string.IsNullOrWhiteSpace(context.TestTarget.Command)
            ? "Validation guard: targeted test command is not resolved yet."
            : $"Validation guard: {context.TestTarget.Command}.");
        var status = previewEdits.Count > 0
            ? "Preview-ready - exact old/new replacement blocks are available."
            : candidates.Count > 0
                ? "Anchored - exact old text found, implementation text still needed."
                : "Hold - no usable target or anchor was found.";
        return new FeaturePatchSynthesis(context.Goal, candidates, previewEdits, guardRows, previewEdits.Count > 0, status);
    }

    private IReadOnlyList<string> FindDeterministicFeaturePatchTargets(FeatureWorkContext context)
    {
        if (IsSimpleWpfProgramGoal(context.Goal))
        {
            return FindDeterministicWpfPatchTargets(context);
        }

        if (IsSimpleConsoleProgramGoal(context.Goal))
        {
            return FindDeterministicConsolePatchTargets(context);
        }

        return [];
    }

    private IReadOnlyList<string> FindDeterministicConsolePatchTargets(FeatureWorkContext context)
    {
        var targets = new List<string>();
        var primaryTarget = GetPrimaryTarget();
        if (!string.IsNullOrWhiteSpace(primaryTarget) && IsSafeProjectPath(primaryTarget))
        {
            targets.Add(primaryTarget);
        }

        foreach (var candidate in context.RankedTargets
            .Select(target => ToAbsoluteWorkspacePath(target.RelativePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Concat(context.CandidateFiles))
        {
            if (IsEditableProgramFile(candidate))
            {
                targets.Add(candidate);
            }
        }

        if (!string.IsNullOrWhiteSpace(primaryTarget))
        {
            var primaryDirectory = Path.GetDirectoryName(primaryTarget);
            if (!string.IsNullOrWhiteSpace(primaryDirectory))
            {
                var primaryProgram = Path.Combine(primaryDirectory, "Program.cs");
                if (IsSafeProgramPath(primaryProgram))
                {
                    targets.Add(primaryProgram);
                }
            }
        }

        targets.AddRange(GetCSharpFiles()
            .Where(IsEditableProgramFile)
            .OrderBy(path => RelativeToWorkspace(path), StringComparer.OrdinalIgnoreCase)
            .Take(1));
        return targets
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private IReadOnlyList<string> FindDeterministicWpfPatchTargets(FeatureWorkContext context)
    {
        var targets = new List<string>();
        var primaryTarget = GetPrimaryTarget();
        if (!string.IsNullOrWhiteSpace(primaryTarget))
        {
            var primaryDirectory = Path.GetDirectoryName(primaryTarget);
            if (!string.IsNullOrWhiteSpace(primaryDirectory))
            {
                AddIfEditableWpfSurface(targets, Path.Combine(primaryDirectory, "MainWindow.xaml"));
                AddIfEditableWpfSurface(targets, Path.Combine(primaryDirectory, "MainWindow.xaml.cs"));
                AddIfSafeNewWpfAppTarget(targets, Path.Combine(primaryDirectory, "App.xaml"));
                AddIfSafeNewWpfAppTarget(targets, Path.Combine(primaryDirectory, "App.xaml.cs"));
                if (IsWpfComplexWindowGoal(context.Goal))
                {
                    AddIfSafeNewWpfViewModelTarget(targets, Path.Combine(primaryDirectory, "MainWindowViewModel.cs"));
                    AddIfSafeNewWpfStylesTarget(targets, Path.Combine(primaryDirectory, "AliDashboardStyles.xaml"));
                    AddIfSafeNewWpfUserControlTarget(targets, Path.Combine(primaryDirectory, "DashboardDetailCard.xaml"));
                    AddIfSafeNewWpfUserControlTarget(targets, Path.Combine(primaryDirectory, "DashboardDetailCard.xaml.cs"));
                }
            }
        }

        foreach (var candidate in context.RankedTargets
            .Select(target => ToAbsoluteWorkspacePath(target.RelativePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Concat(context.CandidateFiles))
        {
            AddIfEditableWpfSurface(targets, candidate);
        }

        targets.AddRange(GetXamlFiles()
            .Where(IsEditableWpfSurfaceFile)
            .OrderBy(path => RelativeToWorkspace(path), StringComparer.OrdinalIgnoreCase)
            .Take(1));

        return targets
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private void AddIfEditableWpfSurface(List<string> targets, string path)
    {
        if (IsEditableWpfSurfaceFile(path))
        {
            targets.Add(path);
        }
    }

    private void AddIfSafeNewWpfViewModelTarget(List<string> targets, string path)
    {
        if (IsSafeNewWpfViewModelPath(path))
        {
            targets.Add(path);
        }
    }

    private void AddIfSafeNewWpfAppTarget(List<string> targets, string path)
    {
        if (IsSafeNewWpfAppPath(path))
        {
            targets.Add(path);
        }
    }

    private void AddIfSafeNewWpfStylesTarget(List<string> targets, string path)
    {
        if (IsSafeNewWpfStylesPath(path))
        {
            targets.Add(path);
        }
    }

    private void AddIfSafeNewWpfUserControlTarget(List<string> targets, string path)
    {
        if (IsSafeNewWpfUserControlPath(path))
        {
            targets.Add(path);
        }
    }

    private bool IsEditableWpfSurfaceFile(string path) =>
        File.Exists(path)
        && IsSafeWpfSurfacePath(path);

    private bool IsSafeWpfSurfacePath(string path)
    {
        var fileName = Path.GetFileName(path);
        return (fileName.Equals("MainWindow.xaml", StringComparison.OrdinalIgnoreCase)
                || fileName.Equals("MainWindow.xaml.cs", StringComparison.OrdinalIgnoreCase))
               && Policy.IsInsideWorkspace(path)
               && !IsBuildArtifactPath(path)
               && !IsGeneratedOrDesignerFile(path);
    }

    private bool IsSafeNewWpfViewModelPath(string path) =>
        Path.GetFileName(path).Equals("MainWindowViewModel.cs", StringComparison.OrdinalIgnoreCase)
        && Policy.IsInsideWorkspace(path)
        && !IsBuildArtifactPath(path)
        && !IsGeneratedOrDesignerFile(path);

    private bool IsSafeNewWpfAppPath(string path)
    {
        var fileName = Path.GetFileName(path);
        return (fileName.Equals("App.xaml", StringComparison.OrdinalIgnoreCase)
                || fileName.Equals("App.xaml.cs", StringComparison.OrdinalIgnoreCase))
               && Policy.IsInsideWorkspace(path)
               && !IsBuildArtifactPath(path)
               && !IsGeneratedOrDesignerFile(path);
    }

    private bool IsSafeNewWpfStylesPath(string path) =>
        Path.GetFileName(path).Equals("AliDashboardStyles.xaml", StringComparison.OrdinalIgnoreCase)
        && Policy.IsInsideWorkspace(path)
        && !IsBuildArtifactPath(path)
        && !IsGeneratedOrDesignerFile(path);

    private bool IsSafeNewWpfUserControlPath(string path)
    {
        var fileName = Path.GetFileName(path);
        return (fileName.Equals("DashboardDetailCard.xaml", StringComparison.OrdinalIgnoreCase)
                || fileName.Equals("DashboardDetailCard.xaml.cs", StringComparison.OrdinalIgnoreCase))
               && Policy.IsInsideWorkspace(path)
               && !IsBuildArtifactPath(path)
               && !IsGeneratedOrDesignerFile(path);
    }

    private bool IsEditableProgramFile(string path) =>
        File.Exists(path)
        && IsSafeProgramPath(path);

    private bool IsSafeProgramPath(string path) =>
        Path.GetFileName(path).Equals("Program.cs", StringComparison.OrdinalIgnoreCase)
        && Policy.IsInsideWorkspace(path)
        && !IsBuildArtifactPath(path)
        && !IsGeneratedOrDesignerFile(path);

    private bool IsSafeProjectPath(string path) =>
        File.Exists(path)
        && path.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
        && Policy.IsInsideWorkspace(path)
        && !IsBuildArtifactPath(path);

    private static IReadOnlyList<string> BuildFeaturePatchSynthesisBlockRows(FeaturePatchSynthesis synthesis)
    {
        if (synthesis.Candidates.Count == 0)
        {
            return ["- none resolved"];
        }

        var lines = new List<string>();
        foreach (var candidate in synthesis.Candidates.Take(4))
        {
            lines.Add($"- File: {candidate.RelativePath}");
            lines.Add($"  Ready: {(candidate.PreviewReady ? "Yes" : "No")} - {candidate.Note}");
            lines.Add($"  Anchor: {candidate.AnchorReason}");
            if (!string.IsNullOrWhiteSpace(candidate.OldText))
            {
                lines.Add("  Old text:");
                lines.AddRange(IndentBlock(candidate.OldText, "    "));
                lines.Add("  New text:");
                lines.AddRange(IndentBlock(candidate.NewText, "    "));
            }
            else if (candidate.PreviewReady && !string.IsNullOrWhiteSpace(candidate.NewText))
            {
                lines.Add("  New file text:");
                lines.AddRange(IndentBlock(candidate.NewText, "    "));
            }
        }

        return lines;
    }

    private static bool TryParseMechanicalPatchTransform(string goal, out string oldValue, out string newValue)
    {
        oldValue = string.Empty;
        newValue = string.Empty;
        var patterns = new[]
        {
            """\b(?:replace|rename|change|swap)\s+["'](?<old>[^"']+)["']\s+(?:with|to)\s+["'](?<new>[^"']+)["']""",
            """\b(?:replace|rename|change|swap)\s+(?<old>[A-Za-z_][\w.:-]*)\s+(?:with|to)\s+(?<new>[A-Za-z_][\w.:-]*)""",
            """\b(?:change|rename)\s+from\s+["']?(?<old>[^"'\s]+)["']?\s+to\s+["']?(?<new>[^"'\s]+)["']?"""
        };
        foreach (var pattern in patterns)
        {
            var match = Regex.Match(goal, pattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            if (!match.Success)
            {
                continue;
            }

            oldValue = match.Groups["old"].Value.Trim();
            newValue = match.Groups["new"].Value.Trim();
            return !string.IsNullOrWhiteSpace(oldValue)
                && !string.IsNullOrWhiteSpace(newValue)
                && !oldValue.Equals(newValue, StringComparison.Ordinal);
        }

        return false;
    }

    private static bool TryBuildMechanicalPatchBlock(
        string content,
        string oldValue,
        string newValue,
        out string oldText,
        out string newText,
        out string note)
    {
        oldText = string.Empty;
        newText = string.Empty;
        note = string.Empty;
        var count = CountOrdinalOccurrences(content, oldValue);
        if (count == 1)
        {
            oldText = oldValue;
            newText = newValue;
            note = "Exact token occurs once in the file.";
            return true;
        }

        var index = content.IndexOf(oldValue, StringComparison.Ordinal);
        if (index >= 0 && TryBuildUniqueContextBlock(content, index, oldValue.Length, out var block))
        {
            oldText = block;
            newText = block.Replace(oldValue, newValue, StringComparison.Ordinal);
            if (!oldText.Equals(newText, StringComparison.Ordinal))
            {
                note = $"Exact token occurs {count} time(s); using a unique surrounding block.";
                return true;
            }
        }

        note = count == 0
            ? "Transform source text was not found in this file."
            : $"Transform source text occurs {count} time(s) and no unique block was resolved.";
        return false;
    }

    private static bool TryBuildSimpleConsoleProgramCreateBlock(
        string goal,
        string fullPath,
        out string newText,
        out string note)
    {
        newText = string.Empty;
        note = string.Empty;
        if (!Path.GetFileName(fullPath).Equals("Program.cs", StringComparison.OrdinalIgnoreCase)
            || !IsSimpleConsoleProgramGoal(goal))
        {
            return false;
        }

        newText = BuildSimpleConsoleProgramText(goal, Environment.NewLine, out note);
        note = "Create Program.cs. " + note;
        return true;
    }

    private static bool TryBuildConsoleProjectOutputTypePatchBlock(
        string content,
        string goal,
        string fullPath,
        out string oldText,
        out string newText,
        out string note)
    {
        oldText = string.Empty;
        newText = string.Empty;
        note = string.Empty;
        if (!fullPath.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
            || !IsSimpleConsoleProgramGoal(goal)
            || content.Contains("<OutputType>Exe</OutputType>", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var newline = GetPreferredNewline(content);
        var outputTypeMatch = Regex.Match(
            content,
            @"<OutputType>\s*[^<]+\s*</OutputType>",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (outputTypeMatch.Success)
        {
            oldText = outputTypeMatch.Value;
            newText = "<OutputType>Exe</OutputType>";
            note = "Set project output type to executable.";
            return !oldText.Equals(newText, StringComparison.Ordinal);
        }

        var propertyGroupMatch = Regex.Match(
            content,
            @"<PropertyGroup>[ \t]*(?:\r?\n)?",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (propertyGroupMatch.Success
            && TryBuildUniqueContextBlock(content, propertyGroupMatch.Index, propertyGroupMatch.Length, out oldText))
        {
            var insertion = propertyGroupMatch.Value + "    <OutputType>Exe</OutputType>" + newline;
            newText = oldText.Replace(propertyGroupMatch.Value, insertion, StringComparison.Ordinal);
            note = "Add executable output type to the existing project property group.";
            return !oldText.Equals(newText, StringComparison.Ordinal);
        }

        var projectMatch = Regex.Match(
            content,
            @"<Project\b[^>]*>[ \t]*(?:\r?\n)?",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (projectMatch.Success
            && TryBuildUniqueContextBlock(content, projectMatch.Index, projectMatch.Length, out oldText))
        {
            var insertion = projectMatch.Value
                + "  <PropertyGroup>" + newline
                + "    <OutputType>Exe</OutputType>" + newline
                + "  </PropertyGroup>" + newline;
            newText = oldText.Replace(projectMatch.Value, insertion, StringComparison.Ordinal);
            note = "Add an executable property group to the project file.";
            return !oldText.Equals(newText, StringComparison.Ordinal);
        }

        return false;
    }

    private static bool TryBuildSimpleConsoleProgramPatchBlock(
        string content,
        string goal,
        string fullPath,
        out string oldText,
        out string newText,
        out string note)
    {
        oldText = string.Empty;
        newText = string.Empty;
        note = string.Empty;
        if (!Path.GetFileName(fullPath).Equals("Program.cs", StringComparison.OrdinalIgnoreCase)
            || !IsSimpleConsoleProgramGoal(goal))
        {
            return false;
        }

        var newline = GetPreferredNewline(content);
        oldText = content;
        newText = BuildSimpleConsoleProgramText(goal, newline, out note);
        return !content.Equals(newText, StringComparison.Ordinal);
    }

    private static string BuildSimpleConsoleProgramText(string goal, string newline, out string note)
    {
        var waitsForKey = MentionsAny(
            goal,
            "keypress",
            "key press",
            "press a key",
            "press any key",
            "press a button",
            "press button",
            "before closing",
            "before it closes",
            "waits for");
        var replacementLines = BuildSimpleConsoleProgramLines(goal, waitsForKey).ToList();

        note = ClassifySimpleConsoleProgramNote(goal, waitsForKey);
        return string.Join(newline, replacementLines) + newline;
    }

    private static IReadOnlyList<string> BuildSimpleConsoleProgramLines(string goal, bool waitsForKey)
    {
        var lines = IsConsoleGuessingGameGoal(goal)
            ? BuildGuessingGameConsoleProgramLines()
            : IsConsoleTodoListGoal(goal)
                ? BuildTodoListConsoleProgramLines()
                : IsConsoleNotesAppGoal(goal)
                    ? BuildNotesAppConsoleProgramLines()
                    : TryBuildGenericConsoleListProgramLines(goal, out var genericListLines)
                        ? genericListLines
                        : IsConsoleCalculatorGoal(goal)
                            ? BuildCalculatorConsoleProgramLines()
                            : IsConsoleAddTwoIntegersGoal(goal)
                                ? BuildAddTwoIntegersConsoleProgramLines()
                                : IsConsoleFactorialGoal(goal)
                                    ? BuildFactorialConsoleProgramLines()
                                    : BuildHelloWorldConsoleProgramLines();
        return waitsForKey
            ? lines.Concat(
                [
                    string.Empty,
                    "Console.WriteLine(\"Press any key to exit...\");",
                    "Console.ReadKey(intercept: true);"
                ]).ToList()
            : lines;
    }

    private static bool TryBuildGenericConsoleListProgramLines(string goal, out IReadOnlyList<string> lines)
    {
        lines = [];
        if (!IsGenericConsoleListManagerGoal(goal))
        {
            return false;
        }

        var itemName = InferConsoleListItemName(goal);
        var recipe = new ConsoleListRecipe(
            BuildConsoleListTitle(goal, itemName),
            itemName,
            PluralizeIdentifier(itemName),
            MentionsAny(goal, "file", "save", "saved", "persist", "load", "storage"));
        lines = recipe.FileBacked
            ? BuildFileBackedConsoleListProgramLines(recipe)
            : BuildInMemoryConsoleListProgramLines(recipe);
        return true;
    }

    private static IReadOnlyList<string> BuildInMemoryConsoleListProgramLines(ConsoleListRecipe recipe)
    {
        var itemTitle = CapitalizeInvariant(recipe.ItemName);
        return
        [
            $"var {recipe.VariableName} = new List<string>();",
            string.Empty,
            "while (true)",
            "{",
            "    Console.WriteLine();",
            $"    Console.WriteLine(\"{recipe.Title}\");",
            $"    Console.WriteLine(\"1. Add {recipe.ItemName}\");",
            $"    Console.WriteLine(\"2. List {recipe.VariableName}\");",
            $"    Console.WriteLine(\"3. Remove {recipe.ItemName}\");",
            "    Console.WriteLine(\"4. Quit\");",
            "    Console.Write(\"Choose an option: \");",
            "    var choice = Console.ReadLine();",
            string.Empty,
            "    if (choice == \"1\")",
            "    {",
            $"        Console.Write(\"{itemTitle}: \");",
            $"        var {recipe.ItemName} = Console.ReadLine();",
            $"        if (!string.IsNullOrWhiteSpace({recipe.ItemName}))",
            "        {",
            $"            {recipe.VariableName}.Add({recipe.ItemName}.Trim());",
            $"            Console.WriteLine(\"{itemTitle} added.\");",
            "        }",
            "    }",
            "    else if (choice == \"2\")",
            "    {",
            $"        if ({recipe.VariableName}.Count == 0)",
            "        {",
            $"            Console.WriteLine(\"No {recipe.VariableName} yet.\");",
            "        }",
            "        else",
            "        {",
            $"            for (var index = 0; index < {recipe.VariableName}.Count; index++)",
            "            {",
            $"                Console.WriteLine($\"{{index + 1}}. {{{recipe.VariableName}[index]}}\");",
            "            }",
            "        }",
            "    }",
            "    else if (choice == \"3\")",
            "    {",
            $"        Console.Write(\"{itemTitle} number to remove: \");",
            $"        if (int.TryParse(Console.ReadLine(), out var itemNumber) && itemNumber >= 1 && itemNumber <= {recipe.VariableName}.Count)",
            "        {",
            $"            {recipe.VariableName}.RemoveAt(itemNumber - 1);",
            $"            Console.WriteLine(\"{itemTitle} removed.\");",
            "        }",
            "        else",
            "        {",
            $"            Console.WriteLine(\"That {recipe.ItemName} number was not found.\");",
            "        }",
            "    }",
            "    else if (choice == \"4\")",
            "    {",
            "        break;",
            "    }",
            "    else",
            "    {",
            "        Console.WriteLine(\"Please choose 1, 2, 3, or 4.\");",
            "    }",
            "}"
        ];
    }

    private static IReadOnlyList<string> BuildFileBackedConsoleListProgramLines(ConsoleListRecipe recipe)
    {
        var itemTitle = CapitalizeInvariant(recipe.ItemName);
        var fileName = $"{recipe.VariableName}.txt";
        return
        [
            $"const string storagePath = \"{fileName}\";",
            $"var {recipe.VariableName} = System.IO.File.Exists(storagePath) ? new List<string>(System.IO.File.ReadAllLines(storagePath)) : new List<string>();",
            string.Empty,
            "while (true)",
            "{",
            "    Console.WriteLine();",
            $"    Console.WriteLine(\"{recipe.Title}\");",
            $"    Console.WriteLine(\"1. Add {recipe.ItemName}\");",
            $"    Console.WriteLine(\"2. List {recipe.VariableName}\");",
            $"    Console.WriteLine(\"3. Remove {recipe.ItemName}\");",
            "    Console.WriteLine(\"4. Quit\");",
            "    Console.Write(\"Choose an option: \");",
            "    var choice = Console.ReadLine();",
            string.Empty,
            "    if (choice == \"1\")",
            "    {",
            $"        Console.Write(\"{itemTitle}: \");",
            $"        var {recipe.ItemName} = Console.ReadLine();",
            $"        if (!string.IsNullOrWhiteSpace({recipe.ItemName}))",
            "        {",
            $"            {recipe.VariableName}.Add({recipe.ItemName}.Trim());",
            $"            System.IO.File.AppendAllText(storagePath, {recipe.ItemName}.Trim() + Environment.NewLine);",
            $"            Console.WriteLine(\"{itemTitle} saved.\");",
            "        }",
            "    }",
            "    else if (choice == \"2\")",
            "    {",
            $"        {recipe.VariableName} = System.IO.File.Exists(storagePath) ? new List<string>(System.IO.File.ReadAllLines(storagePath)) : new List<string>();",
            $"        if ({recipe.VariableName}.Count == 0)",
            "        {",
            $"            Console.WriteLine(\"No {recipe.VariableName} saved yet.\");",
            "        }",
            "        else",
            "        {",
            $"            for (var index = 0; index < {recipe.VariableName}.Count; index++)",
            "            {",
            $"                Console.WriteLine($\"{{index + 1}}. {{{recipe.VariableName}[index]}}\");",
            "            }",
            "        }",
            "    }",
            "    else if (choice == \"3\")",
            "    {",
            $"        Console.Write(\"{itemTitle} number to remove: \");",
            $"        if (int.TryParse(Console.ReadLine(), out var itemNumber) && itemNumber >= 1 && itemNumber <= {recipe.VariableName}.Count)",
            "        {",
            $"            {recipe.VariableName}.RemoveAt(itemNumber - 1);",
            $"            System.IO.File.WriteAllLines(storagePath, {recipe.VariableName});",
            $"            Console.WriteLine(\"{itemTitle} removed.\");",
            "        }",
            "        else",
            "        {",
            $"            Console.WriteLine(\"That {recipe.ItemName} number was not found.\");",
            "        }",
            "    }",
            "    else if (choice == \"4\")",
            "    {",
            "        break;",
            "    }",
            "    else",
            "    {",
            "        Console.WriteLine(\"Please choose 1, 2, 3, or 4.\");",
            "    }",
            "}"
        ];
    }

    private static string InferConsoleListItemName(string goal)
    {
        if (MentionsAny(goal, "contact", "contacts", "address book"))
        {
            return "contact";
        }

        if (MentionsAny(goal, "book", "books", "library"))
        {
            return "book";
        }

        if (MentionsAny(goal, "recipe", "recipes"))
        {
            return "recipe";
        }

        if (MentionsAny(goal, "movie", "movies", "watch list"))
        {
            return "movie";
        }

        if (MentionsAny(goal, "task", "tasks", "todo", "to-do"))
        {
            return "task";
        }

        return "item";
    }

    private static string BuildConsoleListTitle(string goal, string itemName)
    {
        if (MentionsAny(goal, "shopping", "grocery"))
        {
            return "Shopping List";
        }

        if (MentionsAny(goal, "inventory"))
        {
            return "Inventory";
        }

        if (MentionsAny(goal, "address book", "contact", "contacts"))
        {
            return "Contact Manager";
        }

        if (MentionsAny(goal, "library"))
        {
            return "Library";
        }

        return $"{CapitalizeInvariant(itemName)} Manager";
    }

    private static string PluralizeIdentifier(string itemName) =>
        itemName.EndsWith("y", StringComparison.OrdinalIgnoreCase)
            ? itemName[..^1] + "ies"
            : itemName.EndsWith("s", StringComparison.OrdinalIgnoreCase)
                ? itemName
                : itemName + "s";

    private static string CapitalizeInvariant(string value) =>
        string.IsNullOrWhiteSpace(value)
            ? "Item"
            : char.ToUpperInvariant(value[0]) + value[1..];

    private sealed record ConsoleListRecipe(string Title, string ItemName, string VariableName, bool FileBacked);

    private static IReadOnlyList<string> BuildHelloWorldConsoleProgramLines() =>
        ["Console.WriteLine(\"Hello, World!\");"];

    private static IReadOnlyList<string> BuildAddTwoIntegersConsoleProgramLines() =>
    [
        "Console.Write(\"Enter the first integer: \");",
        "var firstInput = Console.ReadLine();",
        string.Empty,
        "Console.Write(\"Enter the second integer: \");",
        "var secondInput = Console.ReadLine();",
        string.Empty,
        "if (!int.TryParse(firstInput, out var firstNumber) || !int.TryParse(secondInput, out var secondNumber))",
        "{",
        "    Console.WriteLine(\"Please enter valid whole numbers.\");",
        "}",
        "else",
        "{",
        "    var sum = firstNumber + secondNumber;",
        "    Console.WriteLine($\"{firstNumber} + {secondNumber} = {sum}\");",
        "}"
    ];

    private static IReadOnlyList<string> BuildCalculatorConsoleProgramLines() =>
    [
        "Console.Write(\"Enter the first number: \");",
        "var firstInput = Console.ReadLine();",
        string.Empty,
        "Console.Write(\"Enter an operator (+, -, *, /): \");",
        "var operation = Console.ReadLine()?.Trim();",
        string.Empty,
        "Console.Write(\"Enter the second number: \");",
        "var secondInput = Console.ReadLine();",
        string.Empty,
        "if (!double.TryParse(firstInput, out var firstNumber) || !double.TryParse(secondInput, out var secondNumber))",
        "{",
        "    Console.WriteLine(\"Please enter valid numbers.\");",
        "}",
        "else",
        "{",
        "    var resultText = operation switch",
        "    {",
        "        \"+\" => $\"{firstNumber} + {secondNumber} = {firstNumber + secondNumber}\",",
        "        \"-\" => $\"{firstNumber} - {secondNumber} = {firstNumber - secondNumber}\",",
        "        \"*\" => $\"{firstNumber} * {secondNumber} = {firstNumber * secondNumber}\",",
        "        \"/\" when secondNumber != 0 => $\"{firstNumber} / {secondNumber} = {firstNumber / secondNumber}\",",
        "        \"/\" => \"Cannot divide by zero.\",",
        "        _ => \"Unknown operator. Please use +, -, *, or /.\"",
        "    };",
        string.Empty,
        "    Console.WriteLine(resultText);",
        "}"
    ];

    private static IReadOnlyList<string> BuildGuessingGameConsoleProgramLines() =>
    [
        "var targetNumber = Random.Shared.Next(1, 101);",
        "var attempts = 0;",
        string.Empty,
        "Console.WriteLine(\"I picked a number between 1 and 100.\");",
        string.Empty,
        "while (true)",
        "{",
        "    Console.Write(\"Enter your guess: \");",
        "    var input = Console.ReadLine();",
        "    if (!int.TryParse(input, out var guess))",
        "    {",
        "        Console.WriteLine(\"Please enter a whole number.\");",
        "        continue;",
        "    }",
        string.Empty,
        "    attempts++;",
        "    if (guess < targetNumber)",
        "    {",
        "        Console.WriteLine(\"Too low.\");",
        "    }",
        "    else if (guess > targetNumber)",
        "    {",
        "        Console.WriteLine(\"Too high.\");",
        "    }",
        "    else",
        "    {",
        "        Console.WriteLine($\"Correct! You guessed it in {attempts} attempt(s).\");",
        "        break;",
        "    }",
        "}"
    ];

