    private static string BuildWpfDashboardStylesXaml() =>
        """
        <ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                            xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
            <SolidColorBrush x:Key="DashboardHeaderBrush" Color="#202A36" />
            <SolidColorBrush x:Key="DashboardHeaderForegroundBrush" Color="#FFFFFF" />
            <SolidColorBrush x:Key="DashboardSubtleForegroundBrush" Color="#C8D2DF" />
            <SolidColorBrush x:Key="DashboardAccentBrush" Color="#1F6FEB" />
            <SolidColorBrush x:Key="DashboardAccentHoverBrush" Color="#2F81F7" />

            <Style x:Key="DashboardHeaderCardStyle" TargetType="Border">
                <Setter Property="Padding" Value="14" />
                <Setter Property="Margin" Value="0,0,0,12" />
                <Setter Property="Background" Value="{StaticResource DashboardHeaderBrush}" />
                <Setter Property="CornerRadius" Value="4" />
            </Style>

            <Style x:Key="DashboardHeaderTextStyle" TargetType="TextBlock">
                <Setter Property="FontSize" Value="24" />
                <Setter Property="FontWeight" Value="SemiBold" />
                <Setter Property="Foreground" Value="{StaticResource DashboardHeaderForegroundBrush}" />
            </Style>

            <Style x:Key="DashboardSubtleTextStyle" TargetType="TextBlock">
                <Setter Property="Foreground" Value="{StaticResource DashboardSubtleForegroundBrush}" />
                <Setter Property="TextWrapping" Value="Wrap" />
            </Style>

            <Style x:Key="DashboardPrimaryButtonStyle" TargetType="Button">
                <Setter Property="MinWidth" Value="92" />
                <Setter Property="Height" Value="34" />
                <Setter Property="Padding" Value="12,0" />
                <Setter Property="Background" Value="{StaticResource DashboardAccentBrush}" />
                <Setter Property="Foreground" Value="White" />
                <Setter Property="BorderThickness" Value="0" />
                <Setter Property="FontWeight" Value="SemiBold" />
                <Style.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                        <Setter Property="Background" Value="{StaticResource DashboardAccentHoverBrush}" />
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.55" />
                    </Trigger>
                </Style.Triggers>
            </Style>

            <Style x:Key="DashboardInputTextBoxStyle" TargetType="TextBox">
                <Setter Property="Height" Value="32" />
                <Setter Property="Margin" Value="0,0,0,8" />
                <Setter Property="VerticalContentAlignment" Value="Center" />
                <Setter Property="Padding" Value="6,0" />
                <Style.Triggers>
                    <Trigger Property="Validation.HasError" Value="True">
                        <Setter Property="BorderBrush" Value="#B42318" />
                        <Setter Property="BorderThickness" Value="2" />
                    </Trigger>
                </Style.Triggers>
            </Style>

            <Style x:Key="DashboardPaneGroupBoxStyle" TargetType="GroupBox">
                <Setter Property="Padding" Value="10" />
                <Setter Property="Margin" Value="0" />
            </Style>

            <Style x:Key="DashboardDetailCardStyle" TargetType="Border">
                <Setter Property="Padding" Value="12" />
                <Setter Property="Margin" Value="0" />
                <Setter Property="BorderThickness" Value="1" />
                <Setter Property="BorderBrush" Value="#D0D7DE" />
                <Setter Property="CornerRadius" Value="4" />
            </Style>
        </ResourceDictionary>
        """;

    private static string BuildWpfComplexDashboardViewModel(string? namespaceName)
    {
        var namespaceLine = string.IsNullOrWhiteSpace(namespaceName)
            ? string.Empty
            : $"namespace {namespaceName};{Environment.NewLine}{Environment.NewLine}";
        return
            $$"""
            using System;
            using System.Collections;
            using System.Collections.Generic;
            using System.Collections.ObjectModel;
            using System.ComponentModel;
            using System.Runtime.CompilerServices;
            using System.Threading;
            using System.Threading.Tasks;
            using System.Windows.Data;
            using System.Windows.Input;

            {{namespaceLine}}public sealed class MainWindowViewModel : INotifyPropertyChanged, INotifyDataErrorInfo
            {
                private readonly Dictionary<string, List<string>> _errors = new();
                private string _newItemName = string.Empty;
                private string _newItemError = string.Empty;
                private string _searchText = string.Empty;
                private CancellationTokenSource? _refreshCancellation;
                private bool _isBusy;
                private string _progressText = "Idle";
                private DashboardNavigationItem? _selectedNavigation;
                private string _selectedNavigationSummary = "Navigation, tabs, data, details, and status in one resizable WPF shell.";
                private int _selectedViewIndex;
                private bool _synchronizingNavigation;
                private DashboardItem? _selectedItem;
                private string _statusText = "Ready";

                public MainWindowViewModel()
                {
                    ItemsView = CollectionViewSource.GetDefaultView(Items);
                    ItemsView.Filter = FilterItem;
                    ConfigureItemsView();
                    RefreshCommand = new AsyncRelayCommand(_ => RefreshAsync(), _ => !IsBusy);
                    CancelRefreshCommand = new RelayCommand(_ => CancelRefresh(), _ => IsBusy);
                    AddItemCommand = new RelayCommand(_ => AddItem(), _ => CanAddItem());
                    SeedNavigation();
                    SeedDashboard();
                }

                public event PropertyChangedEventHandler? PropertyChanged;

                public event EventHandler<DataErrorsChangedEventArgs>? ErrorsChanged;

                public ObservableCollection<DashboardItem> Items { get; } = new();

                public ICollectionView ItemsView { get; }

                public ObservableCollection<string> Activity { get; } = new();

                public ObservableCollection<DashboardNavigationItem> NavigationItems { get; } = new();

                public ICommand RefreshCommand { get; }

                public ICommand CancelRefreshCommand { get; }

                public ICommand AddItemCommand { get; }

                public string NewItemName
                {
                    get => _newItemName;
                    set
                    {
                        if (SetField(ref _newItemName, value))
                        {
                            ValidateNewItemName();
                        }
                    }
                }

                public string NewItemError
                {
                    get => _newItemError;
                    private set => SetField(ref _newItemError, value);
                }

                public bool HasErrors => _errors.Count > 0;

                public DashboardNavigationItem? SelectedNavigation
                {
                    get => _selectedNavigation;
                    private set => SetField(ref _selectedNavigation, value);
                }

                public string SelectedNavigationSummary
                {
                    get => _selectedNavigationSummary;
                    private set => SetField(ref _selectedNavigationSummary, value);
                }

                public int SelectedViewIndex
                {
                    get => _selectedViewIndex;
                    set
                    {
                        if (SetField(ref _selectedViewIndex, value) && !_synchronizingNavigation)
                        {
                            SelectNavigationByViewIndex(value);
                        }
                    }
                }

                public string SearchText
                {
                    get => _searchText;
                    set
                    {
                        var normalized = value ?? string.Empty;
                        if (SetField(ref _searchText, normalized))
                        {
                            ItemsView.Refresh();
                            SelectedItem = FirstVisibleItem();
                            StatusText = string.IsNullOrWhiteSpace(SearchText)
                                ? $"Ready - {Items.Count} items loaded"
                                : $"Filtered by \"{SearchText}\"";
                        }
                    }
                }

                public bool IsBusy
                {
                    get => _isBusy;
                    private set
                    {
                        if (SetField(ref _isBusy, value))
                        {
                            ((AsyncRelayCommand)RefreshCommand).RaiseCanExecuteChanged();
                            ((RelayCommand)CancelRefreshCommand).RaiseCanExecuteChanged();
                            ((RelayCommand)AddItemCommand).RaiseCanExecuteChanged();
                        }
                    }
                }

                public string ProgressText
                {
                    get => _progressText;
                    private set => SetField(ref _progressText, value);
                }

                public DashboardItem? SelectedItem
                {
                    get => _selectedItem;
                    set => SetField(ref _selectedItem, value);
                }

                public string StatusText
                {
                    get => _statusText;
                    private set => SetField(ref _statusText, value);
                }

                private void SeedNavigation()
                {
                    NavigationItems.Clear();
                    var overview = CreateNavigationItem("Overview", "Review current dashboard items, filters, and selected detail records.", 0);
                    var activity = CreateNavigationItem("Activity", "Inspect recent dashboard activity and refresh history.", 1);
                    var settings = CreateNavigationItem("Settings", "Settings are represented as a navigation state until a dedicated settings view is added.", 0);
                    var workspace = CreateNavigationItem("Workspace", "Project workspace navigation.", 0);
                    workspace.IsExpanded = true;
                    workspace.Children.Add(overview);
                    workspace.Children.Add(activity);
                    workspace.Children.Add(settings);
                    NavigationItems.Add(workspace);
                    overview.IsSelected = true;
                }

                private DashboardNavigationItem CreateNavigationItem(string header, string summary, int viewIndex) =>
                    new(header, summary, viewIndex, SelectNavigationItem);

                private void SelectNavigationByViewIndex(int viewIndex)
                {
                    var match = FindNavigationItemByViewIndex(NavigationItems, viewIndex);
                    if (match is not null)
                    {
                        match.IsSelected = true;
                    }
                }

                private DashboardNavigationItem? FindNavigationItemByViewIndex(IEnumerable<DashboardNavigationItem> items, int viewIndex)
                {
                    foreach (var item in items)
                    {
                        if (item.ViewIndex == viewIndex && item.Children.Count == 0)
                        {
                            return item;
                        }

                        var childMatch = FindNavigationItemByViewIndex(item.Children, viewIndex);
                        if (childMatch is not null)
                        {
                            return childMatch;
                        }
                    }

                    return null;
                }

                private void SelectNavigationItem(DashboardNavigationItem item)
                {
                    if (_synchronizingNavigation)
                    {
                        return;
                    }

                    _synchronizingNavigation = true;
                    try
                    {
                        if (SelectedNavigation is not null && !ReferenceEquals(SelectedNavigation, item))
                        {
                            SelectedNavigation.IsSelected = false;
                        }

                        SelectedNavigation = item;
                        SelectedNavigationSummary = item.Summary;
                        SelectedViewIndex = item.ViewIndex;
                        StatusText = $"View: {item.Header}";
                    }
                    finally
                    {
                        _synchronizingNavigation = false;
                    }
                }

                private void SeedDashboard()
                {
                    Items.Clear();
                    Items.Add(new DashboardItem("Intake workflow", "Ali", "Ready"));
                    Items.Add(new DashboardItem("Validation queue", "Owner", "Review"));
                    Items.Add(new DashboardItem("Release packet", "Ali", "Draft"));

                    Activity.Clear();
                    Activity.Add("Dashboard loaded.");
                    Activity.Add("Three sample work items are ready for review.");
                    ItemsView.Refresh();
                    SelectedItem = FirstVisibleItem();
                    StatusText = "Ready - 3 items loaded";
                }

                private async Task RefreshAsync()
                {
                    using var cancellation = new CancellationTokenSource();
                    _refreshCancellation = cancellation;
                    try
                    {
                        IsBusy = true;
                        ProgressText = "Refreshing data...";
                        StatusText = "Refreshing dashboard";
                        await Task.Delay(250, cancellation.Token);
                        ItemsView.Refresh();
                        Activity.Insert(0, $"Refreshed at {DateTime.Now:t}.");
                        ProgressText = "Refresh complete";
                        StatusText = "Dashboard refreshed";
                    }
                    catch (OperationCanceledException)
                    {
                        Activity.Insert(0, "Refresh canceled.");
                        ProgressText = "Refresh canceled";
                        StatusText = "Refresh canceled";
                    }
                    finally
                    {
                        _refreshCancellation = null;
                        IsBusy = false;
                    }
                }

                private void CancelRefresh() => _refreshCancellation?.Cancel();

                public IEnumerable GetErrors(string? propertyName)
                {
                    if (string.IsNullOrWhiteSpace(propertyName))
                    {
                        var allErrors = new List<string>();
                        foreach (var errors in _errors.Values)
                        {
                            allErrors.AddRange(errors);
                        }

                        return allErrors;
                    }

                    return _errors.TryGetValue(propertyName, out var propertyErrors)
                        ? propertyErrors
                        : Array.Empty<string>();
                }

                private bool CanAddItem() => !IsBusy && !HasErrors && !string.IsNullOrWhiteSpace(NewItemName);

                private void AddItem()
                {
                    var name = NewItemName.Trim();
                    if (name.Length == 0)
                    {
                        StatusText = "Enter an item name first.";
                        return;
                    }

                    ValidateNewItemName();
                    if (!CanAddItem())
                    {
                        StatusText = string.IsNullOrWhiteSpace(NewItemError) ? "Fix the item name first." : NewItemError;
                        return;
                    }

                    var item = new DashboardItem(name, "Owner", "New");
                    Items.Add(item);
                    ItemsView.Refresh();
                    SelectedItem = FilterItem(item) ? item : FirstVisibleItem();
                    Activity.Insert(0, $"Added {name}.");
                    NewItemName = string.Empty;
                    StatusText = $"Added {name}";
                }

                private void ValidateNewItemName()
                {
                    var errors = new List<string>();
                    var name = NewItemName.Trim();
                    if (name.Length > 60)
                    {
                        errors.Add("Use 60 characters or fewer.");
                    }

                    if (name.Length > 0 && ContainsItemName(name))
                    {
                        errors.Add("An item with this name already exists.");
                    }

                    SetErrors(nameof(NewItemName), errors);
                    NewItemError = errors.Count > 0 ? errors[0] : string.Empty;
                    ((RelayCommand)AddItemCommand).RaiseCanExecuteChanged();
                }

                private bool ContainsItemName(string name)
                {
                    foreach (var item in Items)
                    {
                        if (string.Equals(item.Name, name, StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }
                    }

                    return false;
                }

                private void SetErrors(string propertyName, IReadOnlyList<string> errors)
                {
                    var changed = errors.Count == 0
                        ? _errors.Remove(propertyName)
                        : true;
                    if (errors.Count > 0)
                    {
                        _errors[propertyName] = new List<string>(errors);
                    }

                    if (changed)
                    {
                        ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
                        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(HasErrors)));
                    }
                }

                private void ConfigureItemsView()
                {
                    ItemsView.SortDescriptions.Clear();
                    ItemsView.SortDescriptions.Add(new SortDescription(nameof(DashboardItem.Status), ListSortDirection.Ascending));
                    ItemsView.SortDescriptions.Add(new SortDescription(nameof(DashboardItem.Name), ListSortDirection.Ascending));
                    ItemsView.GroupDescriptions?.Clear();
                    ItemsView.GroupDescriptions?.Add(new PropertyGroupDescription(nameof(DashboardItem.Status)));
                }

                private bool FilterItem(object item)
                {
                    if (item is not DashboardItem dashboardItem)
                    {
                        return false;
                    }

                    if (string.IsNullOrWhiteSpace(SearchText))
                    {
                        return true;
                    }

                    return dashboardItem.Name.Contains(SearchText, StringComparison.OrdinalIgnoreCase)
                           || dashboardItem.Owner.Contains(SearchText, StringComparison.OrdinalIgnoreCase)
                           || dashboardItem.Status.Contains(SearchText, StringComparison.OrdinalIgnoreCase);
                }

                private DashboardItem? FirstVisibleItem()
                {
                    foreach (var item in ItemsView)
                    {
                        if (item is DashboardItem dashboardItem)
                        {
                            return dashboardItem;
                        }
                    }

                    return null;
                }

                private bool SetField<T>(ref T field, T value, [CallerMemberName] string? propertyName = null)
                {
                    if (Equals(field, value))
                    {
                        return false;
                    }

                    field = value;
                    PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
                    return true;
                }

                public sealed record DashboardItem(string Name, string Owner, string Status);

                public sealed class DashboardNavigationItem : INotifyPropertyChanged
                {
                    private readonly Action<DashboardNavigationItem> _select;
                    private bool _isExpanded;
                    private bool _isSelected;

                    public DashboardNavigationItem(string header, string summary, int viewIndex, Action<DashboardNavigationItem> select)
                    {
                        Header = header;
                        Summary = summary;
                        ViewIndex = viewIndex;
                        _select = select;
                    }

                    public event PropertyChangedEventHandler? PropertyChanged;

                    public string Header { get; }

                    public string Summary { get; }

                    public int ViewIndex { get; }

                    public ObservableCollection<DashboardNavigationItem> Children { get; } = new();

                    public bool IsExpanded
                    {
                        get => _isExpanded;
                        set => SetField(ref _isExpanded, value);
                    }

                    public bool IsSelected
                    {
                        get => _isSelected;
                        set
                        {
                            if (SetField(ref _isSelected, value) && value)
                            {
                                _select(this);
                            }
                        }
                    }

                    private bool SetField<T>(ref T field, T value, [CallerMemberName] string? propertyName = null)
                    {
                        if (Equals(field, value))
                        {
                            return false;
                        }

                        field = value;
                        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
                        return true;
                    }
                }

                private sealed class AsyncRelayCommand : ICommand
                {
                    private readonly Func<object?, Task> _execute;
                    private readonly Predicate<object?>? _canExecute;
                    private bool _isExecuting;

                    public AsyncRelayCommand(Func<object?, Task> execute, Predicate<object?>? canExecute = null)
                    {
                        _execute = execute;
                        _canExecute = canExecute;
                    }

                    public event EventHandler? CanExecuteChanged;

                    public bool CanExecute(object? parameter) => !_isExecuting && (_canExecute?.Invoke(parameter) ?? true);

                    public async void Execute(object? parameter)
                    {
                        if (!CanExecute(parameter))
                        {
                            return;
                        }

                        try
                        {
                            _isExecuting = true;
                            RaiseCanExecuteChanged();
                            await _execute(parameter);
                        }
                        finally
                        {
                            _isExecuting = false;
                            RaiseCanExecuteChanged();
                        }
                    }

                    public void RaiseCanExecuteChanged() => CanExecuteChanged?.Invoke(this, EventArgs.Empty);
                }

                private sealed class RelayCommand : ICommand
                {
                    private readonly Action<object?> _execute;
                    private readonly Predicate<object?>? _canExecute;

                    public RelayCommand(Action<object?> execute, Predicate<object?>? canExecute = null)
                    {
                        _execute = execute;
                        _canExecute = canExecute;
                    }

                    public event EventHandler? CanExecuteChanged;

                    public bool CanExecute(object? parameter) => _canExecute?.Invoke(parameter) ?? true;

                    public void Execute(object? parameter) => _execute(parameter);

                    public void RaiseCanExecuteChanged() => CanExecuteChanged?.Invoke(this, EventArgs.Empty);
                }
            }
            """;
    }

    private static string? ExtractXamlClassName(string content)
    {
        var match = Regex.Match(
            content,
            @"x:Class\s*=\s*""(?<name>[^""]+)""",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        return match.Success ? match.Groups["name"].Value.Trim() : null;
    }

    private static string? ExtractCSharpNamespaceName(string content)
    {
        var match = Regex.Match(
            content,
            """\bnamespace\s+(?<name>[A-Za-z_][\w.]*)\s*(?:;|\{)""",
            RegexOptions.CultureInvariant);
        return match.Success ? match.Groups["name"].Value.Trim() : null;
    }

    private static bool IsSimpleWpfProgramGoal(string goal)
    {
        if (string.IsNullOrWhiteSpace(goal))
        {
            return false;
        }

        return (MentionsAny(goal, "wpf", "xaml", "desktop window", "desktop app", "windowed app") || IsWpfComplexWindowGoal(goal))
               && (IsWpfCounterGoal(goal)
                   || IsWpfCalculatorGoal(goal)
                   || IsWpfGreetingGoal(goal)
                   || IsWpfTodoGoal(goal)
                   || IsWpfComplexWindowGoal(goal)
                   || IsWpfHelloGoal(goal)
                   || MentionsAny(goal, "button", "window", "screen"));
    }

    private static bool NeedsWpfCodeBehind(string goal) =>
        IsWpfCounterGoal(goal)
        || IsWpfCalculatorGoal(goal)
        || IsWpfGreetingGoal(goal)
        || IsWpfTodoGoal(goal)
        || IsWpfComplexWindowGoal(goal);

    private static string ClassifyWpfStarterNote(string goal, string fileName)
    {
        var shape = IsWpfComplexWindowGoal(goal)
            ? "WPF complex-dashboard"
            : IsWpfTodoGoal(goal)
                ? "WPF todo-list"
                : IsWpfCalculatorGoal(goal)
                    ? "WPF calculator"
                    : IsWpfGreetingGoal(goal)
                        ? "WPF greeting-form"
                        : IsWpfCounterGoal(goal)
                            ? "WPF counter"
                            : "WPF hello";
        return $"{shape} {fileName} starter recipe.";
    }

    private static bool IsWpfCounterGoal(string goal) =>
        MentionsAny(goal, "counter", "count", "increment", "increase")
        && MentionsAny(goal, "button", "click", "press");

    private static bool IsWpfCalculatorGoal(string goal) =>
        MentionsAny(goal, "calculator", "calculate", "math", "arithmetic")
        || (MentionsAny(goal, "add", "subtract", "multiply", "divide")
            && MentionsAny(goal, "number", "numbers", "operation"));

    private static bool IsWpfGreetingGoal(string goal) =>
        MentionsAny(goal, "greeting", "say hello", "greeter", "ask for a name", "name textbox")
        || (MentionsAny(goal, "hello") && MentionsAny(goal, "name", "textbox", "text box", "input"));

    private static bool IsWpfTodoGoal(string goal) =>
        MentionsAny(goal, "todo", "to-do", "task list", "tasks", "checklist")
        && MentionsAny(goal, "add", "remove", "list", "selected", "button");

    private static bool IsWpfComplexWindowGoal(string goal) =>
        MentionsAny(goal, "dashboard", "control center", "complex window", "advanced window", "multi panel", "multi-pane", "split pane", "master detail", "details pane", "navigation shell", "management window", "manager window", "data entry")
        && MentionsAny(goal, "wpf", "xaml", "desktop", "window", "screen", "app", "layout", "grid", "tabs", "data grid");

    private static bool IsWpfHelloGoal(string goal) =>
        MentionsAny(goal, "hello world", "hello-world", "says hello", "display hello");

    private static bool IsBuildArtifactPath(string path)
    {
        var normalized = path.Replace('\\', '/');
        return normalized.Contains("/bin/", StringComparison.OrdinalIgnoreCase)
            || normalized.Contains("/obj/", StringComparison.OrdinalIgnoreCase);
    }

    private static bool TryBuildAnchorPatchBlock(
        string content,
        IReadOnlyList<string> goalTerms,
        string? preferredTerm,
        out string anchorText,
        out string note)
    {
        anchorText = string.Empty;
        note = string.Empty;
        var terms = new List<string>();
        if (!string.IsNullOrWhiteSpace(preferredTerm))
        {
            terms.Add(preferredTerm);
        }

        terms.AddRange(goalTerms.Where(term => term.Length > 2));
        foreach (var term in terms.Distinct(StringComparer.OrdinalIgnoreCase))
        {
            var index = content.IndexOf(term, StringComparison.OrdinalIgnoreCase);
            if (index >= 0 && TryBuildUniqueContextBlock(content, index, term.Length, out anchorText))
            {
                note = $"Exact anchor around term {term}.";
                return true;
            }
        }

        var fallbackIndex = FindFallbackAnchorIndex(content);
        if (fallbackIndex >= 0 && TryBuildUniqueContextBlock(content, fallbackIndex, 1, out anchorText))
        {
            note = "Exact fallback anchor from the first likely code block.";
            return true;
        }

        return false;
    }

    private static int FindFallbackAnchorIndex(string content)
    {
        var markers = new[] { "class ", "record ", "interface ", "public ", "private ", "<Button", "Command=\"" };
        foreach (var marker in markers)
        {
            var index = content.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
            if (index >= 0)
            {
                return index;
            }
        }

        return content.TakeWhile(char.IsWhiteSpace).Count();
    }

    private static bool TryBuildUniqueContextBlock(string content, int index, int length, out string block)
    {
        block = string.Empty;
        for (var radius = 0; radius <= 4; radius++)
        {
            var start = FindLineWindowStart(content, index, radius);
            var end = FindLineWindowEnd(content, index + length, radius);
            if (end <= start)
            {
                continue;
            }

            var candidate = content[start..end];
            if (!string.IsNullOrWhiteSpace(candidate)
                && CountOrdinalOccurrences(content, candidate) == 1)
            {
                block = candidate;
                return true;
            }
        }

        return false;
    }

    private static int FindLineWindowStart(string content, int index, int linesBefore)
    {
        var start = Math.Clamp(index, 0, content.Length);
        for (var i = 0; i <= linesBefore; i++)
        {
            var previous = content.LastIndexOf('\n', Math.Max(0, start - 1));
            if (previous < 0)
            {
                return 0;
            }

            start = previous;
        }

        return Math.Min(content.Length, start + 1);
    }

    private static int FindLineWindowEnd(string content, int index, int linesAfter)
    {
        var end = Math.Clamp(index, 0, content.Length);
        for (var i = 0; i <= linesAfter; i++)
        {
            var next = content.IndexOf('\n', end);
            if (next < 0)
            {
                return content.Length;
            }

            end = next + 1;
        }

        return end;
    }

    private static IReadOnlyList<string> IndentBlock(string value, string indent) =>
        value.Split(["\r\n", "\n", "\r"], StringSplitOptions.None)
            .Select(line => indent + line)
            .ToList();

    private string ClassifyAutonomousPatchLoopStage(FeaturePatchSynthesis synthesis, CodingReceipt? latestValidation)
    {
        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "Repair";
        }

        if (_lastPatchPreviewRequest is not null)
        {
            return "Awaiting approved apply";
        }

        return synthesis.PreviewReady
            ? "Ready to preview synthesized patch"
            : "Draft exact patch text";
    }

    private IReadOnlyList<string> BuildAutonomousPatchLoopRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation)
    {
        var validation = string.IsNullOrWhiteSpace(context.TestTarget.Command)
            ? "resolve test target " + context.Goal
            : context.TestTarget.Command;
        return
        [
            $"1. Synthesize: {(synthesis.PreviewReady ? "Good - preview-ready patch exists" : "Review - exact implementation text still needed")}.",
            _lastPatchPreviewRequest is null ? "2. Preview: Waiting - no pending preview." : "2. Preview: Good - pending preview exists.",
            _lastPatchPreviewRequest is null ? "3. Apply: Waiting for preview." : "3. Apply: Waiting for owner confirmation.",
            $"4. Validate: {validation}.",
            latestValidation?.Succeeded == true ? "5. Repair: Not needed - latest validation passed." : "5. Repair: Ready if validation fails.",
            "6. Retry budget: 0/2 automatic repair drafts used in this session.",
            "7. Receipt: finish with feature completion receipt and safe commit check."
        ];
    }

    private IReadOnlyList<string> BuildFeatureFailureClassifierRows()
    {
        if (_lastDotNetRequest is null || _lastDotNetResult is null)
        {
            return ["State: Waiting - no failed build/test result is loaded."];
        }

        if (_lastDotNetResult.Succeeded)
        {
            return [$"State: Good - {_lastDotNetRequest.Action} passed."];
        }

        var text = _lastDotNetResult.Message;
        var category = text.Contains("CS0103", StringComparison.OrdinalIgnoreCase)
            ? "Missing symbol/name"
            : text.Contains("CS1002", StringComparison.OrdinalIgnoreCase) || text.Contains("CS1513", StringComparison.OrdinalIgnoreCase)
                ? "Syntax or brace/semicolon"
                : text.Contains("InitializeComponent", StringComparison.OrdinalIgnoreCase) || text.Contains("binding", StringComparison.OrdinalIgnoreCase)
                    ? "XAML binding or generated UI glue"
                    : text.Contains("Assert", StringComparison.OrdinalIgnoreCase) || text.Contains("Expected", StringComparison.OrdinalIgnoreCase)
                        ? "Test assertion mismatch"
                        : "General build/test failure";
        return
        [
            $"State: Bad - {_lastDotNetRequest.Action} failed.",
            $"Category: {category}.",
            "Rule: repair the smallest active patch slice, then rerun the same validation command."
        ];
    }

    private string BuildAutonomousPatchLoopNextCommand(
        string goal,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation)
    {
        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "feature patch draft " + goal;
        }

        if (_lastPatchPreviewRequest is not null)
        {
            return "confirm apply last patch preview";
        }

        return synthesis.PreviewReady
            ? "preview synthesized feature patch " + goal
            : "concrete patch authoring " + goal;
    }

    private string ClassifyFeatureSessionStage(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (latestValidation is { Succeeded: false })
        {
            return "Repair validation failure";
        }

        if (_lastPatchPreviewRequest is not null)
        {
            return "Awaiting approved apply";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "Ready for safe commit check" : "Ready for completion receipt";
        }

        if (latestEdit is not null || context.ChangedFiles.Count > 0)
        {
            return "Validate changed files";
        }

        if (synthesis.PreviewReady)
        {
            return "Ready for patch preview";
        }

        if (context.RankedTargets.Count == 0)
        {
            return "Resolve edit target";
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "Resolve validation target";
        }

        return "Draft exact patch text";
    }

    private int BuildFeatureSessionScore(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        var score = 0;
        score += context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase) ? 5 : 10;
        score += context.RankedTargets.Count > 0 ? 20 : 0;
        score += string.IsNullOrWhiteSpace(context.TestTarget.Command) ? 0 : 15;
        score += synthesis.PreviewReady ? 20 : synthesis.Candidates.Count > 0 ? 10 : 0;
        score += _lastPatchPreviewRequest is not null ? 10 : 0;
        score += latestEdit is not null || context.ChangedFiles.Count > 0 ? 10 : 0;
        score += latestValidation?.Succeeded == true ? 15 : latestValidation?.Succeeded == false ? -10 : 0;
        score += gitStatus.Available ? 5 : 0;
        score += gitStatus.Clean && latestValidation?.Succeeded == true ? 5 : 0;
        return Math.Clamp(score, 0, 100);
    }

    private IReadOnlyList<string> BuildFeatureSessionChecklistRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        var rows = new List<string>
        {
            context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase)
                ? "Intent: Review - no specific feature goal was provided."
                : $"Intent: Good - {context.Goal}.",
            context.RankedTargets.Count == 0
                ? "Target: Review - no primary edit file is resolved."
                : $"Target: Good - {context.RankedTargets.First().RelativePath} ({context.RankedTargets.First().Confidence}).",
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "Validation target: Review - no targeted command is resolved."
                : $"Validation target: Good - {context.TestTarget.Command}.",
            synthesis.PreviewReady
                ? $"Synthesis: Good - {synthesis.PreviewEdits.Count} preview-ready edit(s)."
                : synthesis.Candidates.Count > 0
                    ? "Synthesis: Review - exact anchors exist but new implementation text is still needed."
                    : "Synthesis: Waiting - no exact anchor or edit block yet.",
            _lastPatchPreviewRequest is not null
                ? $"Preview: Good - pending {_lastPatchPreviewRequest.Action}."
                : synthesis.PreviewReady
                    ? "Preview: Ready - run preview synthesized feature patch."
                    : "Preview: Waiting - no preview-ready patch yet.",
            latestEdit is not null || context.ChangedFiles.Count > 0
                ? "Apply: Review - changes exist and need validation."
                : _lastPatchPreviewRequest is not null
                    ? "Apply: Waiting - owner confirmation is required."
                    : "Apply: Waiting - preview must come first.",
            latestValidation?.Succeeded == true
                ? "Validation: Good - latest build/test receipt passed."
                : latestValidation?.Succeeded == false
                    ? "Validation: Bad - repair the latest failed build/test receipt."
                    : "Validation: Waiting - run the targeted validation after apply.",
            latestValidation?.Succeeded == true && !gitStatus.HasUncommittedChanges
                ? "Closeout: Good - no uncommitted code changes detected."
                : latestValidation?.Succeeded == true
                    ? "Closeout: Ready - run safe commit check."
                    : "Closeout: Waiting - validation must pass first."
        };
        return rows;
    }

    private IReadOnlyList<string> BuildFeatureSessionEvidenceRows(
        FeatureWorkContext context,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        CodingReceipt? latestGit,
        GitWorkingTreeStatus gitStatus)
    {
        var changed = context.ChangedFiles.Count == 0
            ? "none"
            : FormatInlineList(context.ChangedFiles.Take(6));
        return
        [
            $"Top target: {context.RankedTargets.FirstOrDefault()?.RelativePath ?? "none resolved yet"}.",
            _lastPatchPreviewRequest is null ? "Pending preview: none." : $"Pending preview: {_lastPatchPreviewRequest.Action}.",
            latestEdit is null ? "Latest edit: none." : FormatReceiptSummary("Latest edit", latestEdit),
            latestValidation is null ? "Latest validation: none." : FormatReceiptSummary("Latest validation", latestValidation),
            latestGit is null ? "Latest git check: none." : FormatReceiptSummary("Latest git check", latestGit),
            $"Git: {gitStatus.Summary}",
            $"Changed files: {changed}"
        ];
    }

    private string BuildFeatureSessionNextCommand(
        string goal,
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit)
    {
        if (latestValidation is { Succeeded: false })
        {
            return "feature patch draft " + goal;
        }

        if (_lastPatchPreviewRequest is not null)
        {
            return "confirm apply last patch preview";
        }

        if (latestEdit is not null || context.ChangedFiles.Count > 0)
        {
            return latestValidation?.Succeeded == true
                ? "feature completion receipt"
                : "post patch validation " + goal;
        }

        if (synthesis.PreviewReady)
        {
            return "preview synthesized feature patch " + goal;
        }

        if (context.RankedTargets.Count == 0)
        {
            return "feature work context " + goal;
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "resolve test target " + goal;
        }

        return "concrete patch authoring " + goal;
    }

    private static bool IsFeatureEditReceipt(CodingReceipt receipt) =>
        receipt.Action is nameof(CodingToolAction.ApplyLastPatchPreview)
            or nameof(CodingToolAction.ReplaceText)
            or nameof(CodingToolAction.CreateFile)
            or nameof(CodingToolAction.AppendFile);

    private static bool IsFeatureGitReceipt(CodingReceipt receipt) =>
        receipt.Action.StartsWith("Git", StringComparison.OrdinalIgnoreCase)
        || receipt.Action is nameof(CodingToolAction.GitStatus)
            or nameof(CodingToolAction.GitDiff)
            or nameof(CodingToolAction.GitLog)
            or nameof(CodingToolAction.ReviewCurrentChanges)
            or nameof(CodingToolAction.GitAdd)
            or nameof(CodingToolAction.GitCommit);

    private static bool ShouldAttemptDeterministicRepairPreview(string output) =>
        output.Contains("CS1002", StringComparison.OrdinalIgnoreCase)
            && output.Contains("; expected", StringComparison.OrdinalIgnoreCase)
        || output.Contains("CS1513", StringComparison.OrdinalIgnoreCase)
            && output.Contains("} expected", StringComparison.OrdinalIgnoreCase);

    private string BuildValidationRepairStage(string failureType, bool hasPendingPreview, bool previewAttempted)
    {
        if (hasPendingPreview)
        {
            return previewAttempted ? "Deterministic preview prepared" : "Awaiting owner apply";
        }

        return failureType switch
        {
            "locked file" => "Diagnose file lock",
            "restore/package" => "Repair restore or package state",
            "compiler" => "Map compiler diagnostic",
            "test" => "Repair failing test behavior",
            "missing sdk/tool" => "Repair SDK or tool setup",
            _ => "Classify validation failure"
        };
    }

    private IReadOnlyList<string> BuildValidationRepairFocusRows(
        FeatureWorkContext context,
        string primaryDiagnostic,
        CompilerDiagnosticInfo parsed,
        string? absolutePath,
        string? symbolContext)
    {
        var topTarget = context.RankedTargets.FirstOrDefault()?.RelativePath ?? "none resolved yet";
        return
        [
            $"Active slice: {topTarget}.",
            $"First diagnostic: {TrimForChat(primaryDiagnostic, 220)}",
            string.IsNullOrWhiteSpace(parsed.Code) ? "Code: unknown." : $"Code: {parsed.Code}.",
            absolutePath is null ? "File: unknown." : $"File: {RelativeToWorkspace(absolutePath)}.",
            parsed.LineNumber is null ? "Line: unknown." : $"Line: {parsed.LineNumber}.",
            string.IsNullOrWhiteSpace(symbolContext) ? "Nearest symbol: unknown." : $"Nearest symbol: {symbolContext}.",
            $"Targeted validation: {(string.IsNullOrWhiteSpace(context.TestTarget.Command) ? "not resolved yet" : context.TestTarget.Command)}."
        ];
    }

    private static IReadOnlyList<string> BuildValidationRepairStepRows(
        string failureType,
        string primaryDiagnostic,
        string retryCommand)
    {
        if (failureType.Equals("locked file", StringComparison.OrdinalIgnoreCase))
        {
            return
            [
                "1. Inspect - diagnose build lock.",
                "2. Verify - collect process evidence for the owning process.",
                "3. Recover - stop only the confirmed lock owner or shut down dotnet build servers.",
                $"4. Validate - {retryCommand}.",
                "5. Closeout - run validation ledger and safe commit check."
            ];
        }

        if (failureType.Equals("restore/package", StringComparison.OrdinalIgnoreCase))
        {
            return
            [
                "1. Inspect - plan package lookup current failure.",
                "2. Verify - check package id, version, sources, and restore state.",
                "3. Recover - run restore only after owner confirmation.",
                $"4. Validate - {retryCommand}.",
                "5. Closeout - run validation ledger and safe commit check."
            ];
        }

        if (failureType.Equals("test", StringComparison.OrdinalIgnoreCase))
        {
            return
            [
                "1. Inspect - diagnose last test failure.",
                "2. Compare - read expected and actual behavior before editing source.",
                "3. Patch - repair the smallest behavior slice behind preview/apply.",
                $"4. Validate - {retryCommand}.",
                "5. Closeout - run validation ledger and safe commit check."
            ];
        }

        return
        [
            "1. Inspect - open build error.",
            $"2. Map - map compiler diagnostic {TrimForChat(primaryDiagnostic, 140)}",
            "3. Candidate - use the ranked fix candidate with the smallest file/symbol scope.",
            "4. Patch - keep the repair behind patch preview and owner apply confirmation.",
            $"5. Validate - {retryCommand}.",
            "6. Closeout - run validation ledger and safe commit check."
        ];
    }

    private IReadOnlyList<string> BuildValidationRepairRoutingRows(
        string failureType,
        IReadOnlyList<DiagnosticFixCandidate> candidates,
        TestTargetRecommendation testTarget,
        FeatureWorkContext context,
        string retryCommand)
    {
        var topCandidate = candidates.OrderByDescending(candidate => candidate.Score).FirstOrDefault();
        var rows = new List<string>
        {
            topCandidate is null
                ? "Candidate route: Review - no deterministic fix candidate was ranked."
                : $"Candidate route: {topCandidate.Confidence} - {topCandidate.Target}; {topCandidate.NextStep}.",
            string.IsNullOrWhiteSpace(testTarget.Command)
                ? "Retry route: Review - no targeted test command resolved from the diagnostic."
                : $"Retry route: Good - {testTarget.Command}.",
            $"Fallback retry: {retryCommand}.",
            context.RankedTargets.Count == 0
                ? "Slice route: Review - no active implementation slice is tied to this failure."
                : $"Slice route: {context.RankedTargets.First().RelativePath} ({context.RankedTargets.First().Confidence})."
        };

        if (failureType.Equals("test", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Behavior route: compare expected vs actual before changing source; prefer a failing behavior test preview first.");
        }
        else if (failureType.Equals("compiler", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Compiler route: map diagnostic to nearest symbol, preview the smallest literal repair, then rerun the same target.");
        }
        else if (failureType.Equals("restore/package", StringComparison.OrdinalIgnoreCase)
            || failureType.Equals("missing sdk/tool", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Setup route: stop before package/tool changes unless owner confirms the exact restore/install action.");
        }
        else if (failureType.Equals("locked file", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Lock route: collect process evidence before stopping anything.");
        }
        else
        {
            rows.Add("Unknown route: keep changes behind preview and ask for owner review if the first diagnostic is unclear.");
        }

        return rows;
    }

    private string BuildValidationRepairNextCommand(string failureType, string primaryDiagnostic, string retryCommand)
    {
        if (_lastPatchPreviewRequest is not null)
        {
            return "confirm apply last patch preview";
        }

        if (failureType.Equals("locked file", StringComparison.OrdinalIgnoreCase))
        {
            return "diagnose build lock";
        }

        if (failureType.Equals("restore/package", StringComparison.OrdinalIgnoreCase))
        {
            return "plan package lookup current failure";
        }

        if (failureType.Equals("missing sdk/tool", StringComparison.OrdinalIgnoreCase))
        {
            return "show install doctor";
        }

        if (failureType.Equals("test", StringComparison.OrdinalIgnoreCase))
        {
            return "diagnose last test failure";
        }

        if (failureType.Equals("compiler", StringComparison.OrdinalIgnoreCase))
        {
            return "map compiler diagnostic " + TrimForChat(primaryDiagnostic, 180);
        }

        return string.IsNullOrWhiteSpace(retryCommand) ? "diagnose last build failure" : retryCommand;
    }

    private static string BuildValidationRepairRetryCommand(string? command, string goal) =>
        string.IsNullOrWhiteSpace(command)
            ? "resolve test target " + goal
            : command;

    private static string BuildValidationRepairRetryCommand(
        CodingToolRequest failedRequest,
        CodingToolResult failedResult,
        TestTargetRecommendation testTarget,
        FeatureWorkContext context)
    {
        var target = failedResult.TargetPath ?? failedRequest.Path ?? context.TestTarget.TargetPath ?? context.RankedTargets.FirstOrDefault()?.RelativePath;
        if (failedRequest.Action == CodingToolAction.Test && !string.IsNullOrWhiteSpace(testTarget.Command))
        {
            return testTarget.Command;
        }

        if (string.IsNullOrWhiteSpace(target))
        {
            return string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "resolve test target " + context.Goal
                : context.TestTarget.Command;
        }

        var quotedTarget = QuoteForOwnerCommand(target);
        return failedRequest.Action switch
        {
            CodingToolAction.Build => $"confirm dotnet build {quotedTarget}",
            CodingToolAction.Test => $"confirm dotnet test {quotedTarget}",
            CodingToolAction.Restore => $"confirm dotnet restore {quotedTarget}",
            CodingToolAction.RunProject => $"confirm dotnet run {quotedTarget}",
            _ => string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? $"confirm dotnet build {quotedTarget}"
                : context.TestTarget.Command
        };
    }

    private static string QuoteForOwnerCommand(string value) =>
        "\"" + value.Trim().Trim('"').Replace("\"", "\\\"", StringComparison.Ordinal) + "\"";

    private string ClassifyFeatureRunControllerPhase(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (_lastPatchPreviewRequest is not null)
        {
            return "Awaiting owner apply";
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "Repair failed validation";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded != true)
        {
            return "Validate applied change";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "Closeout review" : "Completion receipt";
        }

        if (synthesis.PreviewReady)
        {
            return "Preview synthesized patch";
        }

        if (context.RankedTargets.Count == 0)
        {
            return "Resolve feature target";
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "Resolve validation target";
        }

        return "Draft exact patch";
    }

    private string BuildFeatureRunGoNoGo(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "No-go - repair the failed validation first.";
        }

        if (_lastPatchPreviewRequest is not null)
        {
            return "Hold - owner must review and approve the pending preview.";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded != true)
        {
            return "No-go - changed files need validation.";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "Go - ready for review and safe commit check." : "Go - ready for completion receipt.";
        }

        if (synthesis.PreviewReady)
        {
            return "Go - preview-only patch is ready.";
        }

        if (context.RankedTargets.Count == 0 || string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "Hold - resolve target and validation route first.";
        }

        return "Go - draft the exact patch block.";
    }

    private int BuildFeatureRunControllerScore(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        var score = 0;
        score += context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase) ? 5 : 10;
        score += context.RankedTargets.Count > 0 ? 15 : 0;
        score += string.IsNullOrWhiteSpace(context.TestTarget.Command) ? 0 : 15;
        score += synthesis.PreviewReady ? 15 : synthesis.Candidates.Count > 0 ? 8 : 0;
        score += _lastPatchPreviewRequest is not null ? 10 : 0;
        score += latestEdit is not null || context.ChangedFiles.Count > 0 ? 10 : 0;
        score += latestValidation?.Succeeded == true ? 20 : latestValidation?.Succeeded == false ? -15 : 0;
        score += gitStatus.Available ? 5 : 0;
        score += gitStatus.Clean && latestValidation?.Succeeded == true ? 10 : 0;
        return Math.Clamp(score, 0, 100);
    }

    private IReadOnlyList<string> BuildFeatureRunStateRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit)
    {
        return
        [
            _lastPatchPreviewRequest is null
                ? synthesis.PreviewReady ? "Preview: Ready - synthesized preview can be shown." : "Preview: Waiting - no pending preview."
                : $"Preview: Pending - {_lastPatchPreviewRequest.Action}.",
            latestEdit is null && context.ChangedFiles.Count == 0
                ? "Apply: Waiting - no applied edit or changed file evidence."
                : $"Apply: Review - {Math.Max(context.ChangedFiles.Count, latestEdit is null ? 0 : 1)} edit signal(s) present.",
            latestValidation?.Succeeded == true
                ? "Validation: Good - latest build/test receipt passed."
                : latestValidation?.Succeeded == false
                    ? "Validation: Bad - repair runner should go next."
                    : "Validation: Waiting - no build/test receipt for this run.",
            _lastDotNetResult is { Succeeded: false }
                ? "Repair: Active - failed validation is loaded."
                : "Repair: Clear - no active failed validation loaded.",
            context.RankedTargets.Count == 0
                ? "Target: Review - no ranked edit target."
                : $"Target: Good - {context.RankedTargets.First().RelativePath} ({context.RankedTargets.First().Confidence}).",
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "Validation route: Review - no targeted command resolved."
                : $"Validation route: Good - {context.TestTarget.Command}."
        ];
    }

    private IReadOnlyList<string> BuildFeatureRunStopGateRows(
        FeatureWorkContext context,
        CodingReceipt? latestValidation,
        GitWorkingTreeStatus gitStatus)
    {
        var rows = new List<string>();
        if (_lastPatchPreviewRequest is not null)
        {
            rows.Add("Pending preview must be reviewed, applied, or discarded before validation/commit.");
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            rows.Add("Latest validation is failed; run repair before closeout.");
        }

        if (context.ChangedFiles.Count > 0 && latestValidation?.Succeeded != true)
        {
            rows.Add("Changed files exist without passing validation.");
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            rows.Add("Targeted validation command is unresolved.");
        }

        if (context.RiskLabels.Any(label => label.StartsWith("Protected", StringComparison.OrdinalIgnoreCase)
            || label.StartsWith("High", StringComparison.OrdinalIgnoreCase)))
        {
            rows.Add("High-risk/protected file signal requires explicit owner review.");
        }

        if (!gitStatus.Available)
        {
            rows.Add("Git status is unavailable.");
        }

        return rows.Count == 0 ? ["None - controller has no active stop gate."] : rows;
    }

    private string BuildFeatureRunControllerNextCommand(
        string goal,
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (_lastPatchPreviewRequest is not null)
        {
            return "confirm apply last patch preview";
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "validation repair runner " + goal;
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded != true)
        {
            return "post patch validation " + goal;
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "can i safely commit" : "feature completion receipt";
        }

        if (synthesis.PreviewReady)
        {
            return "preview synthesized feature patch " + goal;
        }

        if (context.RankedTargets.Count == 0)
        {
            return "feature work context " + goal;
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "resolve test target " + goal;
        }

        return "concrete patch authoring " + goal;
    }

    private IReadOnlyList<string> BuildFeatureImplementationOrderRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview)
    {
        var rows = new List<string>
        {
            "1. Intake - freeze request, expected result, failure behavior, and confirmation boundary.",
            context.RankedTargets.Count == 0
                ? "2. Targeting - inspect more before editing; no ranked file target is ready."
                : $"2. Targeting - primary file {context.RankedTargets.First().RelativePath} ({context.RankedTargets.First().Confidence}).",
            testPreview.Ready
                ? $"3. Test preview - {testPreview.Command}."
                : $"3. Test preview - hold; {testPreview.Status}",
            synthesis.PreviewReady
                ? $"4. Code preview - preview synthesized feature patch {context.Goal}."
                : "4. Code preview - draft exact before/after text before preview.",
            testPreview.Ready && synthesis.PreviewReady
                ? $"5. Paired bundle - preview guided feature bundle {context.Goal}."
                : "5. Paired bundle - wait until both behavior test and code preview are ready.",
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "6. Validation - resolve targeted test command before apply."
                : $"6. Validation - {context.TestTarget.Command}.",
            "7. Closeout - review current changes, validation receipt, repair runner if failed, then safe commit check."
        };
        return rows;
    }

    private IReadOnlyList<string> BuildFeatureImplementationFileRoleRows(FeatureWorkContext context)
    {
        var rows = new List<string>();
        foreach (var target in context.RankedTargets.Take(6))
        {
            rows.Add($"{target.RelativePath}: {ClassifyFeatureImplementationRole(target.RelativePath)}; confidence {target.Confidence}; risk {target.Risk}; reason {FormatInlineList(target.Reasons.Take(2))}");
        }

        foreach (var file in context.RelativeCandidateFiles.Except(context.RankedTargets.Select(target => target.RelativePath), StringComparer.OrdinalIgnoreCase).Take(6))
        {
            rows.Add($"{file}: {ClassifyFeatureImplementationRole(file)}; risk {ClassifyFileRisk(file)}.");
        }

        return rows.Count == 0 ? ["none resolved yet"] : rows;
    }

    private static string ClassifyFeatureImplementationRole(string path)
    {
        if (IsTestFile(path))
        {
            return "test proof";
        }

        if (path.Contains("RequestParser", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Contracts", StringComparison.OrdinalIgnoreCase))
        {
            return "command surface";
        }

        if (path.Contains("LocalCodingToolService", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Infrastructure", StringComparison.OrdinalIgnoreCase))
        {
            return "execution/service behavior";
        }

        if (path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase)
            || path.Contains("ViewModel", StringComparison.OrdinalIgnoreCase))
        {
            return "dashboard/UI binding";
        }

        if (path.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".props", StringComparison.OrdinalIgnoreCase))
        {
            return "project/dependency metadata";
        }

        return "source behavior";
    }

    private IReadOnlyList<string> BuildFeatureRoslynTargetingRows(FeatureWorkContext context)
    {
        var declarations = context.Graph.Declarations.Take(5).Select(hit => $"{hit.Kind} {hit.Display} at {RelativeToWorkspace(hit.Path)}:{hit.LineNumber}").ToList();
        var references = context.Graph.References.Take(5).Select(hit => $"{hit.Kind} {hit.Display} at {RelativeToWorkspace(hit.Path)}:{hit.LineNumber}").ToList();
        var calls = context.Graph.InboundCalls
            .Concat(context.Graph.OutboundCalls)
            .Take(5)
            .Select(edge => $"{edge.Caller} -> {edge.Callee} at {RelativeToWorkspace(edge.Path)}:{edge.LineNumber}")
            .ToList();
        return
        [
            $"Declarations: {FormatInlineList(declarations)}",
            $"References: {FormatInlineList(references)}",
            $"Call impact: {FormatInlineList(calls)}",
            $"Reference files: {FormatInlineList(context.Graph.ReferenceFiles.Take(8))}",
            $"Likely test symbols: {FormatInlineList(context.Graph.TestSymbols.Take(8))}"
        ];
    }

    private static IReadOnlyList<string> BuildFeatureValidationMatrixRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview)
    {
        return
        [
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "Targeted tests: Review - no command resolved."
                : $"Targeted tests: Good - {context.TestTarget.Command}.",
            testPreview.Ready
                ? $"Behavior test preview: Good - {testPreview.TargetFile} ({testPreview.FrameworkName})."
                : $"Behavior test preview: Review - {testPreview.Status}",
            synthesis.PreviewReady
                ? $"Code patch preview: Good - {synthesis.PreviewEdits.Count} edit(s) ready."
                : $"Code patch preview: Review - {synthesis.Status}",
            $"Risk-aware depth: {ClassifyRiskAwareTestDepth(context.RelativeCandidateFiles)}",
            $"Build order: {FormatInlineList(context.TestTarget.BuildOrderProjects)}"
        ];
    }

    private static IReadOnlyList<string> BuildFeatureRollbackStopRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis)
    {
        var rows = new List<string>
        {
            "Rollback: discard pending preview if the visible diff does not match the request.",
            "Rollback: use review current changes before commit; revert only owner-approved files.",
            synthesis.PreviewReady ? "Stop gate: preview-ready code exists; apply only after owner reviews the bundle." : "Stop gate: no code preview yet; keep work in planning.",
            context.RankedTargets.Count == 0 || context.RankedTargets.First().Confidence.Equals("Low", StringComparison.OrdinalIgnoreCase)
                ? "Stop gate: target confidence is not strong enough for autonomous editing."
                : "Stop gate: target confidence is acceptable for preview-only drafting.",
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "Stop gate: validation target unresolved."
                : "Stop gate: validation target resolved; run only through confirmation."
        };
        rows.AddRange(context.RiskLabels
            .Where(label => label.StartsWith("Protected", StringComparison.OrdinalIgnoreCase)
                || label.StartsWith("High", StringComparison.OrdinalIgnoreCase))
            .Take(3)
            .Select(label => "Stop gate: " + label));
        return rows;
    }

    private static string BuildGuidedFeatureImplementationNextCommand(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview)
    {
        if (context.RankedTargets.Count == 0)
        {
            return "feature work context " + context.Goal;
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "resolve test target " + context.Goal;
        }

        if (testPreview.Ready && synthesis.PreviewReady)
        {
            return "preview guided feature bundle " + context.Goal;
        }

        if (testPreview.Ready)
        {
            return testPreview.Command;
        }

        return synthesis.PreviewReady ? "preview synthesized feature patch " + context.Goal : "concrete patch authoring " + context.Goal;
    }

    private async Task<BehaviorTestPatchReadiness> BuildBehaviorTestPatchReadinessAsync(
        FeatureWorkContext context,
        CancellationToken cancellationToken)
    {
        var edit = await BuildBehaviorTestPatchPreviewEditAsync(context, cancellationToken).ConfigureAwait(false);
        return new BehaviorTestPatchReadiness(
            edit.Ready,
            edit.Ready ? "Ready - behavior test preview can be drafted." : "Review - " + edit.Status,
            edit.RelativePath,
            edit.FrameworkName,
            edit.Command ?? "behavior test plan " + context.Goal);
    }

    private string ClassifyGuidedFeatureWorkflowStage(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (_lastPatchPreviewRequest is not null)
        {
            return "Awaiting owner preview decision";
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "Repair failed validation";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded != true)
        {
            return "Validate applied change";
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "Review and commit" : "Completion receipt";
        }

        if (context.RankedTargets.Count == 0)
        {
            return "Resolve feature target";
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "Resolve validation route";
        }

        if (testPreview.Ready && synthesis.PreviewReady)
        {
            return "Preview paired bundle";
        }

        if (testPreview.Ready)
        {
            return "Preview behavior test";
        }

        return synthesis.PreviewReady ? "Preview code patch" : "Draft exact patch";
    }

    private int BuildGuidedFeatureWorkflowScore(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        var score = 0;
        score += context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase) ? 5 : 10;
        score += context.RankedTargets.Count > 0 ? 15 : 0;
        score += string.IsNullOrWhiteSpace(context.TestTarget.Command) ? 0 : 15;
        score += testPreview.Ready ? 15 : 5;
        score += synthesis.PreviewReady ? 20 : synthesis.Candidates.Count > 0 ? 10 : 0;
        score += _lastPatchPreviewRequest is not null ? 5 : 0;
        score += latestEdit is not null || context.ChangedFiles.Count > 0 ? 5 : 0;
        score += latestValidation?.Succeeded == true ? 10 : latestValidation?.Succeeded == false ? -10 : 0;
        score += gitStatus.Available ? 5 : 0;
        score += gitStatus.Clean && latestValidation?.Succeeded == true ? 5 : 0;
        return Math.Clamp(score, 0, 100);
    }

    private static string BuildGuidedCodePreviewLine(FeaturePatchSynthesis synthesis) =>
        synthesis.PreviewReady
            ? $"Code preview: Ready - {synthesis.PreviewEdits.Count} exact edit(s) can be previewed."
            : synthesis.Candidates.Count > 0
                ? "Code preview: Drafting - candidate anchor exists but exact preview is not ready."
                : "Code preview: Waiting - no deterministic patch candidate yet.";

    private static string BuildGuidedTestPreviewLine(BehaviorTestPatchReadiness testPreview)
    {
        var target = string.IsNullOrWhiteSpace(testPreview.TargetFile) ? string.Empty : $" Target: {testPreview.TargetFile}.";
        var framework = string.IsNullOrWhiteSpace(testPreview.FrameworkName) ? string.Empty : $" Framework: {testPreview.FrameworkName}.";
        return $"Test preview: {testPreview.Status}{target}{framework}";
    }

    private static string BuildGuidedPatchTestPairingLine(
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview)
    {
        if (synthesis.PreviewReady && testPreview.Ready)
        {
            return "Patch/test pairing: Ready - behavior test preview and code preview can be reviewed as a pair.";
        }

        if (testPreview.Ready)
        {
            return "Patch/test pairing: Test-first - behavior preview can lock the expected result before code.";
        }

        if (synthesis.PreviewReady)
        {
            return "Patch/test pairing: Code-only - code preview is ready, test preview needs owner review.";
        }

        return "Patch/test pairing: Drafting - resolve targets before pairing patch and test.";
    }

    private IReadOnlyList<string> BuildGuidedFeatureWorkflowPathRows(
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        return
        [
            context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase)
                ? "Intake: Review - owner request is still generic."
                : $"Intake: Good - {context.Goal}.",
            context.RankedTargets.Count == 0
                ? "Target: Review - no ranked file target yet."
                : $"Target: Good - {context.RankedTargets.First().RelativePath} ({context.RankedTargets.First().Confidence}).",
            string.IsNullOrWhiteSpace(context.TestTarget.Command)
                ? "Validation: Review - targeted command is unresolved."
                : $"Validation: Good - {context.TestTarget.Command}.",
            testPreview.Ready
                ? $"Behavior test: Ready - {testPreview.Command}."
                : $"Behavior test: Review - {testPreview.Status}",
            synthesis.PreviewReady
                ? $"Code patch: Ready - preview synthesized feature patch {context.Goal}."
                : "Code patch: Draft - exact patch synthesis still needs a safe before/after block.",
            testPreview.Ready && synthesis.PreviewReady
                ? $"Paired preview: Ready - preview guided feature bundle {context.Goal}."
                : "Paired preview: Waiting - needs both a behavior test edit and code edit.",
            _lastPatchPreviewRequest is null
                ? "Pending preview: none."
                : $"Pending preview: {_lastPatchPreviewRequest.Action} needs owner decision.",
            latestEdit is null && context.ChangedFiles.Count == 0
                ? "Apply state: Waiting - no applied edit evidence."
                : "Apply state: Review - changed files exist and need validation/closeout.",
            latestValidation?.Succeeded == true
                ? "Release state: Good - latest validation passed."
                : latestValidation?.Succeeded == false
                    ? "Release state: Repair - latest validation failed."
                    : "Release state: Waiting - no validation receipt yet.",
            gitStatus.HasUncommittedChanges ? "Git state: Review - uncommitted changes present." : $"Git state: {gitStatus.Summary}."
        ];
    }

    private IReadOnlyList<string> BuildGuidedFeatureWorkflowAskRows(
        FeatureWorkContext context,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        GitWorkingTreeStatus gitStatus)
    {
        var rows = new List<string>();
        if (context.Goal.Equals("current feature", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Ask owner for the feature in plain English before drafting code.");
        }

        if (context.RankedTargets.Count == 0 || context.RankedTargets.First().Confidence.Equals("Low", StringComparison.OrdinalIgnoreCase))
        {
            rows.Add("Ask or inspect more when target confidence is Low.");
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            rows.Add("Ask or resolve validation before applying behavior-changing code.");
        }

        if (!testPreview.Ready)
        {
            rows.Add("Ask owner before inventing a new test file; only existing test files are previewed automatically.");
        }

        if (context.RiskLabels.Any(label => label.StartsWith("Protected", StringComparison.OrdinalIgnoreCase)
            || label.StartsWith("High", StringComparison.OrdinalIgnoreCase)))
        {
            rows.Add("Stop for explicit owner review when protected or high-risk files appear.");
        }

        if (_lastPatchPreviewRequest is not null)
        {
            rows.Add("Stop while a patch preview is pending; owner must apply or discard it.");
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            rows.Add("Stop and repair failed validation before drafting another patch.");
        }

        if (!gitStatus.Available)
        {
            rows.Add("Ask owner to verify Git state because Git status is unavailable.");
        }

        return rows.Count == 0 ? ["No extra ask required - continue with the next command."] : rows;
    }

    private string BuildGuidedFeatureWorkflowNextCommand(
        string goal,
        FeatureWorkContext context,
        FeaturePatchSynthesis synthesis,
        BehaviorTestPatchReadiness testPreview,
        CodingReceipt? latestValidation,
        CodingReceipt? latestEdit,
        GitWorkingTreeStatus gitStatus)
    {
        if (_lastPatchPreviewRequest is not null)
        {
            return "confirm apply last patch preview";
        }

        if (_lastDotNetResult is { Succeeded: false } || latestValidation is { Succeeded: false })
        {
            return "validation repair runner " + goal;
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded != true)
        {
            return "post patch validation " + goal;
        }

        if ((latestEdit is not null || context.ChangedFiles.Count > 0) && latestValidation?.Succeeded == true)
        {
            return gitStatus.HasUncommittedChanges ? "can i safely commit" : "feature completion receipt";
        }

        if (testPreview.Ready && synthesis.PreviewReady)
        {
            return "preview guided feature bundle " + goal;
        }

        if (synthesis.PreviewReady)
        {
            return "preview synthesized feature patch " + goal;
        }

        if (context.RankedTargets.Count == 0)
        {
            return "feature work context " + goal;
        }

        if (string.IsNullOrWhiteSpace(context.TestTarget.Command))
        {
            return "resolve test target " + goal;
        }

        if (testPreview.Ready)
        {
            return testPreview.Command;
        }

        return "concrete patch authoring " + goal;
    }

    private static IReadOnlyList<string> BuildPatchSliceRows(FeatureWorkContext context)
    {
        if (context.RankedTargets.Count == 0)
        {
            return
            [
                "Discovery slice - inspect likely files first; reason no ranked target is available; risk review; validation resolve test target before preview."
            ];
        }

        var validation = context.ValidationRows.FirstOrDefault(row => row.Contains("Targeted test", StringComparison.OrdinalIgnoreCase))
            ?? context.ValidationRows.FirstOrDefault()
            ?? "resolve a validation command first";
        return context.RankedTargets
            .Take(3)
            .Select((target, index) =>
                $"Patch slice {index + 1} - {target.RelativePath}: {string.Join("; ", target.Reasons.Take(2))}; risk {target.Risk}; expected behavior supports {context.Goal}; validation {validation}")
            .ToList();
    }

    private static IReadOnlyList<string> BuildTestStubRows(FeatureWorkContext context)
    {
        var firstTarget = context.RankedTargets.FirstOrDefault();
        var targetName = firstTarget is null
            ? "CurrentFeature"
            : Path.GetFileNameWithoutExtension(firstTarget.RelativePath).Replace(".", string.Empty, StringComparison.OrdinalIgnoreCase);
        return
        [
            $"Parser route test: {targetName}_routes_owner_phrase_to_expected_action.",
            $"Service output test: {targetName}_returns_heading_status_and_no_file_change_boundary.",
            $"Behavior regression test: {targetName}_preserves_expected_result_for_{NormalizeTestNameToken(context.Goal)}.",
            "Dashboard binding test: build feature button points at the expected ICommand.",
            "Assertion draft: output contains the contract heading, target file row, validation row, and no hidden apply step."
        ];
    }

    private async Task<BehaviorTestPatchPreviewEdit> BuildBehaviorTestPatchPreviewEditAsync(
        FeatureWorkContext context,
        CancellationToken cancellationToken)
    {
        var targetFile = ResolveBehaviorTestPatchTarget(context);
        if (string.IsNullOrWhiteSpace(targetFile))
        {
            return new BehaviorTestPatchPreviewEdit(
                false,
                "no existing C# test file target was resolved.",
                null,
                null,
                null,
                null,
                null,
                null,
                null);
        }

        var content = await File.ReadAllTextAsync(targetFile, cancellationToken).ConfigureAwait(false);
        var framework = ResolveBehaviorTestFramework(targetFile, content);
        if (framework is null)
        {
            return new BehaviorTestPatchPreviewEdit(
                false,
                "test framework could not be detected as xUnit, NUnit, or MSTest.",
                targetFile,
                RelativeToWorkspace(targetFile),
                null,
                null,
                null,
                null,
                null);
        }

        var methodName = BuildBehaviorTestMethodName(context.Goal, content);
        var newline = content.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
        var testMethod = BuildBehaviorTestMethod(context.Goal, methodName, framework, newline);
        if (!TryBuildBehaviorTestInsertionBlock(content, testMethod, out var oldText, out var newText, out var blockReason))
        {
            return new BehaviorTestPatchPreviewEdit(
                false,
                blockReason,
                targetFile,
                RelativeToWorkspace(targetFile),
                framework.Name,
                methodName,
                blockReason,
                null,
                null);
        }

        return new BehaviorTestPatchPreviewEdit(
            true,
            "Ready - behavior test preview can be drafted.",
            targetFile,
            RelativeToWorkspace(targetFile),
            framework.Name,
            methodName,
            blockReason,
            new CodingPatchEdit(targetFile, oldText, newText),
            "preview behavior test patch " + context.Goal);
    }

    private string? ResolveBehaviorTestPatchTarget(FeatureWorkContext context)
    {
        return context.TestTarget.TestFiles
            .Select(path => ToAbsoluteWorkspacePath(path))
            .Concat(context.RelativeCandidateFiles.Where(IsTestFile).Select(path => ToAbsoluteWorkspacePath(path)))
            .Concat(GetCSharpFiles().Where(IsTestFile).Select(path => ToAbsoluteWorkspacePath(path) ?? path))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Where(path => File.Exists(path)
                && path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase)
                && Policy.IsInsideWorkspace(path)
                && LooksTextReadable(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(path => path.Contains($"{Path.DirectorySeparatorChar}test", StringComparison.OrdinalIgnoreCase) ? 0 : 1)
            .ThenBy(path => path, StringComparer.OrdinalIgnoreCase)
            .FirstOrDefault();
    }

    private BehaviorTestFramework? ResolveBehaviorTestFramework(string testFile, string content)
    {
        var summaries = GetWorkspaceProjectSummaries();
        var project = FindProjectForWorkspaceFile(testFile, summaries);
        var packageText = string.Empty;
        if (!string.IsNullOrWhiteSpace(project))
        {
            packageText = string.Join(Environment.NewLine, summaries
                .Where(summary => summary.RelativePath.Equals(project, StringComparison.OrdinalIgnoreCase))
                .SelectMany(summary => summary.PackageReferences));
        }

        if (MentionsAny(content, "using Xunit", "[Fact", "[Theory")
            || MentionsAny(packageText, "xunit"))
        {
            return new BehaviorTestFramework("xUnit", "[global::Xunit.Fact]");
        }

        if (MentionsAny(content, "using NUnit.Framework", "[Test]")
            || MentionsAny(packageText, "NUnit"))
        {
            return new BehaviorTestFramework("NUnit", "[global::NUnit.Framework.Test]");
        }

        if (MentionsAny(content, "using Microsoft.VisualStudio.TestTools.UnitTesting", "[TestMethod]")
            || MentionsAny(packageText, "MSTest"))
        {
            return new BehaviorTestFramework("MSTest", "[global::Microsoft.VisualStudio.TestTools.UnitTesting.TestMethod]");
        }

        return null;
    }

    private static string BuildBehaviorTestMethod(string goal, string methodName, BehaviorTestFramework framework, string newline)
    {
        var escapedGoal = EscapeCSharpStringLiteral(TrimForChat(goal, 160));
        var failureStatement = framework.Name switch
        {
            "NUnit" => $"global::NUnit.Framework.Assert.Fail(\"Capture expected behavior for: {escapedGoal}\");",
            "MSTest" => $"global::Microsoft.VisualStudio.TestTools.UnitTesting.Assert.Fail(\"Capture expected behavior for: {escapedGoal}\");",
            _ => $"throw new global::System.NotImplementedException(\"Capture expected behavior for: {escapedGoal}\");"
        };
        return string.Join(newline, new[]
        {
            string.Empty,
            "    " + framework.Attribute,
            $"    public void {methodName}()",
            "    {",
            "        " + failureStatement,
            "    }",
            string.Empty
        });
    }

    private static string BuildBehaviorTestMethodName(string goal, string content)
    {
        var tokens = Regex.Matches(goal, "[A-Za-z0-9]+")
            .Select(match => match.Value)
            .Where(token => token.Length > 0)
            .Take(6)
            .Select(token => char.ToUpperInvariant(token[0]) + (token.Length == 1 ? string.Empty : token[1..]))
            .ToList();
        var stem = tokens.Count == 0 ? "GeneratedBehavior" : string.Concat(tokens);
        if (char.IsDigit(stem[0]))
        {
            stem = "Generated" + stem;
        }

        if (stem.Length > 56)
        {
            stem = stem[..56];
        }

        var baseName = stem.EndsWith("Behavior", StringComparison.OrdinalIgnoreCase)
            ? stem + "Contract"
            : stem + "BehaviorContract";
        var candidate = baseName;
        for (var suffix = 2; Regex.IsMatch(content, $@"\b{Regex.Escape(candidate)}\b", RegexOptions.None, TimeSpan.FromMilliseconds(100)); suffix++)
        {
            candidate = baseName + suffix.ToString(CultureInfo.InvariantCulture);
        }

        return candidate;
    }

    private static bool TryBuildBehaviorTestInsertionBlock(
        string content,
        string insertion,
        out string oldText,
        out string newText,
        out string reason)
    {
        oldText = string.Empty;
        newText = string.Empty;
        reason = string.Empty;
        if (!content.Contains("class ", StringComparison.Ordinal))
        {
            reason = "target test file does not contain a class declaration anchor.";
            return false;
        }

        var lastBrace = content.LastIndexOf('}');
        if (lastBrace < 0)
        {
            reason = "target test file does not have a class closing brace.";
            return false;
        }

        var lineStart = content.LastIndexOf('\n', Math.Max(0, lastBrace - 1));
        var start = lineStart < 0 ? 0 : lineStart + 1;
        var candidate = content[start..];
        if (!string.IsNullOrWhiteSpace(candidate) && CountOrdinalOccurrences(content, candidate) == 1)
        {
            oldText = candidate;
            newText = candidate.Insert(lastBrace - start, insertion);
            reason = "Inserted before the final class closing brace.";
            return true;
        }

        if (TryBuildUniqueContextBlock(content, lastBrace, 1, out var block))
        {
            var offset = block.LastIndexOf('}');
            if (offset >= 0)
            {
                oldText = block;
                newText = block.Insert(offset, insertion);
                reason = "Inserted through a unique surrounding class-end block.";
                return true;
            }
        }

        reason = "target class closing brace was not unique enough for a safe literal patch.";
        return false;
    }

    private static string EscapeCSharpStringLiteral(string value) =>
        value.Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", " ", StringComparison.Ordinal)
            .Replace("\n", " ", StringComparison.Ordinal);

    private static IReadOnlyList<string> BuildApplyGateRows(FeatureWorkContext context)
    {
        var topTarget = context.RankedTargets.FirstOrDefault();
        var protectedFiles = context.RelativeCandidateFiles
            .Where(file => ClassifyFileRisk(file).StartsWith("Protected", StringComparison.OrdinalIgnoreCase))
            .Take(5)
            .ToList();
        var targetReady = topTarget is not null && !topTarget.Confidence.Equals("Low", StringComparison.OrdinalIgnoreCase);
        var testReady = !string.IsNullOrWhiteSpace(context.TestTarget.Command);
        var protectedReady = protectedFiles.Count == 0;
        var ready = targetReady && testReady && protectedReady;
        return
        [
            targetReady ? $"Target confidence: Good - {topTarget!.RelativePath} ({topTarget.Confidence})." : "Target confidence: Review - no medium/high target yet.",
            "Behavior contract: Good - input, action, result, failure behavior, and permission boundary are defined.",
            testReady ? $"Test target: Good - {context.TestTarget.Command}." : "Test target: Review - resolve a targeted test before behavior-changing apply.",
            protectedReady ? "Protected files: Good - no generated/designer candidates." : $"Protected files: Review - {FormatInlineList(protectedFiles)}.",
            ready ? "Gate result: Ready for patch preview only." : "Gate result: Hold before patch preview/apply.",
            "Apply boundary: preview the patch bundle first; apply only after the visible diff matches the contract."
        ];
    }

    private static IReadOnlyList<string> BuildPatchSliceApprovalRows(FeatureWorkContext context)
    {
        var rows = new List<string>();
        rows.AddRange(BuildPatchSliceRows(context).Take(3));
        rows.AddRange(BuildApplyGateRows(context)
            .Where(row => row.StartsWith("Target confidence:", StringComparison.OrdinalIgnoreCase)
                || row.StartsWith("Test target:", StringComparison.OrdinalIgnoreCase)
                || row.StartsWith("Gate result:", StringComparison.OrdinalIgnoreCase))
            .Take(3));
        rows.Add("Approval boundary: owner reviews the visible patch preview before any apply step.");
        return rows;
    }

    private static IReadOnlyList<string> BuildDeterministicPatchDraftRows(FeatureWorkContext context)
    {
        var rows = new List<string>();
        var targets = context.RankedTargets.Count > 0
            ? context.RankedTargets.Select(target => target.RelativePath).ToList()
            : context.RelativeCandidateFiles.ToList();
        foreach (var path in targets.Take(6))
        {
            rows.Add($"{path}: {ClassifyPatchDraftTemplate(path)}");
        }

        if (rows.Count == 0)
        {
            rows.Add("Hold - no file target is resolved yet; inspect workspace or project index first.");
        }

        rows.Add("Draft rule: produce exact before/after text only after target confidence and validation rows are present.");
        return rows;
    }

    private static string ClassifyPatchDraftTemplate(string path)
    {
        if (path.Contains("CodingToolContracts", StringComparison.OrdinalIgnoreCase))
        {
            return "action enum draft";
        }

        if (path.Contains("CodingToolRequestParser", StringComparison.OrdinalIgnoreCase))
        {
            return "parser phrase draft";
        }

        if (path.Contains("CodingWorkspacePolicy", StringComparison.OrdinalIgnoreCase))
        {
            return "read-only/write policy draft";
        }

        if (path.Contains("LocalCodingToolService", StringComparison.OrdinalIgnoreCase))
        {
            return "service handler and output draft";
        }

        if (path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase))
        {
            return "dashboard binding draft";
        }

        if (path.Contains("MainWindowViewModel", StringComparison.OrdinalIgnoreCase))
        {
            return "ICommand and compact summary draft";
        }

        if (path.Contains("Tests", StringComparison.OrdinalIgnoreCase) || path.Contains("Program.cs", StringComparison.OrdinalIgnoreCase))
        {
            return "parser, service, and dashboard regression assertion draft";
        }

        return "source edit draft";
    }

    private static IReadOnlyList<string> BuildRouteAwarePatchTemplateRows(FeatureWorkContext context)
    {
        var paths = context.RelativeCandidateFiles;
        var commandSurfaceLikely = paths.Any(path => path.Contains("CodingTool", StringComparison.OrdinalIgnoreCase)
            || path.Contains("LocalCodingToolService", StringComparison.OrdinalIgnoreCase)
            || path.Contains("ProgrammingDashboardWindow", StringComparison.OrdinalIgnoreCase)
            || path.Contains("MainWindowViewModel", StringComparison.OrdinalIgnoreCase));
        if (!commandSurfaceLikely)
        {
            return
            [
                "1. Behavior: state the owner-facing result in one sentence.",
                "2. Source: patch the smallest owning file first.",
                "3. Tests: add or update the nearest behavior check.",
                "4. Validation: run targeted test, build, then review changes.",
                "5. Receipt: capture latest validation and commit readiness."
            ];
        }

        return
        [
            "1. Contract: add or reuse CodingToolAction for the owner phrase.",
            "2. Parser: route exact and prefixed phrases to that action.",
            "3. Policy: mark planning/inspection as read-only or edits as confirmation-gated.",
            "4. Service: add switch handler plus compact, plain-language rows.",
            "5. Dashboard: add one button only when it reduces user friction.",
            "6. Tests: parser action, service heading, dashboard command binding."
        ];
    }

    private IReadOnlyList<string> BuildPatchPreviewGateRows(FeatureWorkContext context)
    {
        var rows = BuildApplyGateRows(context)
            .Where(row => row.StartsWith("Target confidence:", StringComparison.OrdinalIgnoreCase)
                || row.StartsWith("Test target:", StringComparison.OrdinalIgnoreCase)
                || row.StartsWith("Protected files:", StringComparison.OrdinalIgnoreCase)
                || row.StartsWith("Gate result:", StringComparison.OrdinalIgnoreCase))
            .ToList();
        rows.Add(_lastPatchPreviewRequest is null
            ? "Pending preview: none - preview the exact patch bundle before apply."
            : $"Pending preview: loaded - {_lastPatchPreviewRequest.Action} is waiting for review.");
        rows.Add("Cycle guard: never apply a stale preview after new file changes or failed validation.");
        return rows;
    }

    private IReadOnlyList<string> BuildFailureRepairLinkRows()
    {
        if (_lastDotNetRequest is null || _lastDotNetResult is null)
        {
            return
            [
                "Last validation: Waiting - no build/test result is loaded.",
                "Repair route: run targeted validation after preview, then link failures back to the smallest patch slice."
            ];
        }

        if (_lastDotNetResult.Succeeded)
        {
            return
            [
                $"Last validation: Good - {_lastDotNetRequest.Action} passed.",
                "Repair route: no active validation failure."
            ];
        }

        var diagnostic = _lastDotNetResult.Message
            .Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .FirstOrDefault(line => line.Contains("error", StringComparison.OrdinalIgnoreCase)
                || line.Contains("failed", StringComparison.OrdinalIgnoreCase))
            ?? "failure details need inspection";
        return
        [
            $"Last validation: Bad - {_lastDotNetRequest.Action} failed.",
            $"First diagnostic: {TrimForChat(diagnostic, 180)}",
            "Repair route: map the diagnostic to file, symbol, route, or dashboard binding before drafting another patch."
        ];
    }

    private static IReadOnlyList<string> BuildCompletionReceiptV3Rows(FeatureWorkContext context, CodingReceipt? latestValidation)
    {
        var topTarget = context.RankedTargets.FirstOrDefault()?.RelativePath ?? "none resolved yet";
        return
        [
            $"Goal: {context.Goal}",
            $"Top target: {topTarget}",
            $"Test command: {(string.IsNullOrWhiteSpace(context.TestTarget.Command) ? "none resolved yet" : context.TestTarget.Command)}",
            latestValidation is null ? "Latest validation: none" : FormatReceiptSummary("Latest validation", latestValidation),
            $"Risk labels: {FormatInlineList(context.RiskLabels)}"
        ];
    }

    private static IReadOnlyList<string> BuildMiniCodexScoreAuditRows(
        FeatureWorkContext context,
        CodingReceipt? latestValidation,
        bool hasPendingPreview)
    {
        var target = context.RankedTargets.FirstOrDefault();
        var targetGood = target is not null && !target.Confidence.Equals("Low", StringComparison.OrdinalIgnoreCase);
        var testGood = !string.IsNullOrWhiteSpace(context.TestTarget.Command);
        var validationGood = latestValidation?.Succeeded == true;
        var routeGood = context.RelativeCandidateFiles.Any(path => path.Contains("Coding", StringComparison.OrdinalIgnoreCase)
            || path.Contains("Wpf", StringComparison.OrdinalIgnoreCase)
            || path.EndsWith(".xaml", StringComparison.OrdinalIgnoreCase));
        var estimate = 90
            + (targetGood ? 2 : 0)
            + (testGood ? 2 : 0)
            + (validationGood ? 2 : 0)
            + (routeGood ? 1 : 0)
            - (hasPendingPreview ? 1 : 0);
        estimate = Math.Clamp(estimate, 88, 97);
        return
        [
            targetGood ? $"Target confidence: Good - {target!.RelativePath} ({target.Confidence})." : "Target confidence: Review - resolve a medium/high target.",
            testGood ? $"Test readiness: Good - {context.TestTarget.Command}." : "Test readiness: Review - targeted test command missing.",
            validationGood ? "Validation receipt: Good - latest build/test passed." : "Validation receipt: Review - no passing build/test receipt in memory.",
            routeGood ? "Route template: Good - command/dashboard pattern detected." : "Route template: Review - use generic source/test/receipt path.",
            $"Score estimate: {estimate}% local mini-Codex readiness for this slice."
        ];
    }

    private static IReadOnlyList<string> BuildPostPatchValidationRows(FeatureWorkContext context)
    {
        var rows = new List<string>();
        rows.Add(string.IsNullOrWhiteSpace(context.TestTarget.Command)
            ? "1. Targeted test: resolve test target before running validation."
            : $"1. Targeted test: {context.TestTarget.Command}");
        rows.AddRange(context.ValidationRows
            .Where(row => !row.Contains("Targeted test", StringComparison.OrdinalIgnoreCase))
            .Take(4)
            .Select((row, index) => $"{index + 2}. {row}"));
        rows.Add("Final: review current changes, then can i safely commit.");
        return rows;
    }

    private static string NormalizeTestNameToken(string value)
    {
        var token = Regex.Replace(value, "[^A-Za-z0-9]+", "_").Trim('_');
        if (string.IsNullOrWhiteSpace(token))
        {
            return "current_feature";
        }

        return token.Length <= 48 ? token : token[..48];
    }

    private CodingToolResult ShowFailureLoopState()
    {
        var hasDotNetResult = _lastDotNetRequest is not null && _lastDotNetResult is not null;
        var failed = hasDotNetResult && _lastDotNetResult is { Succeeded: false };
        var lines = new List<string>
        {
            "Failure loop state machine:",
            "No files were changed.",
            failed ? "State: Failed - inspect diagnostics before patching." : hasDotNetResult ? "State: Validated - last build/test passed." : "State: Waiting - no build/test result is loaded.",
            hasDotNetResult ? $"Last command: {_lastDotNetRequest!.Action}" : "Last command: none",
            "Loop rows:",
            "- 1. Capture the first useful diagnostic.",
            "- 2. Map it to a file, symbol, or dashboard binding.",
            "- 3. Preview the smallest patch bundle.",
            "- 4. Rerun targeted validation.",
            "- 5. Stop when validation passes or the cause is uncertain."
        };
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Failure loop state", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> ShowStopConditionDetectorAsync(
        CancellationToken cancellationToken,
        IReadOnlyList<string>? precomputedChangedFiles = null)
    {
        var changedFiles = precomputedChangedFiles
            ?? await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var receipts = ReadRecentReceipts(MaxReceiptEntries);
        var latestValidation = receipts.LastOrDefault(IsDotNetReceipt);
        var generated = changedFiles.Where(IsGeneratedOrDesignerFile).Take(5).ToList();
        var lines = new List<string>
        {
            "Stop condition detector:",
            "No files were changed.",
            changedFiles.Count == 0 ? "Changed files: none" : $"Changed files: {changedFiles.Count}",
            latestValidation is null ? "Latest validation: none" : FormatReceiptSummary("Latest validation", latestValidation),
            "Stop now if:",
            latestValidation?.Succeeded == false ? "- Validation failed and needs diagnosis." : "- Validation has not been run after a meaningful edit.",
            changedFiles.Count > MaxPatchBundleEdits ? $"- Too many files changed for one owner-safe slice: {changedFiles.Count}." : "- File count is inside the normal patch-bundle limit.",
            generated.Count > 0 ? $"- Generated/designer files changed: {FormatInlineList(generated)}." : "- No generated/designer changes detected.",
            "- The requirement is unclear, the expected behavior is not testable, or the next edit would be speculative."
        };
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Stop condition detector", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> ShowSliceRiskScoringAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var goal = CleanGoal(request.Query, "current feature");
        var changedFiles = await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var files = changedFiles.Count > 0 ? changedFiles.Take(10).ToList() : SuggestLikelyFilesForGoal(goal).Take(10).ToList();
        var lines = new List<string>
        {
            "Confidence/risk scoring per slice:",
            "No files were changed.",
            $"Goal: {goal}",
            "Scores:"
        };
        if (files.Count == 0)
        {
            lines.Add("- Waiting - no changed or likely files detected.");
        }
        else
        {
            foreach (var file in files)
            {
                var risk = ClassifyFileRisk(file);
                var confidence = risk.StartsWith("Protected", StringComparison.OrdinalIgnoreCase) || risk.StartsWith("High", StringComparison.OrdinalIgnoreCase) ? "medium" : "high";
                lines.Add($"- {file}: risk {risk}; confidence {confidence}; validation {ClassifyRiskAwareTestDepth([file])}.");
            }
        }

        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Slice risk scoring", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> ShowFeatureCompletionReceiptAsync(
        CancellationToken cancellationToken,
        FeatureWorkContext? context = null)
    {
        context ??= await BuildFeatureWorkContextAsync(new CodingToolRequest(CodingToolAction.ShowFeatureCompletionReceipt, null, Query: "current feature"), cancellationToken).ConfigureAwait(false);
        var changedFiles = context.ChangedFiles;
        var receipts = ReadRecentReceipts(MaxReceiptEntries);
        var latestValidation = receipts.LastOrDefault(IsDotNetReceipt);
        var latestGit = receipts.LastOrDefault(receipt => receipt.Action.StartsWith("Git", StringComparison.OrdinalIgnoreCase)
            || receipt.Action is nameof(CodingToolAction.GitStatus) or nameof(CodingToolAction.GitDiff) or nameof(CodingToolAction.ReviewCurrentChanges));
        var gitStatus = await InspectGitWorkingTreeAsync(cancellationToken).ConfigureAwait(false);
        var lines = new List<string>
        {
            "Feature completion receipt:",
            "No files were changed.",
            $"Goal: {context.Goal}",
            $"Changed files: {changedFiles.Count}",
            $"Plan confidence: {context.ImpactScore.Score}/100 ({context.ImpactScore.Confidence})",
            $"Top target: {(context.RankedTargets.FirstOrDefault()?.RelativePath ?? "none resolved yet")}",
            $"Test command: {(string.IsNullOrWhiteSpace(context.TestTarget.Command) ? "none resolved yet" : context.TestTarget.Command)}",
            $"Risk labels: {FormatInlineList(context.RiskLabels)}",
            latestValidation is null ? "Latest validation: none" : FormatReceiptSummary("Latest validation", latestValidation),
            latestGit is null ? "Latest git check: none" : FormatReceiptSummary("Latest git check", latestGit),
            $"Git: {gitStatus.Summary}",
            "Closeout checklist:",
            "- Intent packet exists or the goal is captured in the commit message.",
            "- Behavior contract and patch slices are reviewed.",
            "- Behavior tests or manual verification match the owner-facing workflow.",
            "- Diff review, build, tests, and safe commit check are complete.",
            latestValidation?.Succeeded == true ? "Status: Ready for review." : "Status: Needs validation before release."
        };
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Feature completion receipt", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> ShowFeatureExecutionPacketAsync(
        CodingToolRequest request,
        CancellationToken cancellationToken,
        FeatureWorkContext? context = null)
    {
        context ??= await BuildFeatureWorkContextAsync(request, cancellationToken).ConfigureAwait(false);
        var lines = new List<string>
        {
            "Feature execution packet v1:",
            "No files were changed.",
            $"Goal: {context.Goal}",
            $"Plan confidence: {context.ImpactScore.Score}/100 ({context.ImpactScore.Confidence})",
            $"Plan reasons: {FormatInlineList(context.ImpactScore.Reasons)}",
