    private async Task<CodingToolResult> ShowBuildFeatureLaneAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var context = await BuildFeatureWorkContextAsync(request, cancellationToken).ConfigureAwait(false);
        var goal = context.Goal;
        var intent = BuildFeatureIntentPacket(new CodingToolRequest(CodingToolAction.BuildFeatureIntentPacket, null, Query: goal), context);
        var tests = await PlanBehaviorTestsAsync(new CodingToolRequest(CodingToolAction.PlanBehaviorTests, null, Query: goal), cancellationToken, context).ConfigureAwait(false);
        var slices = await PlanImplementationSlicesAsync(new CodingToolRequest(CodingToolAction.PlanImplementationSlices, null, Query: goal), cancellationToken, context).ConfigureAwait(false);
        var execution = await ShowFeatureExecutionPacketAsync(new CodingToolRequest(CodingToolAction.ShowFeatureExecutionPacket, null, Query: goal), cancellationToken, context).ConfigureAwait(false);
        var stop = await ShowStopConditionDetectorAsync(cancellationToken, context.ChangedFiles).ConfigureAwait(false);
        var receipt = await ShowFeatureCompletionReceiptAsync(cancellationToken, context).ConfigureAwait(false);
        var lines = new List<string>
        {
            "Build Feature lane:",
            "No files were changed.",
            $"Goal: {goal}",
            "Lane rows:"
        };
        AddSelectedLines(lines, intent.Message, 4, "User-facing behavior:", "Affected area:", "Validation depth:");
        lines.Add("Behavior contract:");
        lines.AddRange(BuildBehaviorContractRows(context).Take(4).Select(row => $"- {row}"));
        AddSelectedLines(lines, tests.Message, 3, "- Owner phrase", "- Service result", "- Dashboard binding");
        AddSelectedLines(lines, slices.Message, 6, "- 1.", "- 2.", "- 3.", "- 4.", "- 5.", "Risk-aware test depth:");
        AddSelectedLines(lines, execution.Message, 6, "Plan confidence:", "Plan reasons:", "- High", "- Medium", "- Low", "- Test target:");
        lines.Add("Apply gate:");
        lines.AddRange(BuildApplyGateRows(context).Take(4).Select(row => $"- {row}"));
        lines.Add("Patch intelligence:");
        lines.AddRange(BuildPatchPreviewGateRows(context).Take(3).Select(row => $"- {row}"));
        lines.Add("Validation router:");
        lines.AddRange(BuildPostPatchValidationRows(context).Take(4).Select(row => $"- {row}"));
        AddSelectedLines(lines, stop.Message, 4, "Changed files:", "Latest validation:", "- Validation", "- File count", "- No generated");
        AddSelectedLines(lines, receipt.Message, 3, "Git:", "Status:");
        lines.Add("Next: work context, contract, patch slices, apply gate, then validation router before any patch preview.");
        lines.Add($"Next command: feature work context {goal}");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Build Feature lane", Policy.WorkspaceRoot);
    }

    private CodingToolResult ShowCSharpSymbolIndex()
    {
        var files = GetCSharpFiles();
        var symbols = BuildRoslynSymbolIndex(files, 160);
        var typeCount = symbols.Count(symbol => symbol.Kind is "class" or "record" or "interface" or "enum" or "struct");
        var methodCount = symbols.Count(symbol => symbol.Kind == "method");
        var propertyCount = symbols.Count(symbol => symbol.Kind == "property");
        var lines = new List<string>
        {
            "C# symbol index:",
            "No files were changed.",
            "Engine: Roslyn syntax tree + semantic model",
            $"C# files: {files.Count}",
            $"Types: {typeCount}",
            $"Methods: {methodCount}",
            $"Properties: {propertyCount}",
            $"Projects represented: {symbols.Select(symbol => symbol.ProjectPath).Where(path => !string.IsNullOrWhiteSpace(path)).Distinct(StringComparer.OrdinalIgnoreCase).Count()}",
            "Examples:"
        };
        lines.AddRange(symbols.Count == 0
            ? ["- none found"]
            : symbols.Take(20).Select(symbol =>
            {
                var projectText = string.IsNullOrWhiteSpace(symbol.ProjectPath) ? "no project" : RelativeToWorkspace(symbol.ProjectPath);
                return $"- {symbol.Kind} {symbol.Name}: {RelativeToWorkspace(symbol.Path)}:{symbol.LineNumber}-{symbol.EndLineNumber} ({symbol.DisplayName}; {projectText})";
            }));
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "C# symbol index", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> ShowOwnershipMapAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var query = CleanGoal(request.Query, string.Empty);
        var changedFiles = await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var terms = ExtractMeaningfulGoalTerms(query).Take(8).ToList();
        var directFile = ToAbsoluteWorkspacePath(query);
        var semanticHits = terms.Count == 0
            ? new List<SemanticSymbolHit>()
            : terms
                .SelectMany(term => FindSemanticSymbolHits(workspace, term, 12))
                .DistinctBy(hit => $"{hit.Display}|{hit.Path}|{hit.LineNumber}", StringComparer.Ordinal)
                .Take(24)
                .ToList();
        var candidateFiles = semanticHits
            .Select(hit => hit.Path)
            .Concat(directFile is not null && File.Exists(directFile) ? [directFile] : [])
            .Concat(changedFiles.Select(ToAbsoluteWorkspacePath).Where(path => !string.IsNullOrWhiteSpace(path)).Select(path => path!))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();
        if (candidateFiles.Count == 0 && !string.IsNullOrWhiteSpace(query))
        {
            candidateFiles = SuggestLikelyFilesForGoal(query)
                .Select(ToAbsoluteWorkspacePath)
                .Where(path => !string.IsNullOrWhiteSpace(path))
                .Select(path => path!)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList();
        }

        var summaries = GetWorkspaceProjectSummaries();
        var projectImpact = BuildProjectImpact(candidateFiles, summaries);
        var testTarget = await ResolveTestTargetRecommendationAsync(query, cancellationToken).ConfigureAwait(false);
        var relatedFiles = FindOwnershipRelatedFiles(terms, semanticHits, candidateFiles);
        var ownershipHints = BuildSymbolOwnershipHints(terms, semanticHits, candidateFiles, summaries);
        var lines = new List<string>
        {
            "Ownership map:",
            "No files were changed.",
            string.IsNullOrWhiteSpace(query) ? "Query: current changed files" : $"Query: {query}",
            $"Candidate files: {candidateFiles.Count}",
            $"Semantic hits: {semanticHits.Count}",
            "Owning projects:"
        };
        lines.AddRange(projectImpact.SourceProjects.Count == 0 ? ["- none resolved"] : projectImpact.SourceProjects.Select(project => $"- {project}"));
        lines.Add("Affected projects:");
        lines.AddRange(projectImpact.AffectedProjects.Count == 0 ? ["- none resolved"] : projectImpact.AffectedProjects.Select(project => $"- {project}"));
        lines.Add("Primary files:");
        lines.AddRange(candidateFiles.Count == 0 ? ["- none found"] : candidateFiles.Select(file => $"- {RelativeToWorkspace(file)}: {ClassifyFileRisk(RelativeToWorkspace(file))}"));
        lines.Add("Nearby symbols:");
        lines.AddRange(semanticHits.Count == 0 ? ["- none found"] : semanticHits.Take(10).Select(FormatSemanticHit));
        lines.Add("Ownership hints:");
        lines.AddRange(ownershipHints.Count == 0 ? ["- none resolved"] : ownershipHints);
        lines.Add("Related files:");
        lines.AddRange(relatedFiles.Count == 0 ? ["- none found"] : relatedFiles.Select(file => $"- {file}"));
        lines.Add("Likely tests:");
        lines.AddRange(testTarget.TestFiles.Count == 0 ? ["- none found"] : testTarget.TestFiles.Select(file => $"- {RelativeToWorkspace(file)}"));
        lines.Add("Prioritized test plan:");
        lines.AddRange(testTarget.PrioritizedTests.Count == 0 ? ["- none resolved"] : testTarget.PrioritizedTests.Select(test => $"- {test}"));
        lines.Add("Call-chain impact:");
        lines.AddRange(testTarget.CallChainImpact.Count == 0 ? ["- none resolved"] : testTarget.CallChainImpact.Select(item => $"- {item}"));
        lines.Add("Build order slice:");
        lines.AddRange(projectImpact.BuildOrderProjects.Count == 0 ? ["- none resolved"] : projectImpact.BuildOrderProjects.Select((project, index) => $"- {index + 1}. {project}"));
        lines.Add("Validation commands:");
        lines.Add(string.IsNullOrWhiteSpace(testTarget.Command) ? "- No targeted test command resolved." : $"- {testTarget.Command}");
        lines.Add("Next - inspect the primary files, then use safe edit workflow before changing anything.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Ownership map", Policy.WorkspaceRoot);
    }

    private IReadOnlyList<string> BuildSymbolOwnershipHints(
        IReadOnlyList<string> terms,
        IReadOnlyList<SemanticSymbolHit> semanticHits,
        IReadOnlyList<string> candidateFiles,
        IReadOnlyList<ProjectSummary> summaries)
    {
        var hints = new List<string>();
        var hitOwners = semanticHits
            .Where(hit => !string.IsNullOrWhiteSpace(hit.Container) || !string.IsNullOrWhiteSpace(hit.ProjectPath))
            .Select(hit =>
            {
                var project = string.IsNullOrWhiteSpace(hit.ProjectPath) ? "unknown project" : RelativeToWorkspace(hit.ProjectPath);
                var container = string.IsNullOrWhiteSpace(hit.Container) ? hit.Display : hit.Container;
                return $"{container} owns {hit.Name} in {project}";
            })
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToList();
        hints.AddRange(hitOwners.Select(hint => $"- {hint}"));

        foreach (var file in candidateFiles.Take(6))
        {
            var ownerProject = FindProjectForWorkspaceFile(file, summaries);
            var relativePath = RelativeToWorkspace(file);
            hints.Add(string.IsNullOrWhiteSpace(ownerProject)
                ? $"- {relativePath}: no owning project resolved; inspect folder boundaries."
                : $"- {relativePath}: owned by {ownerProject}; {ClassifyFileRisk(relativePath)}.");
        }

        if (terms.Count > 0 && semanticHits.Count == 0)
        {
            hints.Add($"- Terms {FormatInlineList(terms.Take(4))} did not resolve to symbols; start with file search before editing.");
        }

        return hints.Distinct(StringComparer.OrdinalIgnoreCase).Take(12).ToList();
    }

    private IReadOnlyList<string> FindOwnershipRelatedFiles(
        IReadOnlyList<string> terms,
        IReadOnlyList<SemanticSymbolHit> semanticHits,
        IReadOnlyList<string> candidateFiles)
    {
        var candidateSet = candidateFiles.ToHashSet(StringComparer.OrdinalIgnoreCase);
        var symbolTerms = semanticHits
            .Select(hit => hit.Name)
            .Concat(terms)
            .Where(term => !string.IsNullOrWhiteSpace(term) && term.Length > 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();
        if (symbolTerms.Count == 0)
        {
            return [];
        }

        return BuildRoslynCallGraph(GetCSharpFiles(), 500)
            .Where(edge => symbolTerms.Any(term => edge.Caller.Contains(term, StringComparison.OrdinalIgnoreCase)
                || edge.Callee.Contains(term, StringComparison.OrdinalIgnoreCase)))
            .Select(edge => edge.Path)
            .Where(path => File.Exists(path) && !candidateSet.Contains(path))
            .Select(RelativeToWorkspace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
    }

    private CodingToolResult ShowCallGraph(CodingToolRequest request)
    {
        var query = CleanGoal(request.Query, string.Empty);
        var edges = BuildRoslynCallGraph(GetCSharpFiles(), 240);
        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var graph = BuildSemanticReferenceGraph(query, workspace, 80);
        var filtered = string.IsNullOrWhiteSpace(query)
            ? edges.Take(30).ToList()
            : edges
                .Where(edge => edge.Caller.Contains(query, StringComparison.OrdinalIgnoreCase)
                    || edge.Callee.Contains(query, StringComparison.OrdinalIgnoreCase))
                .Take(30)
                .ToList();
        var lines = new List<string>
        {
            "Call graph:",
            "No files were changed.",
            "Engine: Roslyn semantic invocation graph",
            string.IsNullOrWhiteSpace(query) ? "Filter: none" : $"Filter: {query}",
            $"Edges found: {edges.Count}",
            $"Edges shown: {filtered.Count}"
        };
        lines.AddRange(filtered.Count == 0
            ? ["- none found"]
            : filtered.Select(edge => $"- {edge.Caller} -> {edge.Callee} ({RelativeToWorkspace(edge.Path)}:{edge.LineNumber})"));
        if (!string.IsNullOrWhiteSpace(query))
        {
            lines.Add("Inbound callers:");
            lines.AddRange(graph.InboundCalls.Count == 0 ? ["- none found"] : graph.InboundCalls.Take(8).Select(FormatCallEdge));
            lines.Add("Outbound callees:");
            lines.AddRange(graph.OutboundCalls.Count == 0 ? ["- none found"] : graph.OutboundCalls.Take(8).Select(FormatCallEdge));
        }
        lines.Add("Note - this resolves normal C# invocations; virtual dispatch, reflection, and generated code may still need manual review.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Call graph", Policy.WorkspaceRoot);
    }
    private CodingToolResult ResolveSemanticSymbol(CodingToolRequest request)
    {
        var query = CleanGoal(request.Query, string.Empty);
        if (string.IsNullOrWhiteSpace(query))
        {
            return new CodingToolResult(true, false, "Semantic symbol resolver needs a symbol name.", "Semantic symbol resolver", Policy.WorkspaceRoot);
        }

        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var graph = BuildSemanticReferenceGraph(query, workspace, 80);
        var declarations = graph.Declarations.Take(12).ToList();
        var references = graph.References.Take(12).ToList();
        var lines = new List<string>
        {
            "Semantic symbol resolver:",
            "No files were changed.",
            "Engine: Roslyn semantic model + reference graph",
            $"Query: {query}",
            $"C# files: {workspace.Trees.Count}",
            $"Declarations found: {declarations.Count}",
            $"References found: {references.Count}",
            "Declarations:"
        };
        lines.AddRange(declarations.Count == 0 ? ["- none found"] : declarations.Select(FormatSemanticHit));
        lines.Add("References:");
        lines.AddRange(references.Count == 0 ? ["- none found"] : references.Select(FormatSemanticHit));
        AddReferenceGraphLines(lines, graph, includeSymbols: false);
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Semantic symbol resolver", Policy.WorkspaceRoot);
    }

