    private async Task<TestTargetRecommendation> ResolveTestTargetRecommendationAsync(
        string query,
        CancellationToken cancellationToken,
        IReadOnlyList<string>? precomputedChangedFiles = null,
        SemanticReferenceGraph? precomputedGraph = null)
    {
        var changedFiles = precomputedChangedFiles
            ?? await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var graph = precomputedGraph
            ?? (string.IsNullOrWhiteSpace(query)
                ? new SemanticReferenceGraph(query, [], [], [], [], [], [])
                : BuildSemanticReferenceGraph(query, BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000), 100));
        var semanticHits = graph.Declarations.Concat(graph.References).ToList();
        var sourceFiles = semanticHits
            .Select(hit => hit.Path)
            .Concat(graph.ReferenceFiles.Select(ToAbsoluteWorkspacePath).Where(path => !string.IsNullOrWhiteSpace(path)).Select(path => path!))
            .Where(path => !IsTestFile(path))
            .Concat(changedFiles.Where(IsSourceFile).Where(file => !IsTestFile(file)).Select(ToAbsoluteWorkspacePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();
        var sourceTokens = sourceFiles
            .Select(Path.GetFileNameWithoutExtension)
            .OfType<string>()
            .Where(token => !string.IsNullOrWhiteSpace(token))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var testFiles = GetCSharpFiles()
            .Where(IsTestFile)
            .Where(file => sourceTokens.Count == 0 || sourceTokens.Any(token => file.Contains(token, StringComparison.OrdinalIgnoreCase)) || !string.IsNullOrWhiteSpace(query) && file.Contains(query, StringComparison.OrdinalIgnoreCase))
            .OrderBy(file => file, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();
        if (testFiles.Count == 0)
        {
            testFiles = GetCSharpFiles().Where(IsTestFile).OrderBy(file => file, StringComparer.OrdinalIgnoreCase).Take(12).ToList();
        }

        var testSymbols = graph.TestSymbols
            .Concat(FindLikelyTestSymbols(sourceTokens, testFiles.Select(RelativeToWorkspace).ToList(), 20))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();
        var summaries = GetWorkspaceProjectSummaries();
        var projectImpact = BuildProjectImpact(sourceFiles, summaries);
        var notes = new List<string>();
        string? target = null;
        var scope = "none";
        foreach (var testFile in testFiles)
        {
            if (TryFindNearestProjectForFile(testFile, out var project))
            {
                target = project;
                scope = "targeted test project";
                break;
            }
        }

        if (target is null)
        {
            var testProject = summaries.FirstOrDefault(summary => summary.ProjectRole.Contains("test", StringComparison.OrdinalIgnoreCase));
            if (testProject is not null)
            {
                target = Path.Combine(Policy.WorkspaceRoot, testProject.RelativePath);
                scope = "first test project";
                notes.Add("No nearest test project was found from files; using the first detected test project.");
            }
        }

        if (target is null)
        {
            target = GetPrimaryTarget();
            scope = target is null ? "none" : "primary workspace target";
            if (target is not null)
            {
                notes.Add("No dedicated test project was found; falling back to the primary target.");
            }
        }

        if (projectImpact.AffectedProjects.Count > 0)
        {
            notes.Add($"Project impact includes {projectImpact.AffectedProjects.Count} project(s); validate in dependency build order when build risk is high.");
        }
        if (graph.ReferenceFiles.Count > 0)
        {
            notes.Add($"Reference graph found {graph.ReferenceFiles.Count} related file(s); review those before broad edits.");
        }
        var command = string.IsNullOrWhiteSpace(target) ? string.Empty : $"confirm dotnet test \"{target}\"";
        if (testFiles.Count == 0)
        {
            notes.Add("No likely test files were detected; run project intelligence if this seems wrong.");
        }

        var prioritizedTests = BuildPrioritizedTestPlan(testFiles, testSymbols, sourceTokens, projectImpact, target, command);
        var callChainImpact = BuildCallChainImpactSummary(graph, sourceFiles);
        return new TestTargetRecommendation(
            query,
            sourceFiles,
            testFiles,
            testSymbols,
            graph.ReferenceFiles,
            projectImpact.SourceProjects,
            projectImpact.AffectedProjects,
            projectImpact.BuildOrderProjects,
            target,
            scope,
            command,
            notes,
            prioritizedTests,
            callChainImpact);
    }

    private IReadOnlyList<string> BuildPrioritizedTestPlan(
        IReadOnlyList<string> testFiles,
        IReadOnlyList<string> testSymbols,
        IReadOnlyList<string> sourceTokens,
        ProjectImpact projectImpact,
        string? target,
        string command)
    {
        var lines = new List<string>();
        foreach (var testFile in testFiles.Take(6))
        {
            var relative = RelativeToWorkspace(testFile);
            var score = 50;
            var reasons = new List<string>();
            var name = Path.GetFileNameWithoutExtension(testFile);
            var matchedTokens = sourceTokens
                .Where(token => name.Contains(token, StringComparison.OrdinalIgnoreCase) || SafeReadText(testFile).Contains(token, StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(3)
                .ToList();
            if (matchedTokens.Count > 0)
            {
                score += 25;
                reasons.Add("matches " + string.Join(", ", matchedTokens));
            }

            if (TryFindNearestProjectForFile(testFile, out var project)
                && projectImpact.AffectedProjects.Any(affected => Path.GetFullPath(Path.Combine(Policy.WorkspaceRoot, affected)).Equals(project, StringComparison.OrdinalIgnoreCase)))
            {
                score += 15;
                reasons.Add("inside affected project slice");
            }

            if (testSymbols.Any(symbol => symbol.Contains(name, StringComparison.OrdinalIgnoreCase)))
            {
                score += 10;
                reasons.Add("symbol-level match");
            }

            var confidence = score >= 85 ? "High" : score >= 65 ? "Medium" : "Low";
            lines.Add($"{confidence} {score} - {relative}: {(reasons.Count == 0 ? "nearest available test" : string.Join("; ", reasons))}");
        }

        if (!string.IsNullOrWhiteSpace(command))
        {
            lines.Add($"Command first: {command}");
        }
        else if (!string.IsNullOrWhiteSpace(target))
        {
            lines.Add($"Target first: {target}");
        }

        if (projectImpact.BuildOrderProjects.Count > 0)
        {
            lines.Add($"Then build affected slice: {FormatInlineList(projectImpact.BuildOrderProjects.Take(6))}");
        }

        return lines.Distinct(StringComparer.OrdinalIgnoreCase).Take(10).ToList();
    }

    private IReadOnlyList<string> BuildCallChainImpactSummary(SemanticReferenceGraph graph, IReadOnlyList<string> sourceFiles)
    {
        var inboundCallers = graph.InboundCalls
            .Select(edge => edge.Caller)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToList();
        var outboundCallees = graph.OutboundCalls
            .Select(edge => edge.Callee)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToList();
        var impactFiles = graph.InboundCalls
            .Concat(graph.OutboundCalls)
            .Select(edge => edge.Path)
            .Concat(sourceFiles)
            .Where(File.Exists)
            .Select(RelativeToWorkspace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        var lines = new List<string>
        {
            $"Inbound callers: {FormatInlineList(inboundCallers)}",
            $"Outbound callees: {FormatInlineList(outboundCallees)}",
            $"Impact files: {FormatInlineList(impactFiles)}"
        };
        if (graph.InboundCalls.Count == 0 && graph.OutboundCalls.Count == 0)
        {
            lines.Add("Call graph confidence: Low - no direct invocation edges resolved.");
        }
        else
        {
            lines.Add($"Call graph confidence: Medium - {graph.InboundCalls.Count} inbound and {graph.OutboundCalls.Count} outbound edge(s) resolved.");
        }

        return lines;
    }

    private bool TryFindNearestProjectForFile(string file, out string projectPath)
    {
        projectPath = string.Empty;
        var directory = Path.GetDirectoryName(file);
        while (!string.IsNullOrWhiteSpace(directory) && Policy.IsInsideWorkspace(directory))
        {
            var project = Directory.EnumerateFiles(directory, "*.csproj", SearchOption.TopDirectoryOnly)
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .FirstOrDefault();
            if (project is not null)
            {
                projectPath = project;
                return true;
            }

            var parent = Directory.GetParent(directory)?.FullName;
            if (string.IsNullOrWhiteSpace(parent) || parent.Equals(directory, StringComparison.OrdinalIgnoreCase))
            {
                break;
            }

            directory = parent;
        }

        return false;
    }
    private async Task<CodingToolResult> PlanSemanticEditAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var goal = CleanGoal(request.Query, "current change");
        var changedFiles = await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var goalTerms = ExtractMeaningfulGoalTerms(goal).Take(8).ToList();
        var graph = BuildSemanticReferenceGraph(goal, workspace, 100);
        var hits = graph.Declarations
            .Concat(graph.References)
            .DistinctBy(hit => $"{hit.Display}|{hit.Path}|{hit.LineNumber}", StringComparer.Ordinal)
            .Take(20)
            .ToList();
        var candidateFiles = hits.Select(hit => hit.Path)
            .Concat(graph.ReferenceFiles.Select(ToAbsoluteWorkspacePath).Where(path => !string.IsNullOrWhiteSpace(path)).Select(path => path!))
            .Concat(changedFiles.Select(ToAbsoluteWorkspacePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();
        if (candidateFiles.Count == 0)
        {
            candidateFiles = SuggestLikelyFilesForGoal(goal).Select(ToAbsoluteWorkspacePath).Where(path => !string.IsNullOrWhiteSpace(path)).Select(path => path!).Take(8).ToList();
        }

        var rankedTargets = RankEditTargetCandidates(goalTerms, hits, candidateFiles, changedFiles);
        var impactScore = BuildEditImpactScore(rankedTargets, hits, candidateFiles, null);
        var lines = new List<string>
        {
            "Semantic edit plan:",
            "No files were changed.",
            "Engine: Roslyn semantic model + ranked edit targets",
            $"Goal: {goal}",
            $"Candidate files: {candidateFiles.Count}",
            $"Candidate symbols: {hits.Count}",
            $"Edit impact score: {impactScore.Score}/100 ({impactScore.Confidence})",
            $"Edit impact reasons: {FormatInlineList(impactScore.Reasons)}",
            "Ranked edit targets:"
        };
        lines.AddRange(rankedTargets.Count == 0 ? ["- none found"] : rankedTargets.Take(8).Select(FormatEditTargetCandidate));
        AddReferenceGraphLines(lines, graph, includeSymbols: true);
        AddSafeRefactorDetectorLines(lines, goal, candidateFiles.Select(RelativeToWorkspace).ToList(), graph);
        AddAutonomousPreflightLines(lines, candidateFiles.Select(RelativeToWorkspace).ToList(), graph, null, hasPendingPreview: false);
        lines.Add("Symbols to inspect:");
        lines.AddRange(hits.Count == 0 ? ["- none found from goal terms"] : hits.Take(10).Select(FormatSemanticHit));
        lines.Add("Files to inspect first:");
        lines.AddRange(candidateFiles.Count == 0 ? ["- none found"] : candidateFiles.Select(file => $"- {RelativeToWorkspace(file)}: {ClassifyFileRisk(RelativeToWorkspace(file))}"));
        lines.Add("Edit target validation:");
        lines.Add(rankedTargets.Count == 0
            ? "- Needs review - no exact semantic edit target was resolved."
            : $"- Good - top target is {rankedTargets[0].RelativePath} with {rankedTargets[0].Confidence} confidence.");
        lines.Add("Edit guardrails:");
        lines.Add("- Prefer exact-symbol changes over broad text replacement.");
        lines.Add("- Update tests when source behavior, parser routing, permissions, or UI command bindings change.");
        lines.Add("- Run impacted tests, then build, then safe commit check.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Semantic edit plan", Policy.WorkspaceRoot);
    }

    private EditImpactSurface BuildEditImpactSurface(
        IReadOnlyList<string> goalTerms,
        IReadOnlyList<SemanticSymbolHit> hits,
        IReadOnlyList<string> candidateFiles,
        TestTargetRecommendation testTarget)
    {
        var directFiles = candidateFiles
            .Where(File.Exists)
            .Select(RelativeToWorkspace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        var candidateSet = candidateFiles
            .Where(File.Exists)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var symbolTerms = hits
            .Select(hit => hit.Name)
            .Concat(goalTerms)
            .Where(term => !string.IsNullOrWhiteSpace(term) && term.Length > 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();
        var relatedFiles = hits
            .Where(hit => !hit.Source.Equals("declaration", StringComparison.OrdinalIgnoreCase))
            .Select(hit => hit.Path)
            .Concat(BuildRoslynCallGraph(GetCSharpFiles(), 400)
                .Where(edge => symbolTerms.Any(term => edge.Caller.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || edge.Callee.Contains(term, StringComparison.OrdinalIgnoreCase)))
                .Select(edge => edge.Path))
            .Where(path => File.Exists(path) && !candidateSet.Contains(path) && !IsTestFile(path))
            .Select(RelativeToWorkspace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        if (relatedFiles.Count == 0 && symbolTerms.Count > 0)
        {
            relatedFiles = GetCSharpFiles()
                .Where(file => File.Exists(file) && !candidateSet.Contains(file) && !IsTestFile(file))
                .Where(file => symbolTerms.Any(term => SafeReadText(file).Contains(term, StringComparison.OrdinalIgnoreCase)))
                .Select(RelativeToWorkspace)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList();
        }

        var testFiles = testTarget.TestFiles
            .Where(File.Exists)
            .Select(RelativeToWorkspace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        var affectedProjects = testTarget.AffectedProjects.Take(8).ToList();
        var notes = new List<string>();
        if (directFiles.Count == 0)
        {
            notes.Add("No direct file was resolved yet; inspect semantic hits before editing.");
        }
        if (relatedFiles.Count > 0)
        {
            notes.Add("Related files may need review after the direct edit.");
        }
        if (testFiles.Count == 0)
        {
            notes.Add("No targeted test file was resolved; use build plus broader tests.");
        }

        return new EditImpactSurface(
            directFiles,
            relatedFiles,
            testFiles,
            affectedProjects,
            testTarget.Command,
            testTarget.PrioritizedTests,
            testTarget.CallChainImpact,
            notes);
    }

    private void AddEditImpactSurfaceLines(List<string> lines, EditImpactSurface surface)
    {
        lines.Add("Impact radius:");
        lines.Add($"- Direct files: {FormatInlineList(surface.DirectFiles)}");
        lines.Add($"- Related references/callers: {FormatInlineList(surface.RelatedFiles)}");
        lines.Add($"- Likely tests: {FormatInlineList(surface.TestFiles)}");
        lines.Add($"- Affected projects: {FormatInlineList(surface.AffectedProjects)}");
        lines.Add(string.IsNullOrWhiteSpace(surface.TestCommand)
            ? "- Test command: none resolved"
            : $"- Test command: {surface.TestCommand}");
        lines.Add($"- Prioritized tests: {FormatInlineList(surface.PrioritizedTests.Take(4))}");
        lines.Add($"- Call-chain impact: {FormatInlineList(surface.CallChainImpact.Take(4))}");
        lines.AddRange(surface.Notes.Count == 0 ? ["- Notes: none"] : surface.Notes.Select(note => $"- Note: {note}"));
    }

    private void AddReferenceGraphLines(List<string> lines, SemanticReferenceGraph graph, bool includeSymbols)
    {
        lines.Add("Reference graph:");
        lines.Add($"- Declarations: {graph.Declarations.Count}");
        lines.Add($"- References: {graph.References.Count}");
        lines.Add($"- Inbound callers: {graph.InboundCalls.Count}");
        lines.Add($"- Outbound callees: {graph.OutboundCalls.Count}");
        lines.Add($"- Reference files: {FormatInlineList(graph.ReferenceFiles.Take(8))}");
        if (includeSymbols)
        {
            lines.Add($"- Likely test symbols: {FormatInlineList(graph.TestSymbols.Take(8))}");
        }
    }

    private void AddSafeRefactorDetectorLines(
        List<string> lines,
        string goal,
        IReadOnlyList<string> candidateFiles,
        SemanticReferenceGraph graph)
    {
        var looksLikeRefactor = goal.Contains("rename", StringComparison.OrdinalIgnoreCase)
            || goal.Contains("move", StringComparison.OrdinalIgnoreCase)
            || goal.Contains("extract", StringComparison.OrdinalIgnoreCase)
            || goal.Contains("refactor", StringComparison.OrdinalIgnoreCase)
            || goal.Contains("split", StringComparison.OrdinalIgnoreCase);
        var protectedFiles = candidateFiles
            .Where(file => ClassifyFileRisk(file).StartsWith("Protected", StringComparison.OrdinalIgnoreCase))
            .Take(5)
            .ToList();
        lines.Add("Safe refactor detector:");
        lines.Add(looksLikeRefactor
            ? "- Refactor-shaped goal detected; prefer symbol-aware edits and update callers/tests together."
            : "- No broad refactor verb detected.");
        lines.Add($"- Reference coverage: {graph.Declarations.Count} declaration(s), {graph.References.Count} reference(s), {graph.InboundCalls.Count} inbound caller(s).");
        lines.Add(protectedFiles.Count == 0
            ? "- Protected/generated targets: none in current candidates."
            : $"- Protected/generated targets: {FormatInlineList(protectedFiles)}");
    }

    private static void AddAutonomousPreflightLines(
        List<string> lines,
        IReadOnlyList<string> candidateFiles,
        SemanticReferenceGraph graph,
        TestTargetRecommendation? testTarget,
        bool hasPendingPreview)
    {
        var protectedFiles = candidateFiles
            .Where(file => ClassifyFileRisk(file).StartsWith("Protected", StringComparison.OrdinalIgnoreCase))
            .Take(5)
            .ToList();
        lines.Add("Autonomous preflight:");
        lines.Add(candidateFiles.Count == 0
            ? "- Target resolved: Bad - no candidate files yet."
            : $"- Target resolved: Good - {candidateFiles.Count} candidate file(s).");
        lines.Add(protectedFiles.Count == 0
            ? "- Protected file check: Good - no generated/designer candidate."
            : $"- Protected file check: Review - {FormatInlineList(protectedFiles)}");
        lines.Add(graph.Declarations.Count > 0 || graph.References.Count > 0
            ? "- Semantic evidence: Good - symbol/reference evidence exists."
            : "- Semantic evidence: Needs review - no symbol/reference evidence resolved.");
        lines.Add(testTarget is null || string.IsNullOrWhiteSpace(testTarget.Command)
            ? "- Test target: Needs review - no targeted test command attached yet."
            : $"- Test target: Good - {testTarget.Command}");
        lines.Add(hasPendingPreview
            ? "- Patch preview: Review existing pending preview before creating another."
            : "- Patch preview: Required before any apply step.");
    }

    private IReadOnlyList<string> BuildSemanticPatchCheckLines(IReadOnlyList<string> paths)
    {
        var relativePaths = paths.Select(RelativeToWorkspace).ToList();
        var protectedFiles = relativePaths
            .Where(path => ClassifyFileRisk(path).StartsWith("Protected", StringComparison.OrdinalIgnoreCase))
            .Take(6)
            .ToList();
        var publicApiFiles = relativePaths
            .Where(path => path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase))
            .Where(path =>
            {
                var absolute = ToAbsoluteWorkspacePath(path);
                return !string.IsNullOrWhiteSpace(absolute)
                    && File.Exists(absolute)
                    && SafeReadText(absolute).Contains(" public ", StringComparison.Ordinal);
            })
            .Take(6)
            .ToList();
        var lines = new List<string>
        {
            protectedFiles.Count == 0
                ? "- Generated/designer guard: Good - no protected generated files in this patch."
                : $"- Generated/designer guard: Review - {FormatInlineList(protectedFiles)}",
            publicApiFiles.Count == 0
                ? "- Public API guard: no obvious public C# surface in changed files."
                : $"- Public API guard: Review callers and compatibility for {FormatInlineList(publicApiFiles)}",
            "- Ledger: patch preview must be shown again if old text or target files change."
        };
        var query = string.Join(" ", relativePaths
            .Select(Path.GetFileNameWithoutExtension)
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Distinct(StringComparer.OrdinalIgnoreCase));
        if (!string.IsNullOrWhiteSpace(query))
        {
            var graph = BuildSemanticReferenceGraph(query, BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000), 80);
            lines.AddRange(BuildCallChainImpactSummary(graph, paths).Take(4).Select(item => $"- Call-chain guard: {item}"));
        }

        return lines;
    }

    private string FormatCallEdge(CSharpCallEdge edge) =>
        $"- {edge.Caller} -> {edge.Callee} ({RelativeToWorkspace(edge.Path)}:{edge.LineNumber})";

    private List<EditTargetCandidate> RankEditTargetCandidates(
        IReadOnlyList<string> goalTerms,
        IReadOnlyList<SemanticSymbolHit> hits,
        IReadOnlyList<string> candidateFiles,
        IReadOnlyList<string> changedFiles)
    {
        var changedPaths = changedFiles
            .Select(ToAbsoluteWorkspacePath)
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var ranked = new List<EditTargetCandidate>();
        foreach (var file in candidateFiles.Where(File.Exists).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            var reasons = new List<string>();
            var score = 0;
            var relativePath = RelativeToWorkspace(file);
            var fileName = Path.GetFileNameWithoutExtension(file);
            var fileHits = hits
                .Where(hit => hit.Path.Equals(file, StringComparison.OrdinalIgnoreCase))
                .Select(hit => hit.Display)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(3)
                .ToList();

            if (fileHits.Count > 0)
            {
                score += 4 + fileHits.Count;
                reasons.Add("symbol hit " + string.Join(", ", fileHits));
            }

            if (changedPaths.Contains(file))
            {
                score += 5;
                reasons.Add("already changed");
            }

            var matchingTerms = goalTerms
                .Where(term => fileName.Contains(term, StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(3)
                .ToList();
            if (matchingTerms.Count > 0)
            {
                score += 3;
                reasons.Add("file name matches " + string.Join(", ", matchingTerms));
            }

            var text = SafeReadText(file);
            var contentTerms = goalTerms
                .Where(term => text.Contains(term, StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(3)
                .ToList();
            if (contentTerms.Count > 0)
            {
                score += 2;
                reasons.Add("content matches " + string.Join(", ", contentTerms));
            }

            if (reasons.Count == 0)
            {
                reasons.Add("workspace heuristic");
            }

            var confidence = score >= 8 ? "High" : score >= 4 ? "Medium" : "Low";
            ranked.Add(new EditTargetCandidate(relativePath, confidence, score, ClassifyFileRisk(relativePath), reasons));
        }

        return ranked
            .OrderByDescending(target => target.Score)
            .ThenBy(target => target.RelativePath, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private static string FormatEditTargetCandidate(EditTargetCandidate target) =>
        $"- {target.Confidence} {target.Score} - {target.RelativePath}: {target.Risk}; {string.Join("; ", target.Reasons.Take(3))}";
    private async Task<CodingToolResult> PlanSafeEditWorkflowAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var goal = CleanGoal(request.Query, "current change");
        var changedFiles = await ReadChangedFilesAsync(cancellationToken).ConfigureAwait(false);
        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var goalTerms = ExtractMeaningfulGoalTerms(goal).Take(8).ToList();
        var graph = BuildSemanticReferenceGraph(goal, workspace, 100);
        var hits = graph.Declarations
            .Concat(graph.References)
            .DistinctBy(hit => $"{hit.Display}|{hit.Path}|{hit.LineNumber}", StringComparer.Ordinal)
            .Take(12)
            .ToList();
        var candidateFiles = hits.Select(hit => hit.Path)
            .Concat(graph.ReferenceFiles.Select(ToAbsoluteWorkspacePath).Where(path => !string.IsNullOrWhiteSpace(path)).Select(path => path!))
            .Concat(changedFiles.Select(ToAbsoluteWorkspacePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        if (candidateFiles.Count == 0)
        {
            candidateFiles = SuggestLikelyFilesForGoal(goal)
                .Select(ToAbsoluteWorkspacePath)
                .Where(path => !string.IsNullOrWhiteSpace(path))
                .Select(path => path!)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList();
        }

        var testFiles = GetCSharpFiles()
            .Where(IsTestFile)
            .Where(file => goalTerms.Count == 0
                || goalTerms.Any(term => Path.GetFileName(file).Contains(term, StringComparison.OrdinalIgnoreCase)
                    || SafeReadText(file).Contains(term, StringComparison.OrdinalIgnoreCase)))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        if (testFiles.Count == 0 && candidateFiles.Count > 0)
        {
            var candidateNames = candidateFiles
                .Select(file => Path.GetFileNameWithoutExtension(file))
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .ToList();
            testFiles = GetCSharpFiles()
                .Where(IsTestFile)
                .Where(file => candidateNames.Any(name => Path.GetFileName(file).Contains(name, StringComparison.OrdinalIgnoreCase)
                    || SafeReadText(file).Contains(name, StringComparison.OrdinalIgnoreCase)))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList();
        }

        var primaryTarget = Directory.Exists(Policy.WorkspaceRoot) && TryFindPrimaryProjectOrSolution(Policy.WorkspaceRoot, out var primary)
            ? primary
            : Policy.WorkspaceRoot;
        var testTarget = await ResolveTestTargetRecommendationAsync(goal, cancellationToken).ConfigureAwait(false);
        var impactSurface = BuildEditImpactSurface(goalTerms, hits, candidateFiles, testTarget);
        var rankedTargets = RankEditTargetCandidates(goalTerms, hits, candidateFiles, changedFiles);
        var impactScore = BuildEditImpactScore(rankedTargets, hits, candidateFiles, testTarget);
        LoadPendingPatchPreviewIfNeeded();
        var hasPendingPreview = _lastPatchPreviewRequest is not null;
        var lines = new List<string>
        {
            "Safe edit workflow:",
            "No files were changed.",
            "Purpose: inspect, preview, approve, validate.",
            $"Goal: {goal}",
            hasPendingPreview ? "Pending patch preview: yes - review it before creating another." : "Pending patch preview: none",
            $"Changed files: {changedFiles.Count}",
            $"Candidate files: {candidateFiles.Count}",
            $"Likely tests: {testFiles.Count}",
            $"Edit impact score: {impactScore.Score}/100 ({impactScore.Confidence})",
            $"Edit impact reasons: {FormatInlineList(impactScore.Reasons)}",
            "Inspect first:"
        };
        lines.AddRange(hits.Count == 0 ? ["- no semantic symbol hits from goal terms"] : hits.Take(6).Select(FormatSemanticHit));
        lines.Add("Files to touch only if needed:");
        lines.AddRange(candidateFiles.Count == 0 ? ["- none found yet"] : candidateFiles.Select(file => $"- {RelativeToWorkspace(file)}: {ClassifyFileRisk(RelativeToWorkspace(file))}"));
        AddReferenceGraphLines(lines, graph, includeSymbols: true);
        AddEditImpactSurfaceLines(lines, impactSurface);
        AddSafeRefactorDetectorLines(lines, goal, candidateFiles.Select(RelativeToWorkspace).ToList(), graph);
        AddAutonomousPreflightLines(lines, candidateFiles.Select(RelativeToWorkspace).ToList(), graph, testTarget, hasPendingPreview);
        lines.Add("Autonomous validation plan:");
        lines.AddRange(BuildAutonomousValidationPlanRows(goal, GetProjectIndexStatus(), testTarget).Select(row => $"- {row}"));
        lines.Add("Edit target validation:");
        lines.Add(candidateFiles.Count == 0
            ? "- Needs review - no exact candidate files resolved."
            : $"- Good - {candidateFiles.Count} candidate file(s) resolved before patch preview.");
        lines.Add("Patch gate:");
        if (hasPendingPreview)
        {
            lines.Add("- show pending patch preview");
            lines.Add("- confirm apply last patch preview");
            lines.Add("- discard pending patch preview");
        }
        else
        {
            lines.Add("- resolve symbol <name> or read the exact file section first");
            lines.Add("- prepare a patch bundle with exact old text and new text");
            lines.Add("- preview patch bundle");
            lines.Add("- show pending patch preview");
            lines.Add("- confirm apply last patch preview");
        }

        lines.Add("Likely tests to run:");
        lines.AddRange(testFiles.Count == 0 ? ["- no obvious targeted test file found"] : testFiles.Select(file => $"- {RelativeToWorkspace(file)}"));
        lines.Add("Validation after apply:");
        lines.Add($"- show impacted tests {goal}");
        lines.Add($"- resolve test target {goal}");
        lines.Add($"- confirm dotnet build \"{primaryTarget}\"");
        if (!string.IsNullOrWhiteSpace(testTarget.Command))
        {
            lines.Add($"- {testTarget.Command}");
        }
        lines.Add("Commit gate:");
        lines.Add("- review current changes");
        lines.Add("- can i safely commit");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Safe edit workflow", Policy.WorkspaceRoot);
    }

    private async Task<CodingToolResult> MapCompilerDiagnosticAsync(CodingToolRequest request, CancellationToken cancellationToken)
    {
        var diagnostic = CleanGoal(request.Query, string.Empty);
        if (string.IsNullOrWhiteSpace(diagnostic) && _lastDotNetResult is not null)
        {
            diagnostic = _lastDotNetResult.Message;
        }

        if (string.IsNullOrWhiteSpace(diagnostic))
        {
            return new CodingToolResult(true, false, "Diagnostic mapper needs a compiler diagnostic or a recent build failure.", "Diagnostic mapper", Policy.WorkspaceRoot);
        }

        var parsed = ParseCompilerDiagnostic(diagnostic);
        var absolutePath = string.IsNullOrWhiteSpace(parsed.Path) ? null : ToAbsoluteWorkspacePath(parsed.Path);
        var symbolContext = absolutePath is not null && File.Exists(absolutePath)
            ? FindEnclosingSymbolAtLine(absolutePath, parsed.LineNumber)
            : null;
        var testQuery = BuildDiagnosticTestQuery(parsed, absolutePath, symbolContext);
        var testTarget = await ResolveTestTargetRecommendationAsync(testQuery, cancellationToken).ConfigureAwait(false);
        var workspace = BuildRoslynWorkspaceModel(GetCSharpFiles(), 2_000);
        var graph = BuildSemanticReferenceGraph(testQuery, workspace, 80);
        var candidates = BuildDiagnosticFixCandidates(parsed, diagnostic, absolutePath, symbolContext, testTarget);
        var primaryTarget = Directory.Exists(Policy.WorkspaceRoot) && TryFindPrimaryProjectOrSolution(Policy.WorkspaceRoot, out var primary)
            ? primary
            : Policy.WorkspaceRoot;
        var lines = new List<string>
        {
            "Compiler diagnostic mapper:",
            "No files were changed.",
            "Engine: diagnostic parser + Roslyn syntax context + ranked fix candidates",
            string.IsNullOrWhiteSpace(parsed.Code) ? "Code: unknown" : $"Code: {parsed.Code}",
            absolutePath is null ? "File: unknown" : $"File: {RelativeToWorkspace(absolutePath)}",
            parsed.LineNumber is null ? "Line: unknown" : $"Line: {parsed.LineNumber}",
            symbolContext is null ? "Nearest symbol: unknown" : $"Nearest symbol: {symbolContext}",
            "Ranked fix candidates:"
        };
        lines.AddRange(candidates.Count == 0 ? ["- none found"] : candidates.Select(FormatDiagnosticFixCandidate));
        AddReferenceGraphLines(lines, graph, includeSymbols: true);
        lines.Add("Likely fix lane:");
        AddKnownErrorGuidance(lines, string.IsNullOrWhiteSpace(parsed.Code) ? diagnostic : parsed.Code);
        lines.Add("Validation after fix:");
        lines.Add($"- show impacted tests {testQuery}");
        lines.Add($"- resolve test target {testQuery}");
        lines.Add($"- confirm dotnet build \"{primaryTarget}\"");
        if (!string.IsNullOrWhiteSpace(testTarget.Command))
        {
            lines.Add($"- {testTarget.Command}");
        }
        lines.Add("Next - inspect the top candidate, make the smallest exact edit, then run validation.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Diagnostic mapper", absolutePath ?? Policy.WorkspaceRoot, parsed.LineNumber);
    }

    private List<DiagnosticFixCandidate> BuildDiagnosticFixCandidates(
        CompilerDiagnosticInfo diagnostic,
        string diagnosticText,
        string? absolutePath,
        string? symbolContext,
        TestTargetRecommendation testTarget)
    {
        var candidates = new List<DiagnosticFixCandidate>();
        if (absolutePath is not null && File.Exists(absolutePath))
        {
            var target = diagnostic.LineNumber is null
                ? RelativeToWorkspace(absolutePath)
                : $"{RelativeToWorkspace(absolutePath)}:{diagnostic.LineNumber}";
            candidates.Add(new DiagnosticFixCandidate(
                "High",
                10,
                target,
                "compiler location",
                "inspect the exact line and surrounding symbol before editing"));
        }

        if (!string.IsNullOrWhiteSpace(symbolContext))
        {
            candidates.Add(new DiagnosticFixCandidate(
                "High",
                8,
                symbolContext,
                "nearest enclosing symbol",
                "prefer a local symbol-level fix over broad text replacement"));
        }

        var codeCandidate = BuildDiagnosticCodeCandidate(diagnostic.Code, diagnosticText);
        if (codeCandidate is not null)
        {
            candidates.Add(codeCandidate);
        }

        if (!string.IsNullOrWhiteSpace(testTarget.Command))
        {
            candidates.Add(new DiagnosticFixCandidate(
                "Medium",
                5,
                testTarget.TargetPath ?? Policy.WorkspaceRoot,
                "validation target",
                testTarget.Command));
        }

        return candidates
            .OrderByDescending(candidate => candidate.Score)
            .ThenBy(candidate => candidate.Target, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
    }

    private static DiagnosticFixCandidate? BuildDiagnosticCodeCandidate(string? code, string diagnosticText)
    {
        var query = string.IsNullOrWhiteSpace(code) ? diagnosticText : code;
        if (query.Contains("CS0103", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 7, "missing name/scope", "CS0103", "check typo, missing helper, wrong scope, or stale generated code");
        }

        if (query.Contains("CS0246", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 7, "missing type or namespace", "CS0246", "check using directives, project references, package references, or renamed types");
        }

        if (query.Contains("CS1061", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 7, "missing member", "CS1061", "check property/member name, extension namespace, or API version drift");
        }

        if (query.Contains("CS1002", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 7, "missing semicolon", "CS1002", "inspect the reported line; deterministic preview may be available from last failure");
        }

        if (query.Contains("CS1513", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 7, "missing closing brace", "CS1513", "inspect brace balance near the reported symbol; deterministic preview may be available from last failure");
        }

        if (query.Contains("NETSDK", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 6, "SDK/project configuration", "NETSDK", "check target framework, workload, runtime identifier, restore state, or SDK version");
        }

        if (query.Contains("NU", StringComparison.OrdinalIgnoreCase))
        {
            return new DiagnosticFixCandidate("Medium", 6, "NuGet/package configuration", "NU", "check package id/version, configured sources, restore state, and network permissions");
        }

        return null;
    }

    private string BuildDiagnosticTestQuery(CompilerDiagnosticInfo diagnostic, string? absolutePath, string? symbolContext)
    {
        if (absolutePath is not null && File.Exists(absolutePath))
        {
            return Path.GetFileNameWithoutExtension(absolutePath);
        }

        if (!string.IsNullOrWhiteSpace(symbolContext))
        {
            return symbolContext;
        }

        return string.IsNullOrWhiteSpace(diagnostic.Code) ? "compiler diagnostic" : diagnostic.Code;
    }

    private static string FormatDiagnosticFixCandidate(DiagnosticFixCandidate candidate) =>
        $"- {candidate.Confidence} {candidate.Score} - {candidate.Target}: {candidate.Reason}; {candidate.NextStep}";

    private CodingToolResult VerifyXamlBindings()
    {
        var xamlFiles = GetXamlFiles();
        var symbols = BuildRoslynSymbolIndex(GetCSharpFiles(), 10_000);
        var symbolNames = symbols.Select(symbol => symbol.Name).ToHashSet(StringComparer.Ordinal);
        var bindings = new List<(string Path, string Name)>();
        foreach (var file in xamlFiles)
        {
            foreach (var binding in ExtractXamlBindingNames(SafeReadText(file), commandOnly: false))
            {
                bindings.Add((file, binding));
            }
        }

        var unknown = bindings
            .Where(binding => !IsIgnoredBindingName(binding.Name))
            .Where(binding => !symbolNames.Contains(binding.Name))
            .DistinctBy(binding => RelativeToWorkspace(binding.Path) + "|" + binding.Name, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();
        var lines = new List<string>
        {
            "XAML binding check:",
            "No files were changed.",
            "Engine: XAML text scan + Roslyn C# symbol index",
            $"XAML files: {xamlFiles.Count}",
            $"Bindings found: {bindings.Count}",
            $"Unknown bindings: {unknown.Count}"
        };
        lines.AddRange(unknown.Count == 0 ? ["- Good - no unknown binding names found."] : unknown.Select(binding => $"- {RelativeToWorkspace(binding.Path)} -> {binding.Name}"));
        lines.Add("Note - dynamic DataContext, generated properties, and converter parameters may still need human review.");
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "XAML binding check", Policy.WorkspaceRoot);
    }

    private CodingToolResult VerifyCommandBindings()
    {
        var xamlFiles = GetXamlFiles();
        var symbols = BuildRoslynSymbolIndex(GetCSharpFiles(), 10_000);
        var symbolNames = symbols.Select(symbol => symbol.Name).ToHashSet(StringComparer.Ordinal);
        var symbolByName = symbols
            .GroupBy(symbol => symbol.Name, StringComparer.Ordinal)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.Ordinal);
        var commands = new List<(string Path, string Name)>();
        foreach (var file in xamlFiles)
        {
            foreach (var command in ExtractXamlBindingNames(SafeReadText(file), commandOnly: true))
            {
                commands.Add((file, command));
            }
        }

        var missing = commands
            .Where(command => !symbolNames.Contains(command.Name))
            .DistinctBy(command => RelativeToWorkspace(command.Path) + "|" + command.Name, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToList();
        var lines = new List<string>
        {
            "Command binding check:",
            "No files were changed.",
            "Engine: XAML command scan + Roslyn C# symbol index",
            $"Command bindings found: {commands.Count}",
            $"Missing command targets: {missing.Count}"
        };
        lines.AddRange(missing.Count == 0 ? ["- Good - all command binding names were found in code symbols."] : missing.Select(command => $"- {RelativeToWorkspace(command.Path)} -> {command.Name}"));
        lines.Add("Command/UI binding graph:");
        lines.AddRange(commands
            .DistinctBy(command => RelativeToWorkspace(command.Path) + "|" + command.Name, StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .Select(command =>
            {
                if (!symbolByName.TryGetValue(command.Name, out var symbol))
                {
                    return $"- {RelativeToWorkspace(command.Path)} -> {command.Name} -> missing";
                }

                return $"- {RelativeToWorkspace(command.Path)} -> {command.Name} -> {symbol.DisplayName} ({RelativeToWorkspace(symbol.Path)}:{symbol.LineNumber})";
            }));
        return new CodingToolResult(true, true, string.Join(Environment.NewLine, lines), "Command binding check", Policy.WorkspaceRoot);
    }

    private static IReadOnlyList<string> BuildRouteDriftRows(
        IReadOnlyList<string> missingService,
        IReadOnlyList<string> missingPolicy,
        IReadOnlyList<string> missingParserOrTests,
        IReadOnlyList<string> missingDashboardTargets)
    {
        var rows = new List<string>
        {
            missingService.Count == 0 ? "Service route: Good" : $"Service route: Bad - {missingService.Count} missing",
            missingPolicy.Count == 0 ? "Policy route: Good" : $"Policy route: Bad - {missingPolicy.Count} missing",
            missingParserOrTests.Count == 0 ? "Parser/test route: Good" : $"Parser/test route: Review - {missingParserOrTests.Count} missing",
            missingDashboardTargets.Count == 0 ? "Dashboard route: Good" : $"Dashboard route: Bad - {missingDashboardTargets.Count} missing"
        };
        return rows;
    }

    private void PersistRouteDiffTracker(
        int actionCount,
        IReadOnlyList<string> missingService,
        IReadOnlyList<string> missingPolicy,
        IReadOnlyList<string> missingParserOrTests,
        IReadOnlyList<string> missingDashboardTargets,
        IReadOnlyList<string> routeDriftRows,
        IReadOnlyList<string> routeRepairPackets)
    {
        var snapshot = new RouteDiffTrackerSnapshot(
            DateTimeOffset.UtcNow,
            Policy.WorkspaceRoot,
            actionCount,
            missingService.Take(50).ToList(),
            missingPolicy.Take(50).ToList(),
            missingParserOrTests.Take(50).ToList(),
            missingDashboardTargets.Take(50).ToList(),
            routeDriftRows,
            routeRepairPackets);
        Directory.CreateDirectory(Path.GetDirectoryName(_routeDiffTrackerPath)!);
        File.WriteAllText(_routeDiffTrackerPath, JsonSerializer.Serialize(snapshot, RoadmapJsonOptions));
    }
    private CodingToolResult ShowCommandSurfaceDoctor()
    {
        var servicePath = Path.Combine(Policy.WorkspaceRoot, "src", "Ali.Infrastructure", "Coding", "LocalCodingToolService.cs");
        var parserPath = Path.Combine(Policy.WorkspaceRoot, "src", "Ali.Core", "Coding", "CodingToolRequestParser.cs");
        var policyPath = Path.Combine(Policy.WorkspaceRoot, "src", "Ali.Core", "Coding", "CodingWorkspacePolicy.cs");
        var testsPath = Path.Combine(Policy.WorkspaceRoot, "tests", "Ali.Tests", "Program.cs");
        var dashboardPath = Path.Combine(Policy.WorkspaceRoot, "src", "Ali.App.Wpf", "ProgrammingDashboardWindow.xaml");
        var viewModelPath = Path.Combine(Policy.WorkspaceRoot, "src", "Ali.App.Wpf", "ViewModels", "MainWindowViewModel.cs");

        var serviceText = SafeReadText(servicePath);
        var parserText = SafeReadText(parserPath);
        var policyText = SafeReadText(policyPath);
        var testsText = SafeReadText(testsPath);
        var dashboardText = SafeReadText(dashboardPath);
        var viewModelText = SafeReadText(viewModelPath);
        var actions = Enum.GetNames<CodingToolAction>();
        var missingService = actions
            .Where(action => !serviceText.Contains($"CodingToolAction.{action}", StringComparison.Ordinal))
            .OrderBy(action => action, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var missingPolicy = actions
            .Where(action => !HasPolicyCoverage(action, policyText))
            .OrderBy(action => action, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var missingParserOrTests = actions
            .Where(action => !parserText.Contains($"CodingToolAction.{action}", StringComparison.Ordinal)
                && !testsText.Contains($"CodingToolAction.{action}", StringComparison.Ordinal))
            .OrderBy(action => action, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var dashboardCommands = ExtractXamlBindingNames(dashboardText, commandOnly: true)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var commandSymbols = BuildRoslynSymbolIndex([viewModelPath], 10_000)
            .Where(symbol => symbol.Name.EndsWith("Command", StringComparison.Ordinal))
            .ToDictionary(symbol => symbol.Name, symbol => symbol, StringComparer.Ordinal);
        var missingDashboardTargets = dashboardCommands
            .Where(command => !commandSymbols.ContainsKey(command)
                && !viewModelText.Contains($"ICommand {command}", StringComparison.Ordinal)
                && !viewModelText.Contains($" {command} {{ get; }}", StringComparison.Ordinal))
            .OrderBy(command => command, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var blockerCount = missingService.Count + missingPolicy.Count + missingDashboardTargets.Count;
        var reviewCount = missingParserOrTests.Count;
        var routeDriftRows = BuildRouteDriftRows(missingService, missingPolicy, missingParserOrTests, missingDashboardTargets);
        var routeRepairPackets = BuildRouteRepairPacketRows(missingService, missingPolicy, missingParserOrTests, missingDashboardTargets);
        PersistRouteDiffTracker(actions.Length, missingService, missingPolicy, missingParserOrTests, missingDashboardTargets, routeDriftRows, routeRepairPackets);
        var lines = new List<string>
        {
            "Command surface doctor:",
            "No files were changed.",
            blockerCount == 0 ? "Overall: Good" : $"Overall: Bad - {blockerCount} command-surface blocker(s)",
            $"Actions: {actions.Length}",
            missingService.Count == 0 ? "Service handlers: Good" : $"Service handlers: Bad - {missingService.Count} missing action reference(s)",
            missingPolicy.Count == 0 ? "Policy coverage: Good" : $"Policy coverage: Bad - {missingPolicy.Count} uncovered action(s)",
            missingParserOrTests.Count == 0 ? "Parser/test coverage: Good" : $"Parser/test coverage: Needs review - {reviewCount} action(s) lack direct parser or test references",
            missingDashboardTargets.Count == 0 ? "Dashboard bindings: Good" : $"Dashboard bindings: Bad - {missingDashboardTargets.Count} missing target(s)",
            $"Route diff tracker: {_routeDiffTrackerPath}",
            "Route drift rows:",
            "Route repair packets:",
            "Dashboard summary rows:",
            $"- Service handlers: {(missingService.Count == 0 ? "Good" : "Bad")}",
            $"- Policy coverage: {(missingPolicy.Count == 0 ? "Good" : "Bad")}",
            $"- Parser/test coverage: {(missingParserOrTests.Count == 0 ? "Good" : "Review")}",
            $"- Dashboard bindings: {(missingDashboardTargets.Count == 0 ? "Good" : "Bad")}",
            "Service gaps:"
        };
        lines.InsertRange(lines.IndexOf("Route repair packets:"), routeDriftRows.Select(row => $"- {row}"));
        lines.InsertRange(lines.IndexOf("Dashboard summary rows:"), routeRepairPackets.Select(row => $"- {row}"));
        lines.AddRange(missingService.Count == 0 ? ["- none"] : missingService.Take(20).Select(action => $"- {action}"));
        lines.Add("Policy gaps:");
        lines.AddRange(missingPolicy.Count == 0 ? ["- none"] : missingPolicy.Take(20).Select(action => $"- {action}"));
        lines.Add("Parser/test review:");
        lines.AddRange(missingParserOrTests.Count == 0 ? ["- none"] : missingParserOrTests.Take(20).Select(action => $"- {action}"));
        lines.Add("Dashboard gaps:");
        lines.AddRange(missingDashboardTargets.Count == 0 ? ["- none"] : missingDashboardTargets.Take(20).Select(command => $"- {command}"));
        lines.Add("Dashboard command graph:");
        lines.AddRange(dashboardCommands.Count == 0
            ? ["- none"]
            : dashboardCommands.Take(20).Select(command =>
            {
                if (!commandSymbols.TryGetValue(command, out var symbol))
                {
                    return $"- {command} -> missing";
                }

                return $"- {command} -> {symbol.DisplayName} ({RelativeToWorkspace(symbol.Path)}:{symbol.LineNumber})";
            }));
        return new CodingToolResult(true, blockerCount == 0, string.Join(Environment.NewLine, lines), "Command surface doctor", Policy.WorkspaceRoot);
    }

    private static bool HasPolicyCoverage(string action, string policyText)
    {
        if (policyText.Contains($"CodingToolAction.{action}", StringComparison.Ordinal))
        {
            return true;
        }

        return action is nameof(CodingToolAction.Build)
            or nameof(CodingToolAction.Test)
            or nameof(CodingToolAction.Restore)
            or nameof(CodingToolAction.RunProject)
            or nameof(CodingToolAction.GitStatus)
            or nameof(CodingToolAction.GitDiff)
            or nameof(CodingToolAction.GitLog)
            or nameof(CodingToolAction.GitAdd)
            or nameof(CodingToolAction.GitCommit)
            or nameof(CodingToolAction.GitMerge)
            or nameof(CodingToolAction.GitPull)
            or nameof(CodingToolAction.GitPush)
            or nameof(CodingToolAction.OpenFile)
            or nameof(CodingToolAction.OpenSolution)
            or nameof(CodingToolAction.SearchWorkspace)
            or nameof(CodingToolAction.ReadFile)
            or nameof(CodingToolAction.CreateFile)
            or nameof(CodingToolAction.AppendFile)
            or nameof(CodingToolAction.ReplaceText)
            or nameof(CodingToolAction.PreviewReplaceText)
            or nameof(CodingToolAction.AddPackage)
            or nameof(CodingToolAction.ListPackages)
            or nameof(CodingToolAction.ListOutdatedPackages);
    }
